DG.put("ath-pakhyaan-charitr-likhyate/266",{"n":266,"title":null,"title_roman":null,"page":2085,"blocks":[{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2085,"meaning_status":"draft","meaning_pa":"ਚੌਪਈ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[1],"number_text":"੧।","page":2085,"lines":[{"gurmukhi":"ਸੁਮਤਿ ਸੈਨ ਇਕ ਨ੍ਰਿਪਤਿ ਸੁਨਾ ਬਰ। ਦੁਤਿਯ ਦਿਵਾਕਰ ਕਿਧੌ ਕਿਰਨਿਧਰ।","roman":"Sumti sain ik nripti sunaa bar | dutiy divaakar kidhau kirnidhar |","meaning_en":"There was a fine king named Sumati Sain, a second sun, or else a bearer of rays;","page":2085,"meaning_status":"draft","meaning_pa":"ਸੁਮਤਿ ਸੈਨ ਨਾ ਦਾ ਇਕ ਮਹਾਨ ਰਾਜਾ ਸੁਣੀਂਦਾ ਸੀ। (ਇੰਜ ਪ੍ਰਤੀਤ ਹੁੰਦਾ ਸੀ) ਕਿਤੇ ਦੂਜਾ ਸੂਰਜ ਜਾ ਚੰਦ੍ਰਮਾ ਹੋਵੇ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਸਮਰ ਮਤੀ ਰਾਨੀ ਗ੍ਰਿਹ ਤਾ ਕੇ। ਸੁਰੀ ਆਸੁਰੀ ਸਮ ਨਹਿ ਜਾ ਕੇ। ੧।","roman":"Samar matee raanee grih taa ke | suree aasuree sam nahi jaa ke | 1 |","meaning_en":"Samar Mati was his queen at home; no goddess or demoness was equal to her.","page":2085,"meaning_status":"draft","meaning_pa":"ਉਸ ਦੇ ਘਰ ਸਮਰ ਮਤੀ ਨਾ ਦੀ ਰਾਣੀ ਸੀ ਜਿਸ ਵਰਗੀਆਂ ਦੇਵ ਇਸਤਰੀਆਂ ਤੇ ਮਨੁੱਖ ਇਸਤਰੀਆਂ ਨਹੀਂ ਸਨ ॥੧॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[2],"number_text":"੨।","page":2085,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਰਨਖੰਭ ਕਲਾ ਦੁਹਿਤਾ ਤਿਹ। ਜੀਤਿ ਲਈ ਸਸਿ ਅੰਸ ਕਲਾ ਜਿਹ।","roman":"Sree rankhanbh kalaa duhitaa tih | jeeti laee sasi ans kalaa jih |","meaning_en":"His daughter was Sri Ranakhambh Kala, who had won away the moon's portion and phase;","page":2085,"meaning_status":"draft","note":"ਰਨਖੰਭ ਕਲਾ: taken as a personal name; uncertain.","meaning_pa":"ਉਨ੍ਰਹਾ ਦੀ ਰਨਖੰਭ ਕਲਾ (ਨਾ ਦੀ ਇਕ) ਧੀ ਸੀ ਜਿਸ ਨੇ ਚੰਦ੍ਰਮਾ ਦੀਆਂ ਕਲਾਵਾ ਨੂੰ ਜਿਤ ਲਿਆ ਸੀ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਨਿਰਖਿ ਭਾਨ ਜਿਹਾ ਪ੍ਰਭਾ ਰਹਤ ਦਬਿ। ਸੁਰੀ ਆਸੁਰਿਨ ਕੀ ਨਹਿ ਸਮ ਛਬਿ। ੨।","roman":"Nirkhi bhaan jihaa prabhaa rahat dabi | suree aasurin kee nahi sam chhabi | 2 |","meaning_en":"seeing her, the sun's radiance stays suppressed; the beauty of goddesses and demonesses is no match for hers.","page":2085,"meaning_status":"draft","note":"ਭਾਨ ਜਿਹਾ: printed so; read as 'bhan jih' (whose light, the sun's).","meaning_pa":"ਜਿਸ ਦੀ ਸੁੰਦਰਤਾ ਨੂੰ ਵੇਖ ਕੇ ਸੂਰਜ ਵੀ ਦਬਿਆ ਦਬਿਆ ਰਹਿੰਦਾ ਸੀ। ਦੇਵ ਇਸਤਰੀਆਂ ਅਤੇ ਦੈਂਤ ਇਸਤਰੀਆਂ ਦੀ ਸੁੰਦਰਤਾ ਵੀ (ਉਸ ਦੇ) ਸਮਾਨ ਨਹੀਂ ਸੀ ॥੨॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2085,"meaning_status":"draft","meaning_pa":"ਦੋਹਰਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[3],"number_text":"੩।","page":2085,"lines":[{"gurmukhi":"ਤਰੁਨਿ ਭਈ ਤਰੁਨੀ ਜਬੈ ਅਧਿਕ ਸੁਖਨ ਕੇ ਸੰਗ।","roman":"Taruni bhaee tarunee jabai adhik sukhan ke sang |","meaning_en":"When the girl became a young woman, amid abundant pleasures,","page":2085,"meaning_status":"draft","meaning_pa":"ਜਦ ਰਾਜ ਕੁਮਾਰੀ ਬਹੁਤ ਸੁਖਾ ਨਾਲ ਪਲ ਕੇ ਵੱਡੀ ਹੋ ਗਈ","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਲਰਿਕਾਪਨ ਮਿਟਿ ਜਾਤ ਭਯੋ ਦੁੰਦਭਿ ਦਿਯੋ ਅਨੰਗ। ੩।","roman":"Larikaapan miti jaat bhayo dundbhi diyo anang | 3 |","meaning_en":"her childhood came to an end, and Cupid beat his drum.","page":2085,"meaning_status":"draft","meaning_pa":"ਤਦ ਉਸ ਦਾ ਬਚਪਨਾ ਖ਼ਤਮ ਹੋ ਗਿਆ ਅਤੇ ਕਾਮ ਦੇਵ ਨੇ ਨਗਾਰਾ ਵਜਾ ਦਿੱਤਾ (ਭਾਵ ਭਰ ਜਵਾਨ ਹੋ ਗਈ) ॥੩॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2085,"meaning_status":"draft","meaning_pa":"ਚੌਪਈ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[4],"number_text":"੪।","page":2085,"lines":[{"gurmukhi":"ਚਾਰਿ ਭ੍ਰਾਤ ਤਾ ਕੇ ਬਲਵਾਨਾ। ਸੂਰਬੀਰ ਸਭ ਸਸਤ੍ਰ ਨਿਧਾਨਾ।","roman":"Chaari bhraat taa ke balvaanaa | soorbeer sabh sasatr nidhaanaa |","meaning_en":"She had four strong brothers, brave warriors, all treasuries of weapons;","page":2085,"meaning_status":"draft","meaning_pa":"ਉਸ ਦੇ ਚਾਰ ਬਹੁਤ ਬਲਵਾਨ ਭਰਾ ਸਨ। (ਉਹ) ਸਾਰੇ ਸ਼ੂਰਵੀਰ ਅਤੇ ਸ਼ਸਤ੍ਰ ਵਿਦਿਆ ਦੇ ਧਨੀ ਸਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਤੇਜਵਾਨ ਦੁਤਿਮਾਨ ਅਤੁਲ ਬਲ। ਅਰਿ ਅਨੇਕ ਜੀਤੇ ਜਿਹ ਦਲਿ ਮਲਿ। ੪।","roman":"Tejvaan dutimaan atul bal | ari anek jeete jih dali mali | 4 |","meaning_en":"radiant, splendid, of matchless strength, who had crushed many enemies with their armies.","page":2085,"meaning_status":"draft","meaning_pa":"(ਉਹ) ਬਹੁਤ ਤੇਜਵਾਨ, ਸੁੰਦਰ ਅਤੇ ਅਦੁੱਤੀ ਬਲ ਵਾਲੇ ਸਨ। ਉਨ੍ਰਹਾ ਨੇ ਅਨੇਕ ਵੈਰੀਆਂ ਨੂੰ ਮਸਲ ਕੇ ਜਿਤ ਲਿਆ ਸੀ ॥੪॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[5],"number_text":"੫।","page":2085,"lines":[{"gurmukhi":"ਸਾਰਦੂਲ ਧੁਜ ਨਾਹਰ ਧੁਜ ਭਨ। ਸਿੰਘ ਕੇਤੁ ਹਰਿ ਕੇਤੁ ਮਹਾ ਮਨ।","roman":"Saardool dhuj naahar dhuj bhan | singh ketu hari ketu mahaa man |","meaning_en":"They were called Sardul Dhuj, Nahar Dhuj, Singh Ketu and Hari Ketu of great mind;","page":2085,"meaning_status":"draft","note":"Names taken from the Gurmukhi: Sardul Dhuj, Nahar Dhuj, Singh Ketu, Hari Ketu.","meaning_pa":"ਸਾਰਦੂਲ ਧੁਜ, ਨਾਹਰ ਧੁਜ, ਸਿੰਘ ਕੇਤੁ ਅਤੇ ਹਰਿ ਕੇਤੁ ਨਾ ਵਾਲੇ ਬਹੁਤ ਮਹਾਨ ਸਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਚਾਰੌ ਸੂਰਬੀਰ ਬਲਵਾਨਾ। ਮਾਨਤ ਸਤ੍ਰੁ ਸਕਲ ਜਿਹ ਆਨਾ। ੫।","roman":"Chaarau soorbeer balvaanaa | maanat satru sakal jih aanaa | 5 |","meaning_en":"all four were strong brave warriors, whose command every enemy obeyed.","page":2085,"meaning_status":"draft","note":"ਆਨਾ: read as 'command' (aan).","meaning_pa":"ਉਹ ਚਾਰੇ ਸੂਰਮੇ ਬਹੁਤ ਬਲਵਾਨ ਸਨ। ਉਨ੍ਰਹਾ ਦੀ ਅਧੀਨਗੀ ਨੂੰ ਸਾਰੇ ਵੈਰੀ ਮੰਨਦੇ ਸਨ ॥੫॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[6],"number_text":"੬।","page":2085,"lines":[{"gurmukhi":"ਚਾਰੌ ਕੁਅਰਿ ਪੜਨ ਕੇ ਕਾਜਾ। ਦਿਜ ਇਕ ਬੋਲਿ ਪਠਾਯੋ ਰਾਜਾ।","roman":"Chaarau kuari paran ke kaajaa | dij ik boli pathaayo raajaa |","meaning_en":"For the four princes to study, the king sent for a brahmin;","page":2085,"meaning_status":"draft","meaning_pa":"ਚੌਹਾ ਰਾਜ ਕੁਮਾਰਾ ਨੂੰ ਪੜ੍ਰਹਾਉਣ ਲਈ ਰਾਜੇ ਨੇ ਇਕ ਬ੍ਰਾਹਮਣ ਨੂੰ ਬੁਲਾ ਲਿਆ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਭਾਖ੍ਯਾਦਿਕ ਬ੍ਯਾਕਰਨ ਪੜੇ ਜਿਨ। ਔਗਾਹਨ ਸਭ ਕਿਯ ਪੁਰਾਨ ਤਿਨ। ੬।","roman":"Bhaakhyaadik byaakran pare jin | augaahan sabh kiy puraan tin | 6 |","meaning_en":"he had studied the vernacular and grammar, and had fathomed all the Puranas.","page":2085,"meaning_status":"draft","note":"ਭਾਖ੍ਯਾਦਿਕ: read as 'bhakhya (the spoken language) and the like'; uncertain.","meaning_pa":"ਜਿਸ ਨੇ ਭਾਸ਼੍ਰਯ, ਵਿਆਕਰਣ ਆਦਿ ਪੜ੍ਰਹੇ ਹੋਏ ਸਨ ਅਤੇ ਜਿਸ ਨੇ ਸਾਰਿਆਂ ਪੁਰਾਣਾ ਦਾ ਅਧਿਐਨ ਕੀਤਾ ਹੋਇਆ ਸੀ ॥੬॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[7],"number_text":"੭।","page":2085,"lines":[{"gurmukhi":"ਅਧਿਕ ਦਰਬ ਨ੍ਰਿਪ ਬਰ ਤਿਹ ਦੀਯਾ। ਬਿਬਿਧ ਬਿਧਨ ਕਰਿ ਆਦਰ ਕੀਯਾ।","roman":"Adhik darab nrip bar tih deeyaa | bibidh bidhan kari aadar keeyaa |","meaning_en":"The king gave him great wealth and honoured him in many ways;","page":2085,"meaning_status":"draft","meaning_pa":"ਮਹਾਨ ਰਾਜੇ ਨੇ ਉਸ ਨੂੰ ਬਹੁਤ ਧਨ ਦਿੱਤਾ ਅਤੇ ਬਹੁਤ ਤਰ੍ਰਹਾ ਨਾਲ ਮਾਣ ਸਤਿਕਾਰ ਕੀਤਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਸੁਤਾ ਸਹਿਤ ਸੌਪੇ ਸੁਤ ਤਿਹ ਘਰ। ਕਛੁ ਬਿਦ੍ਯਾ ਦਿਜਿ ਦੇਹੁ ਕ੍ਰਿਪਾ ਕਰਿ। ੭।","roman":"Sutaa sahit saupe sut tih ghar | kachhu bidyaa diji dehu kripaa kari | 7 |","meaning_en":"he entrusted to his house the sons along with the daughter: 'Kindly give them some learning, brahmin.'","page":2085,"meaning_status":"draft","meaning_pa":"ਪੁੱਤਰੀ ਸਮੇਤ ਚਾਰੇ ਪੁੱਤਰ ਉਸ ਦੇ ਘਰ ਭੇਜ ਦਿੱਤੇ ਅਤੇ ਕਿਹਾ, ਹੇ ਸ੍ਰੇਸ਼ਠ ਪੰਡਿਤ! ਮਿਹਰਬਾਨੀ ਕਰ ਕੇ ਇਨ੍ਰਹਾ ਨੂੰ ਕੁਝ ਵਿਦਿਆ ਦਾ ਦਾਨ ਦਿਓ ॥੭॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[8],"number_text":"੮।","page":2085,"lines":[{"gurmukhi":"ਜਬ ਤੇ ਤਹ ਪੜਬੇ ਕਹ ਆਵੈ। ਅਪਨੋ ਬਿਪ ਕਹ ਸੀਸ ਝੁਕਾਵੈ।","roman":"Jab te tah parbe kah aavai | apno bip kah sees jhukaavai |","meaning_en":"From the time they came there to study, they bowed their heads to their brahmin.","page":2085,"meaning_status":"draft","meaning_pa":"ਜਦ ਉਹ ਉਥੇ ਪੜ੍ਰਹਨ ਲਈ ਆਉਾਂਦੇ ਤਾ ਆਪਣਾ ਸਿਰ ਬ੍ਰਾਹਮਣ ਅਗੇ ਝੁਕਾਉਾਂਦੇ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜੋ ਸਿਖ੍ਯਾ ਦਿਜ ਦੇਤ ਸੁ ਲੇਹੀ। ਅਮਿਤ ਦਰਬ ਪੰਡਿਤ ਕਹ ਦੇਹੀ। ੮।","roman":"Jo sikhyaa dij det su lehee | amit darab pandit kah dehee | 8 |","meaning_en":"Whatever teaching the brahmin gave they took in, and they gave the pandit boundless wealth.","page":2085,"meaning_status":"draft","meaning_pa":"ਜੋ ਸਿਖਿਆ ਬ੍ਰਾਹਮਣ ਦਿੰਦਾ ਸੀ, ਉਹੀ ਪ੍ਰਾਪਤ ਕਰਦੇ ਸਨ ਅਤੇ ਬ੍ਰਾਹਮਣ ਨੂੰ ਬਹੁਤ ਧਨ ਦਿੰਦੇ ਸਨ ॥੮॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[9],"number_text":"੯।","page":2085,"lines":[{"gurmukhi":"ਇਕ ਦਿਨ ਕੁਅਰਿ ਅਗਮਨੋ ਗਈ। ਦਿਜ ਕਹ ਸੀਸ ਝੁਕਾਵਤ ਭਈ।","roman":"Ik din kuari agamno gaee | dij kah sees jhukaavat bhaee |","meaning_en":"One day the princess came, and bowed her head to the brahmin.","page":2085,"meaning_status":"draft","meaning_pa":"ਇਕ ਦਿਨ ਰਾਜ ਕੁਮਾਰੀ ਪਹਿਲਾ ਚਲੀ ਗਈ ਅਤੇ ਬ੍ਰਾਹਮਣ ਨੂੰ ਸਿਰ ਝੁਕਾਇਆ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਸਾਲਿਗ੍ਰਾਮ ਪੂਜਤ ਥਾ ਦਿਜਬਰ। ਭਾਤਿ ਭਾਤਿ ਤਿਹ ਸੀਸ ਨ੍ਯਾਇ ਕਰਿ। ੯।","roman":"Saaligraam poojat thaa dijbar | bhaati bhaati tih sees nyaai kari | 9 |","meaning_en":"The excellent brahmin was worshipping a Shaligram, bowing his head to it in many ways.","page":2085,"meaning_status":"draft","meaning_pa":"ਬ੍ਰਾਹਮਣ ਭਾਤ ਭਾਤ ਨਾਲ ਸਿਰ ਨਿਵਾ ਕੇ ਸਾਲਗ੍ਰਾਮ ਦੀ ਪੂਜਾ ਕਰ ਰਿਹਾ ਸੀ ॥੯॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[10],"number_text":"੧੦।","page":2087,"lines":[{"gurmukhi":"ਤਾ ਕੌ ਨਿਰਖਿ ਕੁਅਰਿ ਮੁਸਕਾਨੀ। ਸੋ ਪ੍ਰਤਿਮਾ ਪਾਹਨ ਪਹਿਚਾਨੀ।","roman":"Taa kau nirkhi kuari muskaanee | so pratimaa paahan pahichaanee |","meaning_en":"Seeing him, the princess smiled; she recognised the image as a stone.","page":2087,"meaning_status":"draft","meaning_pa":"ਉਸ ਨੂੰ ਵੇਖ ਕੇ ਰਾਜ ਕੁਮਾਰੀ ਹਸ ਪਈ ਅਤੇ ਉਸ ਮੂਰਤੀ ਨੂੰ ਪੱਥਰ ਸਮਝਿਆ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਤਾਹਿ ਕਹਾ ਪੂਜਤ ਕਿਹ ਨਮਿਤਿਹ। ਸਿਰ ਨਾਵਤ ਕਰ ਜੋਰਿ ਕਾਜ ਜਿਹ। ੧੦।","roman":"Taahi kahaa poojat kih namitih | sir naavat kar jori kaaj jih | 10 |","meaning_en":"She asked him: 'Whom do you worship, and for what purpose do you bow your head with joined hands?'","page":2087,"meaning_status":"draft","meaning_pa":"ਉਸ (ਬ੍ਰਾਹਮਣ) ਨੂੰ ਪੁੱਛਣ ਲਗੀ ਕਿ ਇਸ ਨੂੰ ਕਿਸ ਨਿਮਿਤ ਪੂਜ ਰਹੇ ਹੋ ਅਤੇ ਕਿਸ ਲਈ ਹੱਥ ਜੋੜ ਕੇ ਸਿਰ ਨਿਵਾ ਰਹੇ ਹੋ ॥੧੦॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"speaker","name":"ਦਿਜ ਬਾਚ","gurmukhi":"ਦਿਜ ਬਾਚ","roman":"Dij baach","meaning_en":"The brahmin said:","page":2087,"meaning_status":"draft","meaning_pa":"ਬ੍ਰਾਹਮਣ ਨੇ ਕਿਹਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[11],"number_text":"੧੧।","page":2087,"lines":[{"gurmukhi":"ਸਾਲਗ੍ਰਾਮ ਠਾਕੁਰ ਏ ਬਾਲਾ। ਪੂਜਤ ਜਿਨੈ ਬਡੇ ਨਰਪਾਲਾ।","roman":"Saalgraam thaakur e baalaa | poojat jinai bade narpaalaa |","meaning_en":"'Girl, this is the Shaligram Thakur, whom great kings worship.","page":2087,"meaning_status":"draft","meaning_pa":"ਹੇ ਰਾਜ ਕੁਮਾਰੀ! ਇਹ ਸਾਲਗ੍ਰਾਮ ਠਾਕੁਰ ਹੈ ਜਿਸ ਨੂੰ ਵੱਡੇ ਵੱਡੇ ਰਾਜੇ ਪੂਜਦੇ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਤੈ ਅਗ੍ਯਾਨ ਇਹ ਕਹਾ ਪਛਾਨੈ। ਪਰਮੇਸ੍ਵਰ ਕਹ ਪਾਹਨ ਜਾਨੈ। ੧੧।","roman":"Tai agyaan ih kahaa pachhaanai | parmesvar kah paahan jaanai | 11 |","meaning_en":"You, ignorant, what do you understand of this? You take God to be a stone.'","page":2087,"meaning_status":"draft","meaning_pa":"ਤੂੰ ਮੂਰਖ ਇਸ ਨੂੰ ਕੀ ਸਮਝੇਾਂ। ਪਰਮੇਸ਼੍ਵਰ ਨੂੰ ਪੱਥਰ ਸਮਝ ਰਹੀ ਹੈਂ ॥੧੧॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"speaker","name":"ਰਾਜਾ ਸੁਤ ਬਾਚ","gurmukhi":"ਰਾਜਾ ਸੁਤ ਬਾਚ","roman":"Raajaa sut baach","meaning_en":"The king's daughter said:","page":2087,"meaning_status":"draft","meaning_pa":"ਰਾਜ ਕੁਮਾਰੀ ਨੇ ਕਿਹਾ:","meaning_pa_source":"BaniDB"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":2087,"meaning_status":"draft","meaning_pa":"ਸਵੈਯਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[12],"number_text":"੧੨।","page":2087,"lines":[{"gurmukhi":"ਤਾਹਿ ਪਛਾਨਤ ਹੈ ਨ ਮਹਾ ਜੜ ਜਾ ਕੋ ਪ੍ਰਤਾਪ ਤਿਹੂੰ ਪੁਰ ਮਾਹੀ।","roman":"Taahi pachhaanat hai na mahaa jar jaa ko prataap tihoon pur maahee |","meaning_en":"'You do not recognise Him, utterly dull one, whose glory is in the three worlds;","page":2087,"meaning_status":"draft","meaning_pa":"ਹੇ ਮਹਾ ਮੂਰਖ! ਤੂੰ ਉਸ ਨੂੰ ਨਹੀਂ ਪਛਾਣਦਾ ਜਿਸ ਦਾ ਪ੍ਰਤਾਪ ਤਿੰਨਾ ਲੋਕਾ ਵਿਚ (ਪਸਰਿਆ ਹੋਇਆ) ਹੈ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਪੂਜਤ ਹੈ ਪ੍ਰਭੁ ਕੈ ਤਿਸ ਕੌ ਜਿਨ ਕੇ ਪਰਸੇ ਪਰਲੋਕ ਪਰਾਹੀ।","roman":"Poojat hai prabhu kai tis kau jin ke parse parlok paraahee |","meaning_en":"you worship as the Lord that thing by whose touch the other world is lost,","page":2087,"meaning_status":"draft","note":"ਪਰਾਹੀ: read as 'flees, is lost'; uncertain.","meaning_pa":"ਉਸ ਨੂੰ ਪ੍ਰਭੂ ਕਰ ਕੇ ਪੂਜਦਾ ਹੈਂ, ਜਿਸ ਦੇ ਪੂਜਣ ਨਾਲ ਪਰਲੋਕ (ਹੋਰ ਵੀ) ਦੂਰ ਹੋ ਜਾਦਾ ਹੈ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਪਾਪ ਕਰੋ ਪਰਮਾਰਥ ਕੈ ਜਿਹ ਪਾਪਨ ਤੇ ਅਤਿ ਪਾਪ ਡਰਾਹੀ।","roman":"Paap karo parmaarath kai jih paapan te ati paap daraahee |","meaning_en":"you commit sin in the name of charity, sins at which sin itself is very afraid;","page":2087,"meaning_status":"draft","meaning_pa":"ਪਰਮਾਰਥ ਲਈ ਪਾਪ ਕਰਦਾ ਹੈਂ, ਜਿਨ੍ਰਹਾ ਪਾਪਾ ਨੂੰ ਵੇਖ ਕੇ ਪਾਪ ਵੀ ਬਹੁਤ ਡਰਦੇ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਪਾਇ ਪਰੋ ਪਰਮੇਸ੍ਵਰ ਕੇ ਪਸੁ ਪਾਹਨ ਮੈ ਪਰਮੇਸ੍ਵਰ ਨਾਹੀ। ੧੨।","roman":"Paai paro parmesvar ke pasu paahan mai parmesvar naahee | 12 |","meaning_en":"you fall at the feet of the Lord, beast! In a stone there is no Lord.'","page":2087,"meaning_status":"draft","meaning_pa":"ਹੇ ਮੂਰਖ! ਪਰਮੇਸ਼੍ਵਰ ਦੇ ਪੈਰਾ ਵਿਚ ਪੈ, ਪੱਥਰਾ ਵਿਚ ਪਰਮਾਤਮਾ ਨਹੀਂ ਹੈ ॥੧੨॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਬਿਜੈ ਛੰਦ","gurmukhi":"ਬਿਜੈ ਛੰਦ","roman":"Bijai chhand","meaning_en":"Bijay metre.","page":2087,"meaning_status":"draft","note":"ਬਿਜੈ ਛੰਦ: Bijai chhand.","meaning_pa":"ਬਿਜੈ ਛੰਦ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[13],"number_text":"੧੩।","page":2087,"lines":[{"gurmukhi":"ਜੀਵਨ ਮੈ ਜਲ ਮੈ ਥਲ ਮੈ ਸਭ ਰੂਪਨ ਮੈ ਸਭ ਭੂਪਨ ਮਾਹੀ।","roman":"Jeevan mai jal mai thal mai sabh roopan mai sabh bhoopan maahee |","meaning_en":"'In life, in water, on land, in all forms, among all kings,","page":2087,"meaning_status":"draft","meaning_pa":"(ਉਹ ਪਰਮਾਤਮਾ) ਸਾਰਿਆਂ ਜੀਵਾ ਵਿਚ, ਜਲ ਵਿਚ, ਥਲ ਵਿਚ, ਸਭ ਰੂਪਾ ਵਿਚ ਅਤੇ ਸਾਰਿਆਂ ਰਾਜਿਆਂ ਵਿਚ,","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਸੂਰਜ ਮੈ ਸਸਿ ਮੈ ਨਭ ਮੈ ਜਹ ਹੇਰੌ ਤਹਾ ਚਿਤ ਲਾਇ ਤਹਾ ਹੀ।","roman":"Sooraj mai sasi mai nabh mai jah herau tahaa chit laai tahaa hee |","meaning_en":"in the sun, in the moon, in the sky, wherever I look and fix my mind, there He is;","page":2087,"meaning_status":"draft","meaning_pa":"ਸੂਰਜ ਵਿਚ, ਚੰਦ੍ਰਮਾ ਵਿਚ, ਆਕਾਸ਼ ਵਿਚ, ਜਿਥੇ ਵੇਖੋ, ਉਥੇ ਚਿਤ ਟਿਕਾਉਣ ਨਾਲ (ਪ੍ਰਾਪਤ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ)।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਪਾਵਕ ਮੈ ਅਰੁ ਪੌਨ ਹੂੰ ਮੈ ਪ੍ਰਿਥਵੀ ਤਲ ਮੈ ਸੁ ਕਹਾ ਨਹਿ ਜਾਹੀ।","roman":"Paavak mai aru paun hoon mai prithvee tal mai su kahaa nahi jaahee |","meaning_en":"in fire and in wind, on the surface of the earth, where is it that He does not go?","page":2087,"meaning_status":"draft","meaning_pa":"ਅਗਨੀ ਵਿਚ, ਪੌਣ ਵਿਚ, ਧਰਤੀ ਉਤੇ, (ਅਤੇ ਉਹ) ਕਿਹੜੀ ਥਾ ਤੇ ਨਹੀਂ ਹੈ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਬ੍ਯਾਪਕ ਹੈ ਸਭ ਹੀ ਕੇ ਬਿਖੈ ਕਛੁ ਪਾਹਨ ਮੈ ਪਰਮੇਸ੍ਵਵਰ ਨਾਹੀ। ੧੩।","roman":"Byaapak hai sabh hee ke bikhai kachhu paahan mai parmesvavar naahee | 13 |","meaning_en":"He pervades all; the Lord is not at all in a stone.'","page":2087,"meaning_status":"draft","note":"ਪਰਮੇਸ੍ਵਵਰ: printed so with a doubled letter; read as Parmeshwar, the Supreme Lord.","meaning_pa":"(ਉਹ) ਸਭ ਵਿਚ ਵਿਆਪਕ ਹੈ, ਬਸ ਪੱਥਰਾ ਵਿਚ ਪਰਮਾਤਮਾ ਨਹੀਂ ਹੈ ॥੧੩॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[14],"number_text":"੧੪।","page":2087,"lines":[{"gurmukhi":"ਕਾਗਜ ਦੀਪ ਸਭੈ ਕਰਿ ਕੈ ਅਰੁ ਸਾਤ ਸਮੁੰਦ੍ਰਨ ਕੀ ਮਸੁ ਕੈਯੈ।","roman":"Kaagaj deep sabhai kari kai aru saat samundran kee masu kaiyai |","meaning_en":"'Make all the continents paper and the seven seas ink,","page":2087,"meaning_status":"draft","meaning_pa":"ਸਾਰੇ ਦੀਪਾ (ਟਾਪੂਆਂ) ਨੂੰ ਕਾਗ਼ਜ਼ ਬਣਾ ਕੇ ਅਤੇ ਸੱਤ ਸਮੁੰਦਰਾ ਦੀ ਸਿਆਹੀ ਕਰ ਲਈਏ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਕਾਟਿ ਬਨਾਸਪਤੀ ਸਿਗਰੀ ਲਿਖਬੇ ਹੂੰ ਕੌ ਲੇਖਨਿ ਕਾਜ ਬਨੈਯੈ।","roman":"Kaati banaasaptee sigree likhbe hoon kau lekhni kaaj banaiyai |","meaning_en":"cut down all the plants and make them pens for writing,","page":2087,"meaning_status":"draft","meaning_pa":"ਸਾਰੀ ਬਨਸਪਤੀ ਨੂੰ ਕਟ ਕੇ ਲਿਖਣ ਲਈ ਕਲਮਾ ਬਣਾ ਲਈਏ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਸਾਰਸ੍ਵਤੀ ਬਕਤਾ ਕਰਿ ਕੈ ਸਭ ਜੀਵਨ ਤੇ ਜੁਗ ਸਾਠਿ ਲਿਖੈਯੈ।","roman":"Saarsvatee baktaa kari kai sabh jeevan te jug saathi likhaiyai |","meaning_en":"make Sarasvati the speaker, and have it written by all beings for sixty ages;","page":2087,"meaning_status":"draft","meaning_pa":"ਸਰਸਵਤੀ ਨੂੰ ਬੋਲਣ ਵਾਲਾ ਕਰ ਕੇ ਸਾਰਿਆਂ ਜੀਵਾ ਤੋਂ ਸਠ ਯੁਗਾ ਤਕ ਲਿਖਵਾਇਆ ਜਾਏ","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜੋ ਪ੍ਰਭੁ ਪਾਯੁਤ ਹੈ ਨਹਿ ਕੈਸੇ ਹੂੰ ਸੋ ਜੜ ਪਾਹਨ ਮੌ ਠਹਰੈਯੈ।੧੪।","roman":"Jo prabhu paayut hai nahi kaise hoon so jar paahan mau thahraiyai | 14 |","meaning_en":"the Lord, whom one does not find even so, you would lodge in a dull stone.'","page":2087,"meaning_status":"draft","meaning_pa":"(ਤਦ ਵੀ) ਜਿਸ ਪ੍ਰਭੂ ਨੂੰ ਕਿਸੇ ਤਰ੍ਰਹਾ ਪ੍ਰਾਪਤ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਦਾ, ਹੇ ਮੂਰਖ! ਉਸ ਨੂੰ ਪੱਥਰਾ ਵਿਚ ਸਥਿਤ ਕਰ ਰਿਹਾ ਹੈਂ ॥੧੪॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2087,"meaning_status":"draft","meaning_pa":"ਚੌਪਈ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[15],"number_text":"੧੫।","page":2087,"lines":[{"gurmukhi":"ਏ ਜਨ ਭੇਵ ਨ ਹਰਿ ਕੋ ਪਾਵੈ। ਪਾਹਨ ਮੈ ਹਰਿ ਕੌ ਠਹਰਾਵੈ।","roman":"E jan bhev na hari ko paavai | paahan mai hari kau thahraavai |","meaning_en":"'These people do not find the secret of Hari; they lodge Hari in a stone.","page":2087,"meaning_status":"draft","meaning_pa":"ਜੋ ਪੱਥਰ ਵਿਚ ਪਰਮਾਤਮਾ ਨੂੰ ਸਥਿਤ ਮੰਨਦਾ ਹੈ, ਉਹ ਵਿਅਕਤੀ ਪਰਮਾਤਮਾ ਦੇ ਭੇਦ ਨੂੰ ਨਹੀਂ ਸਮਝ ਸਕਦਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜਿਹ ਕਿਹ ਬਿਧਿ ਲੋਗਨ ਭਰਮਾਹੀ। ਗ੍ਰਿਹ ਕੋ ਦਰਬੁ ਲੂਟਿ ਲੈ ਜਾਹੀ। ੧੫।","roman":"Jih kih bidhi logan bharmaahee | grih ko darbu looti lai jaahee | 15 |","meaning_en":"By whatever means they delude people, and plunder the wealth of the house and go off.'","page":2087,"meaning_status":"draft","meaning_pa":"(ਉਹ) ਜਿਵੇਾਂ ਕਿਵੇਾਂ ਲੋਕਾ ਨੂੰ ਭਰਮਾਉਾਂਦਾ ਹੈ ਅਤੇ ਘਰ ਨੂੰ ਧਨ ਲੁਟ ਕੇ ਲੈ ਜਾਦਾ ਹੈ ॥੧੫॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2087,"meaning_status":"draft","meaning_pa":"ਦੋਹਰਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[16],"number_text":"੧੬।","page":2087,"lines":[{"gurmukhi":"ਜਗ ਮੈ ਆਪੁ ਕਹਾਵਈ ਪੰਡਿਤ ਸੁਘਰ ਸੁਚੇਤ।","roman":"Jag mai aapu kahaavaee pandit sughar suchet |","meaning_en":"'In the world you call yourself a pandit, skilled and wise;","page":2087,"meaning_status":"draft","meaning_pa":"ਜਗਤ ਵਿਚ (ਤੂੰ) ਆਪਣੇ ਆਪ ਨੂੰ ਵਿਦਵਾਨ, ਸੁਘੜ ਅਤੇ ਸਚੇਤ ਅਖਵਾਉਾਂਦਾ ਹੈਂ,","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਪਾਹਨ ਕੀ ਪੂਜਾ ਕਰੈ ਯਾ ਤੇ ਲਗਤ ਅਚੇਤ। ੧੬।","roman":"Paahan kee poojaa karai yaa te lagat achet | 16 |","meaning_en":"you worship a stone, and for this you appear unwise.'","page":2087,"meaning_status":"draft","meaning_pa":"ਪਰ ਪੱਥਰਾ ਦੀ ਪੂਜਾ ਕਰਦਾ ਹੈਂ, ਇਸ ਲਈ ਮੂਰਖ ਲਗਦਾ ਹੈਂ ॥੧੬॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2087,"meaning_status":"draft","meaning_pa":"ਚੌਪਈ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[17],"number_text":"੧੭।","page":2087,"lines":[{"gurmukhi":"ਚਿਤ ਭੀਤਰ ਆਸਾ ਧਨ ਧਾਰੈ। ਸਿਵ ਸਿਵ ਸਿਵ ਮੁਖ ਤੇ ਉਚਾਰੈ।","roman":"Chit bheetar aasaa dhan dhaarai | siv siv siv mukh te uchaarai |","meaning_en":"'He holds hope of wealth within his mind, and utters 'Shiv, Shiv, Shiv' from his mouth;","page":2087,"meaning_status":"draft","meaning_pa":"(ਤੂੰ) ਮਨ ਵਿਚ (ਧਨ ਆਦਿ ਦੀ) ਲਾਲਸਾ ਰਖਦਾ ਹੈਂ ਅਤੇ ਮੂੰਹੋਂ 'ਸ਼ਿਵ ਸ਼ਿਵ' ਦਾ ਉਚਾਰਨ ਕਰਦਾ ਹੈਂ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਅਧਿਕ ਡਿੰਭ ਕਰਿ ਜਗਿ ਦਿਖਾਵੈ। ਦ੍ਵਾਰ ਦ੍ਵਾਰ ਮਾਗਤ ਨ ਲਜਾਵੈ। ੧੭।","roman":"Adhik dinbh kari jagi dikhaavai | dvaar dvaar maagat na lajaavai | 17 |","meaning_en":"he displays great hypocrisy to the world, begs from door to door and is not ashamed.'","page":2087,"meaning_status":"draft","meaning_pa":"ਬਹੁਤ ਪਾਖੰਡ ਕਰ ਕੇ ਸੰਸਾਰ ਨੂੰ ਵਿਖਾਉਾਂਦਾ ਹੈਂ, ਪਰ ਦੁਆਰ ਦੁਆਰ ਉਤੇ ਮੰਗਣੋ ਸ਼ਰਮਾਉਾਂਦਾ ਨਹੀਂ ਹੈਂ ॥੧੭॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":2089,"meaning_status":"draft","meaning_pa":"ਅੜਿਲ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[18],"number_text":"੧੮।","page":2089,"lines":[{"gurmukhi":"ਨਾਕ ਮੂੰਦਿ ਕਰਿ ਚਾਰਿ ਘਰੀ ਠਾਢੇ ਰਹੈ।","roman":"Naak moondi kari chaari gharee thaadhe rahai |","meaning_en":"'Holding his nose shut, he stands for four ghari;","page":2089,"meaning_status":"draft","note":"ghari: a period of about 24 minutes.","meaning_pa":"ਨਕ ਨੂੰ ਬੰਦ ਕਰ ਕੇ ਚਾਰ ਘੜੀਆਂ ਤਕ ਖੜੋਤਾ ਰਹਿੰਦਾ ਹੈਂ","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਸਿਵ ਸਿਵ ਸਿਵ ਹ੍ਵੈ ਏਕ ਚਰਨ ਇਸਥਿਤ ਕਹੈ।","roman":"Siv siv siv hvai ek charan isthit kahai |","meaning_en":"standing on one foot, he says 'Shiv, Shiv, Shiv'.","page":2089,"meaning_status":"draft","meaning_pa":"ਅਤੇ ਇਕ ਚਰਨ ਉਤੇ ਟਿਕ ਕੇ 'ਸ਼ਿਵ ਸ਼ਿਵ' ਕਹਿੰਦਾ ਹੈਂ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜੋ ਕੋਊ ਪੈਸਾ ਏਕ ਦੇਤ ਕਰਿ ਆਇ ਕੈ।","roman":"Jo ko'oo paisaa ek det kari aai kai |","meaning_en":"If anyone comes and gives him a single paisa,","page":2089,"meaning_status":"draft","meaning_pa":"ਜੇ ਕੋਈ ਆ ਕੇ ਇਕ ਪੈਸਾ ਦਿੰਦਾ ਹੈ","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਹੋ ਦਾਤਨ ਲੇਤ ਉਠਾਇ ਸਿਵਹਿ ਬਿਸਰਾਇ ਕੈ। ੧੮।","roman":"Ho daatan let uthaai sivhi bisraai kai | 18 |","meaning_en":"he picks up the gift, forgetting Shiva.'","page":2089,"meaning_status":"draft","note":"ਦਾਤਨ: read as 'the gift/alms'; could also mean a tooth-stick; uncertain.","meaning_pa":"ਤਾ ਸ਼ਿਵ ਨੂੰ ਭੁਲਾ ਕੇ ਦੰਦਾ ਨਾਲ ਉਠਾ ਲੈਂਦਾ ਹੈਂ ॥੧੮॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"Kabitt.","page":2089,"meaning_status":"draft","meaning_pa":"ਕਬਿੱਤ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[19],"number_text":"੧੯।","page":2089,"lines":[{"gurmukhi":"ਔਰਨੁਪਦੇਸ ਕਰੈ ਆਪੁ ਧ੍ਯਾਨ ਕੌ ਨ ਧਰੈ","roman":"Aurnupdes karai aapu dhyaan kau na dharai","meaning_en":"'He instructs others while he himself does not hold to meditation;","page":2089,"meaning_status":"draft"},{"gurmukhi":"ਲੋਗਨ ਕੌ ਸਦਾ ਤ੍ਯਾਗ ਧਨ ਕੋ ਦ੍ਰਿੜਾਤ ਹੈ।","roman":"Logan kau sadaa tyaag dhan ko driraat hai |","meaning_en":"he always tells people to renounce, while he himself holds firmly to wealth.","page":2089,"meaning_status":"draft","meaning_pa":"ਹੋਰਾ ਨੂੰ ਉਪਦੇਸ਼ ਕਰਦਾ ਹੈਂ, ਪਰ ਆਪ ਧਿਆਨ ਨੂੰ ਧਾਰਨ ਨਹੀਂ ਕਰਦਾ ਹੈਂ ਅਤੇ ਲੋਕਾ ਨੂੰ ਸਦਾ ਧਨ ਦਾ ਤਿਆਗ ਦ੍ਰਿੜ੍ਰਹ ਕਰਾਉਾਂਦਾ ਹੈਂ।","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"},{"gurmukhi":"ਤੇਹੀ ਧਨ ਲੋਭ ਊਚ ਨੀਚਨ ਕੇ ਦ੍ਵਾਰ ਦ੍ਵਾਰ","roman":"Tehee dhan lobh ooch neechan ke dvaar dvaar","meaning_en":"In that same greed for wealth, at the doors of high and low,","page":2089,"meaning_status":"draft"},{"gurmukhi":"ਲਾਜ ਕੌ ਤਿਯਾਗ ਜੇਹੀ ਤੇਹੀ ਪੈ ਘਿਘਾਤ ਹੈ।","roman":"Laaj kau tiyaag jehee tehee pai ghighaat hai |","meaning_en":"giving up shame, he whines before whoever he meets.","page":2089,"meaning_status":"draft","note":"ਘਿਘਾਤ: read as 'whines, pleads'.","meaning_pa":"ਉਸ ਧਨ ਦੇ ਲੋਭ ਕਰ ਕੇ, ਊਚ ਨੀਚ ਦੇ ਦੁਆਰ ਦੁਆਰ ਤੇ ਸ਼ਰਮ ਨੂੰ ਤਿਆਗ ਕੇ ਹਰ ਕਿਸੇ ਅਗੇ ਗਿੜਗਿੜਾਉਾਂਦਾ ਫਿਰਦਾ ਹੈਂ।","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"},{"gurmukhi":"ਕਹਤ ਪਵਿਤ੍ਰ ਹਮ ਰਹਤ ਅਪਵਿਤ੍ਰ ਖਰੇ","roman":"Kahat pavitr ham rahat apvitr khare","meaning_en":"They call themselves pure, yet remain quite impure;","page":2089,"meaning_status":"draft"},{"gurmukhi":"ਚਾਕਰੀ ਮਲੇਛਨ ਕੀ ਕੈਕੈ ਟੂਕ ਖਾਤ ਹੈ।","roman":"Chaakree malechhan kee kaikai took khaat hai |","meaning_en":"they eat morsels, doing service to the mlechhas.","page":2089,"meaning_status":"draft","note":"ਮਲੇਛਨ: 'mlechhas' (foreigners/barbarians), as printed.","meaning_pa":"ਕਹਿੰਦਾ ਹੈਂ ਕਿ ਮੈਂ ਪਵਿਤ੍ਰ ਰਹਿੰਦਾ ਹਾ, (ਪਰ ਹੁੰਦਾ) ਬਹੁਤ ਅਪਵਿਤ੍ਰ ਹੈਂ (ਕਿਉਾਂਕਿ) ਮਲੇਛਾ ਦੀ ਨੌਕਰੀ ਕਰ ਕੇ ਟੁਕੜੇ ਖਾਉਾਂਦਾ ਹੈਂ।","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"},{"gurmukhi":"ਬਡੇ ਅਸੰਤੋਖੀ ਹੈ ਕਹਾਵਤ ਸੰਤੋਖੀ ਮਹਾ","roman":"Bade asantokhee hai kahaavat santokhee mahaa","meaning_en":"Very discontented, they call themselves greatly contented;","page":2089,"meaning_status":"draft"},{"gurmukhi":"ਏਕ ਦ੍ਵਾਰ ਛਾਡਿ ਮਾਗਿ ਦ੍ਵਾਰੇ ਦ੍ਵਾਰ ਜਾਤ ਹੈ। ੧੯।","roman":"Ek dvaar chhaadi maagi dvaare dvaar jaat hai | 19 |","meaning_en":"leaving one door they go begging from door to door.'","page":2089,"meaning_status":"draft","meaning_pa":"(ਤੂੰ) ਬਹੁਤ ਅਸੰਤੋਖੀ ਹੈਂ, (ਪਰ ਆਪਣੇ ਆਪ ਨੂੰ) ਵੱਡਾ ਸੰਤੋਖੀ ਅਖਵਾਉਾਂਦਾ ਹੈਂ (ਕਿਉਾਂਕਿ ਤੂੰ) ਪਰਮਾਤਮਾ ਦੇ ਇਕ ਦੁਆਰ ਨੂੰ ਛਡ ਕੇ ਦੁਆਰ ਦੁਆਰ ਉਤੇ ਮੰਗਦਾ ਫਿਰਦਾ ਹੈਂ ॥੧੯॥","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"}]},{"type":"verse","number":[20],"number_text":"੨੦।","page":2089,"lines":[{"gurmukhi":"ਮਾਟੀ ਕੇ ਸਿਵ ਬਨਾਏ ਪੂਜਿ ਕੈ ਬਹਾਇ ਆਏ","roman":"Maatee ke siv banaae pooji kai bahaai aae","meaning_en":"'They make Shivas of clay, worship them and float them away;","page":2089,"meaning_status":"draft"},{"gurmukhi":"ਆਇ ਕੈ ਬਨਾਏ ਫੇਰਿ ਮਾਟੀ ਕੇ ਸੁਧਾਰਿ ਕੈ।","roman":"Aai kai banaae pheri maatee ke sudhaari kai |","meaning_en":"coming back, they make them again of clay, shaping them well.","page":2089,"meaning_status":"draft","meaning_pa":"(ਤੂੰ) ਮਿੱਟੀ ਦੇ ਸ਼ਿਵ ਬਣਾ ਕੇ ਪੂਜ ਕੇ ਰੋੜ੍ਰਹ ਆਉਾਂਦਾ ਹੈਂ ਅਤੇ ਫਿਰ ਆ ਕੇ ਮਿੱਟੀ ਨੂੰ ਗੁੰਨ੍ਰਹ ਕੇ (ਹੋਰ) ਬਣਾਉਾਂਦਾ ਹੈਂ।","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"},{"gurmukhi":"ਤਾ ਕੇ ਪਾਇ ਪਰਿਯੋ ਮਾਥੋ ਘਰੀ ਦ੍ਵੈ ਰਗਰਿਯੋ","roman":"Taa ke paai pariyo maatho gharee dvai ragriyo","meaning_en":"They put their forehead at its feet and rub it for two ghari:","page":2089,"meaning_status":"draft"},{"gurmukhi":"ਐ ਰੇ ਤਾ ਮੈ ਕਹਾ ਹੈ ਰੇ ਦੈ ਹੈ ਤੋਹਿ ਕੌ ਬਿਚਾਰਿ ਕੈ।","roman":"Ai re taa mai kahaa hai re dai hai tohi kau bichaari kai |","meaning_en":"'Hey, what is in it? What will it give you, if you consider?","page":2089,"meaning_status":"draft","meaning_pa":"ਉਸ (ਮੂਰਤੀ) ਦੇ ਪੈਰੀਂ ਪੈਂਦਾ ਹੈਂ ਅਤੇ ਦੋ ਘੜੀਆਂ ਤਕ ਮੱਥੇ ਨੂੰ ਰਗੜਦਾ ਹੈਂ, ਓਏ (ਮੂਰਖ!) ਵਿਚਾਰ ਕਰ ਲੈ ਕਿ ਉਨ੍ਰਹਾ ਵਿਚ ਕੀ ਹੈ ਜੋ ਤੈਨੂੰ ਦੇਣਗੇ।","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"},{"gurmukhi":"ਲਿੰਗ ਕੀ ਤੂ ਪੂਜਾ ਕਰੈ ਸੰਭੁ ਜਾਨਿ ਪਾਇ ਪਰੈ","roman":"Ling kee too poojaa karai sanbhu jaani paai parai","meaning_en":"You worship the lingam and fall at its feet taking it as Shambhu;","page":2089,"meaning_status":"draft"},{"gurmukhi":"ਸੋਈ ਅੰਤ ਦੈਹੈ ਤੇਰੇ ਕਰ ਮੈ ਨਿਕਾਰਿ ਕੈ।","roman":"Soee ant daihai tere kar mai nikaari kai |","meaning_en":"in the end that very thing it will take out and give into your hand.","page":2089,"meaning_status":"draft","note":"Lines .5 to .7 are obscure and rendered as printed; uncertain.","meaning_pa":"ਤੂੰ (ਉਸ ਦੇ) ਲਿੰਗ ਦੀ ਪੂਜਾ ਕਰਦਾ ਹੈਂ ਅਤੇ ਸ਼ਿਵ ਸਮਝ ਕੇ ਪੈਰੀਂ ਪੈਂਦਾ ਹੈਂ। (ਫਿਰ) ਉਹੀ ਅੰਤ ਵਿਚ ਕਢ ਕੇ ਤੇਰੇ ਹੱਥ ਵਿਚ ਦੇਵੇਗਾ।","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"},{"gurmukhi":"ਦੁਹਿਤਾ ਕੌ ਦੈਹੈ ਕੀ ਤੂ ਆਪਨ ਖਬੈ ਹੈ ਤਾ ਕੌ","roman":"Duhitaa kau daihai kee too aapan khabai hai taa kau","meaning_en":"Will you give it to your daughter, or will you eat it yourself?","page":2089,"flags":[{"code":"ੇੈ","reason":"ੇ and ੈ typed on one letter; one covers the other, printed as ੈ"}],"meaning_status":"draft","note":"Taken as a crude jibe at the lingam; uncertain."},{"gurmukhi":"ਯੌ ਹੀ ਤੋਹਿ ਮਾਰਿ ਹੈ ਰੇ ਸਦਾ ਸਿਵ ਖ੍ਵਾਰਿ ਕੈ। ੨੦।","roman":"Yau hee tohi maari hai re sadaa siv khvaari kai | 20 |","meaning_en":"In just this way Shiva will kill you, always disgracing you.'","page":2089,"meaning_status":"draft","meaning_pa":"ਕੀ ਤੂੰ ਉਸ (ਲਿੰਗ) ਨੂੰ ਧੀ ਨੂੰ ਦੇਵੇਾਂਗਾ, ਜਾ ਉਸ ਨੂੰ ਆਪ ਖਾਏਾਂਗਾ। ਇਸ ਤਰ੍ਰਹਾ ਹੀ ਤੈਨੂੰ ਸਦਾ ਸ਼ਿਵ (ਪਰਮਾਤਮਾ) ਖੁਆਰ ਕਰ ਕੇ ਮਾਰੇਗਾ ॥੨੦॥","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"}]},{"type":"heading","kind":"chhand","name":"ਬਿਜੈ ਛੰਦ","gurmukhi":"ਬਿਜੈ ਛੰਦ","roman":"Bijai chhand","meaning_en":"Bijay metre.","page":2089,"meaning_status":"draft","meaning_pa":"ਬਿਜੈ ਛੰਦ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[21],"number_text":"੨੧।","page":2089,"lines":[{"gurmukhi":"ਪਾਹਨ ਕੌ ਸਿਵ ਤੂ ਜੋ ਕਹੈ ਪਸੁ ਯਾ ਤੇ ਕਛੁ ਤੁਹਿ ਹਾਥ ਨ ਐ ਹੈ।","roman":"Paahan kau siv too jo kahai pasu yaa te kachhu tuhi haath na ai hai |","meaning_en":"'If you call a stone Shiva, you beast, nothing will come into your hand from it.","page":2089,"meaning_status":"draft"},{"gurmukhi":"ਤ੍ਰੈਯਕ ਜੋਨਿ ਜੁ ਆਪੁ ਪਰਾ ਹਸਿ ਕੈ ਤੁਹਿ ਕੋ ਕਹੁ ਕਾ ਬਰੁ ਦੈ ਹੈ।","roman":"Traiyak joni ju aapu paraa hasi kai tuhi ko kahu kaa baru dai hai |","meaning_en":"One who himself has fallen into some threefold birth (or kind), laughing, what boon will he give you?","page":2089,"meaning_status":"draft","note":"ਤ੍ਰੈਯਕ ਜੋਨਿ: uncertain; read as 'a certain (threefold) species/birth'.","meaning_pa":"ਹੇ ਮੂਰਖ! ਤੂੰ ਜੋ ਪੱਥਰ ਨੂੰ ਸ਼ਿਵ ਕਹਿੰਦਾ ਹੈਂ, ਪਰ ਉਸ ਕੋਲੋਂ ਤੇਰੇ ਹੱਥ ਕੁਝ ਨਹੀਂ ਲਗਣਾ। ਜੋ ਆਪ ਟੇਢਾ ਚਲਣ ਵਾਲੀ ਜੂਨ ਵਿਚ ਪਿਆ ਹੋਇਆ ਹੈ, ਉਹ ਖ਼ੁਸ਼ ਹੋ ਕੇ ਤੈਨੂੰ ਕੀ ਵਰ ਦੇਵੇਗਾ।","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"},{"gurmukhi":"ਆਪਨ ਸੋ ਕਰਿ ਹੈ ਕਬਹੂੰ ਤੁਹਿ ਪਾਹਨ ਕੀ ਪਦਵੀ ਤਬ ਪੈ ਹੈ।","roman":"Aapan so kari hai kabhoon tuhi paahan kee padvee tab pai hai |","meaning_en":"Some day he will make you like himself, and then you will gain the rank of a stone.","page":2089,"meaning_status":"draft","meaning_pa":"ਤੈਨੂੰ ਕਿਤੇ ਆਪਣੇ ਵਰਗਾ ਕਰ ਦੇਵੇਗਾ, ਤਦ (ਤੂੰ) ਪੱਥਰ ਦੀ ਪਦਵੀ ਪਾਏਾਂਗਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜਾਨੁ ਰੇ ਜਾਨੁ ਅਜਾਨ ਮਹਾ ਫਿਰਿ ਜਾਨ ਗਈ ਕਛੁ ਜਾਨਿ ਨ ਜੈ ਹੈ। ੨੧।","roman":"Jaanu re jaanu ajaan mahaa phiri jaan gaee kachhu jaani na jai hai | 21 |","meaning_en":"Know, know, great ignoramus; when life has gone, nothing can be known.'","page":2089,"meaning_status":"draft","meaning_pa":"ਹੇ ਮਹਾ ਮੂਰਖ! ਸਮਝ ਲੈ। ਜੇ ਜਾਨ ਚਲੀ ਗਈ, ਫਿਰ ਤੂੰ ਕੁਝ ਵੀ ਜਾਣ ਨਹੀਂ ਸਕੇਾਂਗਾ ॥੨੧॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[22],"number_text":"੨੨।","page":2089,"lines":[{"gurmukhi":"ਬੈਸ ਗਈ ਲਰਿਕਾਪਨ ਮੋ ਤਰੁਨਾਪਨ ਮੈ ਨਹਿ ਨਾਮ ਲਯੋ ਰੇ।","roman":"Bais gaee larikaapan mo tarunaapan mai nahi naam layo re |","meaning_en":"'Your age passed in childhood, and in youth you did not take the Name.","page":2089,"meaning_status":"draft","meaning_pa":"ਓਏ! (ਪਹਿਲਾ ਤੇਰੀ) ਬਾਲਪਣੇ ਵਿਚ ਉਮਰ ਬੀਤ ਗਈ ਅਤੇ ਜਵਾਨੀ ਵਿਚ (ਤੂੰ) ਉਸ ਦਾ ਨਾਮ ਨਹੀਂ ਲਿਆ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਔਰਨ ਦਾਨ ਕਰਾਤ ਰਹਾ ਕਰ ਆਪ ਉਠਾਇ ਨ ਦਾਨ ਦਯੋ ਰੇ।","roman":"Auran daan karaat rahaa kar aap uthaai na daan dayo re |","meaning_en":"You made others give charity but did not rise and give charity yourself.","page":2089,"meaning_status":"draft","meaning_pa":"(ਤੂੰ) ਹੋਰਨਾ ਤੋਂ ਦਾਨ ਕਰਾਉਾਂਦਾ ਰਿਹਾ, ਪਰ ਆਪ ਹੱਥ ਚੁਕ ਕੇ ਕਿਸੇ ਨੂੰ ਦਾਨ ਨਹੀਂ ਦਿੱਤਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਪਾਹਨ ਕੋ ਸਿਰ ਨ੍ਯਾਤਨ ਤੈ ਪਰਮੇਸ੍ਵਰ ਕੌ ਸਿਰ ਨ੍ਯਾਤ ਭਯੋ ਰੇ।","roman":"Paahan ko sir nyaatan tai parmesvar kau sir nyaat bhayo re |","meaning_en":"You bowed your head to a stone, and did not bow your head to the Lord.","page":2089,"meaning_status":"draft","meaning_pa":"ਤੂੰ ਪੱਥਰ ਅਗੇ ਸਿਰ ਝੁਕਾ ਕੇ ਪਰਮੇਸ਼੍ਵਰ ਦੇ ਸਿਰ ਨੂੰ ਨੀਵਾ ਕਰ ਦਿੱਤਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਕਾਮਹਿ ਕਾਮ ਫਸਾ ਘਰ ਕੇ ਜੜ ਕਾਲਹਿ ਕਾਲ ਕੈ ਕਾਲ ਗਯੋ ਰੇ। ੨੨।","roman":"Kaamhi kaam phasaa ghar ke jar kaalhi kaal kai kaal gayo re | 22 |","meaning_en":"Entangled in desire upon desire, fool of the house, your time has passed in time upon time.'","page":2089,"meaning_status":"draft","note":"ਕਾਲਹਿ ਕਾਲ ਕੈ ਕਾਲ ਗਯੋ: read as 'time passed away in time upon time'; uncertain.","meaning_pa":"ਹੇ ਮੂਰਖ! (ਤੂੰ) ਘਰ ਦੇ ਕੰਮਾ ਵਿਚ ਹੀ ਫਸਿਆ ਰਿਹਾ ਅਤੇ ਕਲ੍ਰਹ ਕਲ੍ਰਹ ਕਰਦਿਆਂ ਸਮਾ ਬਤੀਤ ਕਰ ਦਿੱਤਾ ॥੨੨॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[23],"number_text":"੨੩।","page":2089,"lines":[{"gurmukhi":"ਦ੍ਵੈਕ ਪੁਰਾਨਨ ਕੌ ਪੜਿ ਕੈ ਤੁਮ ਫੂਲਿ ਗਏ ਦਿਜ ਜੂ ਜਿਯ ਮਾਹੀ।","roman":"Dvaik puraanan kau pari kai tum phooli gae dij joo jiy maahee |","meaning_en":"'Having read a couple of Puranas, you have swelled up in your mind, brahmin sir.","page":2089,"meaning_status":"draft","meaning_pa":"ਹੇ ਬ੍ਰਾਹਮਣ! ਤੂੰ ਦੋ ਕੁ ਪੁਰਾਣ ਪੜ੍ਰਹ ਕੇ ਮਨ ਵਿਚ ਫੁਲ ਗਿਆ ਹੈਂ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਸੋ ਨ ਪੁਰਾਨ ਪੜਾ ਜਿਹ ਕੇ ਇਹ ਠੌਰ ਪੜੇ ਸਭ ਪਾਪ ਪਰਾਹੀ।।","roman":"So na puraan paraa jih ke ih thaur pare sabh paap paraahee ||","meaning_en":"You have not read that Purana, by reading which in this place all sins flee.","page":2089,"meaning_status":"draft","note":"ਜਿਹ ਕੇ ਇਹ ਠੌਰ: read as 'by whose (reading) in this place'; uncertain.","meaning_pa":"ਪਰ ਉਹ ਪੁਰਾਣ ਨਹੀਂ ਪੜ੍ਰਹਿਆ, ਜਿਸ ਦੇ ਪੜ੍ਰਹਿਆਂ ਇਸ ਸੰਸਾਰ ਦੇ ਸਾਰੇ ਪਾਪ ਦੂਰ ਹੋ ਜਾਦੇ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਡਿੰਭ ਦਿਖਾਇ ਕਰੋ ਤਪਸਾ ਦਿਨ ਰੈਨਿ ਬਸੈ ਜਿਯਰਾ ਧਨ ਮਾਹੀ।","roman":"Dinbh dikhaai karo tapsaa din raini basai jiyraa dhan maahee |","meaning_en":"Displaying hypocrisy you practise austerity, while day and night your heart dwells on wealth;","page":2089,"meaning_status":"draft","meaning_pa":"ਤੂੰ ਪਾਖੰਡ ਵਿਖਾ ਕੇ ਤਪਸਿਆ ਕਰਦਾ ਹੈਂ, (ਪਰ ਤੇਰਾ) ਮਨ ਦਿਨ ਰਾਤ ਧਨ ਵਿਚ ਵਸਦਾ ਹੈ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਮੂਰਖ ਲੋਗ ਪ੍ਰਮਾਨ ਕਰੈ ਇਨ ਬਾਤਨ ਕੌ ਹਮ ਮਾਨਤ ਨਾਹੀ। ੨੩।","roman":"Moorakh log pramaan karai in baatan kau ham maanat naahee | 23 |","meaning_en":"foolish people accept it, but I do not accept such talk.'","page":2089,"meaning_status":"draft","meaning_pa":"ਮੂਰਖ ਲੋਗ (ਤੇਰੀਆਂ ਗੱਲਾ ਨੂੰ) ਪ੍ਰਮਾਣਿਕ ਮੰਨਣ, ਪਰ ਅਸੀਂ ਇਨ੍ਰਹਾ ਗੱਲਾ ਨੂੰ ਨਹੀਂ ਮੰਨਦੇ ॥੨੩॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[24],"number_text":"੨੪।","page":2091,"lines":[{"gurmukhi":"ਕਾਹੇ ਕੋ ਕਾਜ ਕਰੋ ਇਤਨੀ ਤੁਮ ਪਾਹਨ ਕੋ ਕਿਹ ਕਾਜ ਪੁਜਾਵੋ।","roman":"Kaahe ko kaaj karo itnee tum paahan ko kih kaaj pujaavo |","meaning_en":"'Why do you take such trouble? For what purpose do you get a stone worshipped?","page":2091,"meaning_status":"draft","meaning_pa":"ਤੂੰ ਕਿਸ ਕੰਮ ਲਈ ਇਤਨੀ (ਪੂਜਾ) ਕਰਦਾ ਹੈਂ ਅਤੇ ਪੱਥਰ ਨੂੰ ਕਿਸ ਲਈ ਪੂਜਦਾ ਹੈਂ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਕਾਹੇ ਕੋ ਡਿੰਭ ਕਰੋ ਜਗ ਮੈ ਇਹ ਲੋਕ ਗਯੋ ਪਰਲੋਕ ਗਵਾਵੋ।","roman":"Kaahe ko dinbh karo jag mai ih lok gayo parlok gavaavo |","meaning_en":"Why practise hypocrisy in the world? You have lost this world and spoilt the next.","page":2091,"meaning_status":"draft","meaning_pa":"ਜਗਤ ਵਿਚ ਕਿਸ ਲਈ ਪਾਖੰਡ ਕਰਦਾ ਹੈਂ। (ਤੇਰਾ) ਇਹ ਲੋਕ ਤਾ ਨਸ਼ਟ ਹੋ ਗਿਆ (ਹੁਣ) ਪਰਲੋਕ ਵੀ ਗੰਵਾ ਲਵੇਾਂਗਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਝੂਠੇ ਨ ਮੰਤ੍ਰ ਉਪਦੇਸ ਕਰੋ ਜੋਊ ਚਾਹਤ ਹੋ ਧਨ ਲੌ ਹਰਖਾਵੋ।","roman":"Jhoothe na mantr updes karo jo'oo chaahat ho dhan lau harkhaavo |","meaning_en":"Do not give false teaching of mantras; take whatever wealth you want and be glad;","page":2091,"meaning_status":"draft","note":"ਧਨ ਲੌ ਹਰਖਾਵੋ: read as 'take wealth and be glad'; uncertain.","meaning_pa":"(ਮੈਨੂੰ) ਝੂਠੇ ਮੰਤ੍ਰਾ ਦਾ ਉਪਦੇਸ਼ ਨਾ ਕਰ। ਜਿਤਨਾ ਚਾਹੁੰਦਾ ਹੈਂ, (ਉਤਨਾ) ਧਨ ਲੈ ਕੇ ਪ੍ਰਸੰਨ ਹੋ ਜਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਰਾਜ ਕੁਮਾਰਨ ਮੰਤ੍ਰ ਦਿਯੋ ਸੁ ਦਿਯੋ ਬਹੁਰੌ ਹਮ ਕੌ ਨ ਸਿਖਾਵੋ। ੨੪।","roman":"Raaj kumaaran mantr diyo su diyo bahurau ham kau na sikhaavo | 24 |","meaning_en":"the mantra you gave to the princes you have given; now do not teach us.'","page":2091,"meaning_status":"draft","meaning_pa":"ਰਾਜ ਕੁਮਾਰਾ ਨੂੰ ਜੋ ਮੰਤ੍ਰ ਦਿੱਤਾ ਗਿਆ, ਸੋ ਦਿੱਤਾ ਗਿਆ, ਪਰ ਫਿਰ ਸਾਨੂੰ ਕੋਈ (ਮੰਤ੍ਰ) ਨਾ ਸਿਖਾਣਾ ॥੨੪॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"speaker","name":"ਦਿਜ ਬਾਚ","gurmukhi":"ਦਿਜ ਬਾਚ","roman":"Dij baach","meaning_en":"The brahmin said:","page":2091,"meaning_status":"draft","meaning_pa":"ਬ੍ਰਾਹਮਣ ਨੇ ਕਿਹਾ:","meaning_pa_source":"BaniDB"},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2091,"meaning_status":"draft","meaning_pa":"ਚੌਪਈ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[25],"number_text":"੨੫।","page":2091,"lines":[{"gurmukhi":"ਕਹਾ ਬਿਪ੍ਰ ਸੁਨੁ ਰਾਜ ਦੁਲਾਰੀ। ਤੈ ਸਿਵ ਕੀ ਮਹਿਮਾ ਨ ਬਿਚਾਰੀ।","roman":"Kahaa bipr sunu raaj dulaaree | tai siv kee mahimaa na bichaaree |","meaning_en":"'Listen, darling of the king: you have not considered the greatness of Shiva.","page":2091,"meaning_status":"draft","meaning_pa":"ਬ੍ਰਾਹਮਣ ਨੇ ਆਖਿਆ, ਹੇ ਰਾਜ ਕੁਮਾਰੀ! ਸੁਣ, ਤੂੰ ਸ਼ਿਵ ਦੀ ਮਹਿਮਾ ਨੂੰ ਨਹੀਂ ਵਿਚਾਰਿਆ ਹੈ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਬ੍ਰਹਮਾ ਬਿਸਨ ਰੁਦ੍ਰ ਜੂ ਦੇਵਾ। ਇਨ ਕੀ ਸਦਾ ਕੀਜਿਯੈ ਸੇਵਾ। ੨੫।","roman":"Brahmaa bisan rudr joo devaa | in kee sadaa keejiyai sevaa | 25 |","meaning_en":"Brahma, Vishnu and Rudra are gods; they should always be served.","page":2091,"meaning_status":"draft","meaning_pa":"ਬ੍ਰਹਮਾ, ਵਿਸ਼ਣੂ ਅਤੇ ਸ਼ਿਵ ਆਦਿ, ਜੋ ਦੇਵਤੇ ਹਨ, ਇਨ੍ਰਹਾ (ਦੇਵਤਿਆਂ) ਦੀ ਸਦਾ ਸੇਵਾ ਕਰਨੀ ਚਾਹੀਦੀ ਹੈ ॥੨੫॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[26],"number_text":"੨੬।","page":2091,"lines":[{"gurmukhi":"ਤੈ ਯਾ ਕੇ ਭੇਵਹਿ ਨ ਪਛਾਨੈ। ਮਹਾ ਮੂੜ ਇਹ ਭਾਤਿ ਬਖਾਨੈ।","roman":"Tai yaa ke bhevhi na pachhaanai | mahaa moor ih bhaati bakhaanai |","meaning_en":"You do not recognise their secret; you are a great fool to speak like this.","page":2091,"meaning_status":"draft","meaning_pa":"ਤੂੰ ਇਨ੍ਰਹਾ ਦੇ ਭੇਦ ਨੂੰ ਨਹੀਂ ਪਛਾਣਿਆ ਅਤੇ ਮਹਾ ਮੂਰਖਾ ਵਾਗ ਇਸ ਤਰ੍ਰਹਾ ਬਖਾਨ ਕਰਦੀ ਹੈਂ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਇਨ ਕੋ ਪਰਮ ਪੁਰਾਤਨ ਜਾਨਹੁ। ਪਰਮ ਪੁਰਖ ਮਨ ਮਹਿ ਪਹਿਚਾਨਹੁ। ੨੬।","roman":"In ko param puraatan jaanhu | param purakh man mahi pahichaanhu | 26 |","meaning_en":"Know them as supremely ancient; recognise them in your mind as the supreme Person.","page":2091,"meaning_status":"draft","meaning_pa":"ਇਨ੍ਰਹਾ (ਦੇਵਤਿਆਂ) ਨੂੰ ਪਰਮ ਪੁਰਾਤਨ ਜਾਣੋ ਅਤੇ (ਇਨ੍ਰਹਾ ਨੂੰ) ਮਨ ਵਿਚ ਪਰਮ ਪੁਰਸ਼ ਸਮਝੋ ॥੨੬॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[27],"number_text":"੨੭।","page":2091,"lines":[{"gurmukhi":"ਹਮ ਹੈ ਕੁਅਰਿ ਬਿਪ੍ਰ ਬ੍ਰਤ ਧਾਰੀ। ਊਚ ਨੀਚ ਸਭ ਕੇ ਹਿਤਕਾਰੀ।","roman":"Ham hai kuari bipr brat dhaaree | ooch neech sabh ke hitkaaree |","meaning_en":"Princess, we are brahmins who keep vows, well-wishers of all, high and low.","page":2091,"meaning_status":"draft","meaning_pa":"ਹੇ ਰਾਜ ਕੁਮਾਰੀ! ਮੈਂ ਬ੍ਰਤਧਾਰੀ ਬ੍ਰਾਹਮਣ ਹਾ ਅਤੇ ਉਚੇ ਨੀਵੇਾਂ ਸਭ ਦਾ ਹਿਤੈਸ਼ੀ ਹਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜਿਸੀ ਕਿਸੀ ਕਹ ਮੰਤ੍ਰ ਸਿਖਾਵੈ। ਮਹਾ ਕ੍ਰਿਪਨ ਤੇ ਦਾਨ ਕਰਾਵੈ। ੨੭।","roman":"Jisee kisee kah mantr sikhaavai | mahaa kripan te daan karaavai | 27 |","meaning_en":"Whomever he teaches a mantra, from even the greatest miser he gets charity given.'","page":2091,"meaning_status":"draft","note":"Shifts from 'we' to 'he' as printed.","meaning_pa":"ਜਿਸ ਕਿਸੇ ਨੂੰ ਮੰਤ੍ਰ (ਵਿਦਿਆ) ਸਿਖਾਉਾਂਦਾ ਹਾ, ਅਤੇ ਵੱਡੇ ਕੰਜੂਸਾ ਤੋਂ ਦਾਨ ਕਰਵਾਉਾਂਦਾ ਹਾ ॥੨੭॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"speaker","name":"ਕੁਅਰਿ ਬਾਚ","gurmukhi":"ਕੁਅਰਿ ਬਾਚ","roman":"Kuari baach","meaning_en":"The princess said:","page":2091,"meaning_status":"draft","meaning_pa":"ਰਾਜ ਕੁਮਾਰੀ ਨੇ ਕਿਹਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[28],"number_text":"੨੮।","page":2091,"lines":[{"gurmukhi":"ਮੰਤ੍ਰ ਦੇਤ ਸਿਖ ਅਪਨ ਕਰਤ ਹਿਤ। ਜ੍ਯੋ ਤ੍ਯੋ ਭੇਟ ਲੈਤ ਤਾ ਤੇ ਬਿਤ।","roman":"Mantr det sikh apan karat hit | jyo tyo bhet lait taa te bit |","meaning_en":"'He gives a mantra, makes the man his disciple and shows him affection, and somehow takes wealth as an offering from him.","page":2091,"meaning_status":"draft","meaning_pa":"ਤੁਸੀਂ ਆਪਣੇ ਸੇਵਕ ਬਣਾਉਣ ਲਈ ਮੰਤ੍ਰ ਦਿੰਦੇ ਹੋ ਅਤੇ ਜਿਵੇਾਂ ਕਿਵੇਾਂ ਉਨ੍ਰਹਾ ਤੋਂ ਦਾਨ ਲੈਂਦੇ ਹੋ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਸਤਿ ਬਾਤ ਤਾ ਕਹ ਨ ਸਿਖਾਵਹੁ। ਤਾਹਿ ਲੋਕ ਪਰਲੋਕ ਗਵਾਵਹੁ। ੨੮।","roman":"Sati baat taa kah na sikhaavhu | taahi lok parlok gavaavhu | 28 |","meaning_en":"He does not teach him the true matter; he makes him lose this world and the next.","page":2091,"meaning_status":"draft","meaning_pa":"ਉਨ੍ਰਹਾ ਨੂੰ ਸੱਚੀ (ਵਾਸਤਵਿਕ) ਗੱਲ ਨਹੀਂ ਸਿਖਾਉਾਂਦੇ। (ਇਸ ਤਰ੍ਰਹਾ) ਉਨ੍ਰਹਾ ਦੇ ਲੋਕ ਅਤੇ ਪਰਲੋਕ ਗੰਵਾ ਦਿੰਦੇ ਹੋ ॥੨੮॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[29],"number_text":"੨੯।","page":2091,"lines":[{"gurmukhi":"ਸੁਨਹੁ ਬਿਪ ਤੁਮ ਮੰਤ੍ਰ ਦੇਤ ਜਿਹ। ਲੂਟਿ ਲੇਤ ਤਿਹ ਘਰ ਬਿਧਿ ਜਿਹ ਕਿਹ।","roman":"Sunhu bip tum mantr det jih | looti let tih ghar bidhi jih kih |","meaning_en":"Listen, brahmin: the man to whom you give a mantra, you plunder his house by whatever means.","page":2091,"meaning_status":"draft","meaning_pa":"ਹੇ ਬ੍ਰਾਹਮਣ! ਸੁਣੋ। ਜਿਨ੍ਰਹਾ ਨੂੰ ਤੁਸੀਂ ਮੰਤ੍ਰ ਦਿੰਦੇ ਹੋ, ਉਨ੍ਰਹਾ ਦੇ ਘਰਾ ਨੂੰ ਕਿਸੇ ਨਾ ਕਿਸੇ ਢੰਗ ਨਾਲ ਲੁਟ ਲੈਂਦੇ ਹੋ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਤਾ ਕਹ ਕਛੂ ਗ੍ਯਾਨ ਨਹਿ ਆਵੈ। ਮੂਰਖ ਅਪਨਾ ਮੂੰਡ ਮੁੰਡਾਵੈ। ੨੯।","roman":"Taa kah kachhoo gyaan nahi aavai | moorakh apnaa moond mundaavai | 29 |","meaning_en":"He gets no knowledge at all; the fool has his own head shaved.","page":2091,"meaning_status":"draft","meaning_pa":"ਉਨ੍ਰਹਾ ਨੂੰ ਕੋਈ ਗਿਆਨ ਹਾਸਲ ਨਹੀਂ ਹੁੰਦਾ ਅਤੇ ਮੂਰਖ (ਤੁਹਾਡੇ ਤੋਂ) ਆਪਣਾ ਸਿਰ ਮੁੰਨਵਾ ਲੈਂਦੇ ਹਨ ॥੨੯॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[30],"number_text":"੩੦।","page":2091,"lines":[{"gurmukhi":"ਤਿਹ ਤੁਮ ਕਹੁ ਮੰਤ੍ਰ ਸਿਧਿ ਹ੍ਵੈਹੈ। ਮਹਾਦੇਵ ਤੋ ਕੌ ਬਰੁ ਦੈ ਹੈ।","roman":"Tih tum kahu mantr sidhi hvaihai | mahaadev to kau baru dai hai |","meaning_en":"You tell him, 'The mantra will be perfected; Mahadev will give you a boon.'","page":2091,"meaning_status":"draft","meaning_pa":"ਤੁਸੀਂ ਉਨ੍ਰਹਾ ਨੂੰ ਕਹਿੰਦੇ ਹੋ (ਕਿ ਜਦੋਂ ਤੁਹਾਡਾ) ਮੰਤ੍ਰ ਸਿੱਧ ਹੋਵੇਗਾ ਤਾ ਮਹਾਦੇਵ ਤੁਹਾਨੂੰ ਵਰ ਦੇਵੇਗਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜਬ ਤਾ ਤੇ ਨਹਿ ਹੋਤ ਮੰਤ੍ਰ ਸਿਧਿ। ਤਬ ਤੁਮ ਬਚਨ ਕਹਤ ਹੌ ਇਹ ਬਿਧਿ। ੩੦।","roman":"Jab taa te nahi hot mantr sidhi | tab tum bachan kahat hau ih bidhi | 30 |","meaning_en":"When no mastery of the mantra comes from it, then you speak to him in this way:","page":2091,"meaning_status":"draft","meaning_pa":"ਜਦੋਂ ਉਨ੍ਰਹਾ ਤੋਂ ਮੰਤ੍ਰ ਸਿੱਧ ਨਹੀਂ ਹੁੰਦਾ, ਤਾ ਤੁਸੀਂ (ਉਨ੍ਰਹਾ ਨੂੰ) ਇਸ ਤਰ੍ਰਹਾ ਬਚਨ ਕਹਿੰਦੇ ਹੋ ॥੩੦॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[31],"number_text":"੩੧।","page":2091,"lines":[{"gurmukhi":"ਕਛੂ ਕੁਕ੍ਰਿਯਾ ਤੁਮਤੇ ਭਯੋ। ਤਾ ਤੇ ਦਰਸ ਨ ਸਿਵ ਜੂ ਦਯੋ।","roman":"Kachhoo kukriyaa tumte bhayo | taa te daras na siv joo dayo |","meaning_en":"'Some wrong action was done by you, and so Shiva did not give his sight.","page":2091,"meaning_status":"draft","meaning_pa":"ਤੁਹਾਡੇ ਤੋਂ ਕੁਝ ਚੂਕ ਹੋ ਗਈ ਹੈ, ਇਸ ਲਈ ਸ਼ਿਵ ਜੀ ਨੇ ਦੀਦਾਰ ਨਹੀਂ ਦਿੱਤਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਅਬ ਤੈ ਪੁੰਨ੍ਯ ਦਾਨ ਦਿਜ ਕਰ ਰੇ। ਪੁਨਿ ਸਿਵ ਕੇ ਮੰਤ੍ਰਹਿ ਅਨੁਸਰੁ ਰੇ। ੩੧।","roman":"Ab tai punny daan dij kar re | puni siv ke mantrahi anusru re | 31 |","meaning_en":"Now give charity to brahmins, and then follow Shiva's mantra again.'","page":2091,"meaning_status":"draft","meaning_pa":"ਓਏ! ਹੁਣ ਤੂੰ ਬ੍ਰਾਹਮਣਾ ਨੂੰ ਪੁੰਨ ਦਾਨ ਕਰ ਅਤੇ ਫਿਰ ਸ਼ਿਵ ਦੇ ਮੰਤ੍ਰਾ ਨੂੰ ਜਪ ॥੩੧॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[32],"number_text":"੩੨।","page":2091,"lines":[{"gurmukhi":"ਉਲਟੋ ਡੰਡ ਤਿਸੀ ਤੇ ਲੇਹੀ। ਪੁਨਿ ਤਿਹ ਮੰਤ੍ਰ ਰੁਦ੍ਰ ਕੋ ਦੇਹੀ।","roman":"Ulto dand tisee te lehee | puni tih mantr rudr ko dehee |","meaning_en":"He takes a fine in return from the same man, and then gives him a mantra of Rudra.","page":2091,"meaning_status":"draft","meaning_pa":"(ਤੁਸੀਂ) ਉਲਟਾ ਉਸੇ ਤੋਂ ਹੀ ਦੰਡ ਲੈਂਦੇ ਹੋ ਅਤੇ ਉਨ੍ਰਹਾ ਨੂੰ ਫਿਰ ਰੁਦ੍ਰ ਦਾ ਮੰਤ੍ਰ ਦਿੰਦੇ ਹੋ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਤਾ ਕੌ ਭਟਕਾਵੈ। ਅੰਤ ਬਾਰ ਇਮਿ ਭਾਖ ਸੁਨਾਵੈ। ੩੨।","roman":"Bhaati bhaati taa kau bhatkaavai | ant baar imi bhaakh sunaavai | 32 |","meaning_en":"In many ways he leads him astray, and at last he tells him this:","page":2091,"meaning_status":"draft","meaning_pa":"ਉਸ ਨੂੰ ਕਈਆਂ ਤਰ੍ਰਹਾ ਨਾਲ ਭਟਕਾਉਾਂਦੇ ਹੋ ਅਤੇ ਅੰਤ ਵਿਚ ਇਸ ਤਰ੍ਰਹਾ ਕਹਿ ਦਿੰਦੇ ਹੋ ॥੩੨॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[33],"number_text":"੩੩।","page":2091,"lines":[{"gurmukhi":"ਤੋ ਤੇ ਕਛੁ ਅਛਰ ਰਹਿ ਗਯੋ। ਤੈ ਕਛੁ ਭੰਗ ਕ੍ਰਿਯਾ ਤੇ ਭਯੋ।","roman":"To te kachhu achhar rahi gayo | tai kachhu bhang kriyaa te bhayo |","meaning_en":"'Some letter was left out by you, or you made some fault in the rite;","page":2091,"meaning_status":"draft","meaning_pa":"ਤੇਰੇ ਕੋਲੋਂ (ਜਾਪ ਕਰਦਿਆਂ) ਕੋਈ ਅੱਖਰ ਰਹਿ ਗਿਆ ਹੋਵੇਗਾ। ਤੇਰੇ ਤੋਂ (ਜਾਪ) ਕ੍ਰਿਆ ਭੰਗ ਹੋ ਗਈ ਹੋਵੇਗੀ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਤਾ ਤੇ ਤੁਹਿ ਬਰੁ ਰੁਦ੍ਰ ਨ ਦੀਨਾ। ਪੁੰਨ੍ਯ ਦਾਨ ਚਹਿਯਤ ਪੁਨਿ ਕੀਨਾ। ੩੩।","roman":"Taa te tuhi baru rudr na deenaa | punny daan chahiyat puni keenaa | 33 |","meaning_en":"therefore Rudra did not give you a boon; you must give charity again.'","page":2091,"meaning_status":"draft","meaning_pa":"ਇਸ ਲਈ ਤੈਨੂੰ ਰੁਦ੍ਰ ਨੇ ਵਰ ਨਹੀਂ ਦਿੱਤਾ। (ਇਸ ਲਈ) ਫਿਰ ਪੁੰਨ ਦਾਨ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ ॥੩੩॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[34],"number_text":"੩੪।","page":2091,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਮੰਤ੍ਰ ਸਿਖਾਵਤ ਤਾ ਕੋ। ਲੂਟਾ ਚਾਹਤ ਬਿਪ੍ਰ ਘਰ ਜਾ ਕੋ।","roman":"Ih bidhi mantr sikhaavat taa ko | lootaa chaahat bipr ghar jaa ko |","meaning_en":"In this way he teaches him the mantra, wanting to loot the house of whoever he is;","page":2091,"meaning_status":"draft","meaning_pa":"ਹੇ ਬ੍ਰਾਹਮਣ! ਇਸ ਤਰ੍ਰਹਾ (ਤੁਸੀਂ) ਉਸ ਨੂੰ ਮੰਤ੍ਰ ਸਿਖਾਉਾਂਦੇ ਹੋ ਜਿਸ ਦਾ ਘਰ ਲੁਟਣਾ ਚਾਹੁੰਦੇ ਹੋ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜਬ ਵਹੁ ਦਰਬ ਰਹਤ ਹ੍ਵੈ ਜਾਈ। ਔਰ ਧਾਮ ਤਬ ਚਲਤ ਤਕਾਈ। ੩੪।","roman":"Jab vahu darab rahat hvai jaaee | aur dhaam tab chalat takaaee | 34 |","meaning_en":"when that man has no wealth left, he looks to another house and goes.","page":2091,"meaning_status":"draft","meaning_pa":"ਜਦ ਉਹ ਧਨ-ਰਹਿਤ ਹੋ ਜਾਦਾ ਹੈ, ਤਦ ਤੁਸੀਂ ਹੋਰ ਘਰ ਤਕਣ ਲਗ ਜਾਦੇ ਹੋ ॥੩੪॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2093,"meaning_status":"draft","meaning_pa":"ਦੋਹਰਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[35],"number_text":"੩੫।","page":2093,"lines":[{"gurmukhi":"ਮੰਤ੍ਰ ਜੰਤ੍ਰ ਅਰੁ ਤੰਤ੍ਰ ਸਿਧਿ ਜੌ ਇਨਿ ਮਹਿ ਕਛੁ ਹੋਇ।","roman":"Mantr jantr aru tantr sidhi jau ini mahi kachhu hoi |","meaning_en":"If there were any success in mantra, yantra and tantra among these people,","page":2093,"meaning_status":"draft","meaning_pa":"ਜੇ ਇਨ੍ਰਹਾ ਮੰਤ੍ਰਾ, ਜੰਤ੍ਰਾ ਅਤੇ ਤੰਤ੍ਰਾ ਵਿਚ ਕੁਝ ਸਿੱਧੀ ਹੁੰਦੀ,","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਹਜਰਤਿ ਹ੍ਵੈ ਆਪਹਿ ਰਹਹਿ ਮਾਗਤ ਫਿਰਤ ਨ ਕੋਇ। ੩੫।","roman":"Hajarti hvai aaphi rahhi maagat phirat na koi | 35 |","meaning_en":"they would themselves become lords, and none of them would wander begging.","page":2093,"meaning_status":"draft","note":"ਹਜਰਤਿ: 'hazrat', read as 'lord, honoured one'.","meaning_pa":"ਤਾ ਤੁਸੀਂ ਆਪ ਬਾਦਸ਼ਾਹ ਬਣ ਜਾਦੇ ਅਤੇ ਕੋਈ ਵੀ ਮੰਗਦਾ ਨਾ ਫਿਰਦਾ ॥੩੫॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਦਿਜ ਬਾਜ","gurmukhi":"ਦਿਜ ਬਾਜ","roman":"Dij baaj","meaning_en":"The brahmin said:","page":2093,"meaning_status":"draft","note":"Printed ਦਿਜ ਬਾਜ (baj); read as ਬਾਚ (bach), 'said'.","meaning_pa":"ਬ੍ਰਾਹਮਣ ਨੇ ਕਿਹਾ:","meaning_pa_source":"BaniDB"},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2093,"meaning_status":"draft","meaning_pa":"ਚੌਪਈ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[36],"number_text":"੩੬।","page":2093,"lines":[{"gurmukhi":"ਸੁਨਿ ਏ ਬਚਨ ਮਿਸਰ ਰਿਸਿ ਭਰਾ। ਧਿਕ ਧਿਕ ਤਾਕਹਿ ਬਚਨ ਉਚਰਾ।","roman":"Suni e bachan misar risi bharaa | dhik dhik taakhi bachan uchraa |","meaning_en":"Hearing these words, the Mishra was filled with anger and spoke the words 'Curse, curse' to her.","page":2093,"meaning_status":"draft","meaning_pa":"ਇਹ ਬੋਲ ਸੁਣ ਕੇ ਬ੍ਰਾਹਮਣ ਰੋਹ ਨਾਲ ਭਰ ਗਿਆ ਅਤੇ ਉਸ ਨੂੰ 'ਧਿਕਾਰ, ਧਿਕਾਰ' ਦੇ ਬਚਨ ਕਹਿਣ ਲਗਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਤੈ ਹਮਰੀ ਬਾਤ ਕਹ ਜਾਨੈ। ਭਾਂਗ ਖਾਇ ਕੈ ਬੈਨ ਪ੍ਰਮਾਨੈ। ੩੬।","roman":"Tai hamree baat kah jaanai | bhaang khaai kai bain pramaanai | 36 |","meaning_en":"'What do you know of our affairs? You eat bhang and then speak such words.'","page":2093,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਕੁਅਰਿ ਬਾਚ","gurmukhi":"ਕੁਅਰਿ ਬਾਚ","roman":"Kuari baach","meaning_en":"The princess said:","page":2093,"meaning_status":"draft","meaning_pa":"ਤੂੰ ਮੇਰੀਆਂ ਗੱਲਾ ਨੂੰ ਕੀ ਸਮਝੇਾਂਗੀ ਜੋ ਭੰਗ ਖਾ ਕੇ ਬੋਲ ਉਚਾਰ ਰਹੀ ਹੈਂ ॥੩੬॥ ਰਾਜ ਕੁਮਾਰੀ ਨੇ ਕਿਹਾ:","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"},{"type":"verse","number":[37],"number_text":"੩੭।","page":2093,"lines":[{"gurmukhi":"ਸੁਨੋ ਮਿਸਰ ਤੁਮ ਬਾਤ ਨ ਜਾਨਤ। ਅਹੰਕਾਰ ਕੈ ਬਚਨ ਪ੍ਰਮਾਨਤ।","roman":"Suno misar tum baat na jaanat | ahankaar kai bachan pramaanat |","meaning_en":"'Listen, Mishra, you do not know the matter; you utter words out of ego.","page":2093,"meaning_status":"draft","meaning_pa":"ਹੇ ਬ੍ਰਾਹਮਣ! ਸੁਣੋ, ਤੁਸੀਂ ਗੱਲ ਨੂੰ ਨਹੀਂ ਸਮਝਦੇ ਅਤੇ ਹੰਕਾਰ ਭਰੇ ਬੋਲ ਬੋਲਦੇ ਹੋ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਭਾਂਗ ਪੀਏ ਬੁਧਿ ਜਾਤ ਨ ਹਰੀ। ਬਿਨੁ ਪੀਏ ਤਵ ਬੁਧਿ ਕਹ ਪਰੀ। ੩੭।","roman":"Bhaang pee'e budhi jaat na haree | binu pee'e tav budhi kah paree | 37 |","meaning_en":"Drinking bhang does not steal intelligence; without drinking it, where has your intelligence gone?","page":2093,"meaning_status":"draft","meaning_pa":"ਭੰਗ ਪੀਣ ਨਾਲ ਬੁੱਧੀ ਹਰੀ ਨਹੀਂ ਜਾਦੀ। ਬਿਨਾ ਪੀਤਿਆਂ ਤੁਹਾਨੂੰ ਕਿਹੜੀ ਬੁੱਧੀ ਪ੍ਰਾਪਤ ਹੋ ਗਈ ਹੈ ॥੩੭॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[38],"number_text":"੩੮।","page":2093,"lines":[{"gurmukhi":"ਤੁਮ ਆਪਨ ਸ੍ਯਾਨੇ ਕਹਲਾਵਤ। ਕਬ ਹੀ ਭੂਲਿ ਨ ਭਾਂਗ ਚੜਾਵਤ।","roman":"Tum aapan syaane kahlaavat | kab hee bhooli na bhaang charaavat |","meaning_en":"You call yourselves clever, but you never even by mistake take bhang;","page":2093,"meaning_status":"draft","meaning_pa":"ਤੁਸੀਂ ਆਪਣੇ ਆਪ ਨੂੰ ਸਿਆਣਾ ਅਖਵਾਉਾਂਦੇ ਹੋ ਅਤੇ ਕਦੇ ਭੁਲ ਕੇ ਵੀ ਭੰਗ ਨਹੀਂ ਚੜ੍ਰਹਾਉਾਂਦੇ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜਬ ਪੁਨ ਜਾਹੁ ਕਾਜ ਭਿਛਾ ਕੇ। ਕਰਹੋ ਖ੍ਵਾਰ ਰਹਤ ਗ੍ਰਿਹ ਜਾ ਕੇ। ੩੮।","roman":"Jab pun jaahu kaaj bhichhaa ke | karho khvaar rahat grih jaa ke | 38 |","meaning_en":"when you go for alms you ruin the one in whose house you stay.","page":2093,"meaning_status":"draft","note":"Second half of the line is obscure; read as printed; uncertain.","meaning_pa":"ਫਿਰ ਜਦ (ਤੁਸੀਂ) ਭਿਖਿਆ ਲਈ ਜਾਓਗੇ ਤਾ ਜਿਸ ਦੇ ਘਰ ਵੀ ਰਹੋਗੇ, (ਉਸ ਨੂੰ) ਖੁਆਰ ਕਰੋਗੇ ॥੩੮॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[39],"number_text":"੩੯।","page":2093,"lines":[{"gurmukhi":"ਜਿਹ ਧਨ ਕੋ ਤੁਮ ਤ੍ਯਾਗ ਦਿਖਾਵਤ। ਦਰ ਦਰ ਤਿਹ ਮਾਂਗਨ ਕਸ ਜਾਵਤ।","roman":"Jih dhan ko tum tyaag dikhaavat | dar dar tih maangan kas jaavat |","meaning_en":"The wealth whose renunciation you show off, why do you go from door to door begging for it?","page":2093,"meaning_status":"draft","meaning_pa":"ਜਿਸ ਧਨ ਨੂੰ ਤੁਸੀਂ ਤਿਆਗ ਕੇ ਵਿਖਾਉਾਂਦੇ ਹੋ, (ਫਿਰ) ਉਸ ਨੂੰ ਮੰਗਣ ਲਈ ਦੁਆਰ ਦੁਆਰ ਉਤੇ ਕਿਉਾਂ ਜਾਦੇ ਹੋ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਮਹਾ ਮੂੜ ਰਾਜਨ ਕੇ ਪਾਸਨ। ਲੇਤ ਫਿਰਤ ਹੋ ਮਿਸ੍ਰ ਜੂ ਕਨ ਕਨ। ੩੯।","roman":"Mahaa moor raajan ke paasan | let phirat ho misr joo kan kan | 39 |","meaning_en":"Great fool, you go about near kings taking grain by grain, Mishra ji.","page":2093,"meaning_status":"draft","meaning_pa":"(ਤੁਸੀਂ) ਮਹਾ ਮੂਰਖ ਰਾਜਿਆਂ ਪਾਸੋਂ ਹੇ ਮਿਸ਼ਰ ਜੀ! ਕਣ ਕਣ ਲੈਣ ਲਈ ਘੁੰਮਦੇ ਫਿਰਦੇ ਹੋ ॥੩੯॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[40],"number_text":"੪੦।","page":2093,"lines":[{"gurmukhi":"ਤੁਮ ਜਗ ਮਹਿ ਤ੍ਯਾਗੀ ਕਹਲਾਵਤ। ਸਭ ਲੋਕਨ ਕਹ ਤ੍ਯਾਗ ਦ੍ਰਿੜਾਵਤ।","roman":"Tum jag mahi tyaagee kahlaavat | sabh lokan kah tyaag driraavat |","meaning_en":"You are called renouncers in the world, and you make all people firm in renunciation;","page":2093,"meaning_status":"draft","meaning_pa":"ਤੁਸੀਂ ਜਗਤ ਵਿਚ ਤਿਆਗੀ ਅਖਵਾਉਾਂਦੇ ਹੋ ਅਤੇ ਸਾਰਿਆਂ ਲੋਕਾ ਨੂੰ ਤਿਆਗ (ਕਰਨ ਦੀ ਗੱਲ) ਦ੍ਰਿੜ੍ਰਹ ਕਰਾਉਾਂਦੇ ਹੋ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜਾ ਕਹ ਮਨ ਬਚ ਕ੍ਰਮ ਤਜਿ ਦੀਜੈ। ਤਾ ਕਹ ਹਾਥ ਉਠਾਇ ਕਸ ਲੀਜੈ। ੪੦।","roman":"Jaa kah man bach kram taji deejai | taa kah haath uthaai kas leejai | 40 |","meaning_en":"the one to whom you give up in mind, word and deed, how can you raise your hand and take from him?","page":2093,"meaning_status":"draft","note":"Line is obscure; read as printed; uncertain.","meaning_pa":"ਜਿਸ ਨੂੰ (ਤੁਸੀਂ) ਮਨ, ਬਚ ਅਤੇ ਕਰਮ ਕਰ ਕੇ ਛਡ ਦਿੱਤਾ ਹੈ, (ਫਿਰ) ਉਸ ਨੂੰ ਹੱਥ ਉਠਾ ਕੇ ਕਿਉਾਂ ਗ੍ਰਹਿਣ ਕਰਦੇ ਹੋ ॥੪੦॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[41],"number_text":"੪੧।","page":2093,"lines":[{"gurmukhi":"ਕਾਹੂ ਧਨ ਤ੍ਯਾਗ ਦ੍ਰਿੜਾਵਹਿ। ਕਾਹੂ ਕੋ ਕੋਊ ਗ੍ਰਹਿ ਲਾਵਹਿ।","roman":"Kaahoo dhan tyaag driraavhi | kaahoo ko ko'oo grahi laavhi |","meaning_en":"Some you make firm in renunciation of wealth; some you bring into a house;","page":2093,"meaning_status":"draft","note":"ਕਾਹੂ ਕੋ ਕੋਊ ਗ੍ਰਹਿ ਲਾਵਹਿ: obscure; read as 'someone you bring into someone's house'; uncertain.","meaning_pa":"ਕਿਸੇ ਨੂੰ ਧਨ ਤਿਆਗਣ ਲਈ ਪਕਿਆਈ ਕਰਦੇ ਹੋ ਅਤੇ ਕਿਸੇ ਨੂੰ ਕੋਈ ਗ੍ਰਹਿ ਲਗਾ ਦਿੰਦੇ ਹੋ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਮਨ ਮਹਿ ਦਰਬ ਠਗਨ ਕੀ ਆਸਾ। ਦ੍ਵਾਰ ਦ੍ਵਾਰ ਡੋਲਤ ਇਹ ਪ੍ਯਾਸਾ। ੪੧।","roman":"Man mahi darab thagan kee aasaa | dvaar dvaar dolat ih pyaasaa | 41 |","meaning_en":"in your mind is the hope of cheating them of wealth; you wander from door to door with this thirst.","page":2093,"meaning_status":"draft","meaning_pa":"(ਤੁਹਾਡੇ) ਮਨ ਵਿਚ ਧਨ ਠਗਣ ਦੀ ਲਾਲਸਾ ਹੈ ਅਤੇ ਇਸੇ ਪਿਆਸ (ਨੂੰ ਤ੍ਰਿਪਤਾਉਣ ਲਈ) ਘਰ ਘਰ ਡੋਲਦੇ ਫਿਰਦੇ ਹੋ ॥੪੧॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":2093,"meaning_status":"draft","meaning_pa":"ਅੜਿਲ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[42],"number_text":"੪੨।","page":2093,"lines":[{"gurmukhi":"ਬੇਦ ਬ੍ਯਾਕਰਨ ਸਾਸਤ੍ਰ ਸਿੰਮ੍ਰਿਤ ਇਮ ਉਚਰੈ।","roman":"Bed byaakran saasatr sinmrit im uchrai |","meaning_en":"He recites the Vedas, grammar, shastras and smritis, saying this:","page":2093,"meaning_status":"draft","meaning_pa":"ਵੇਦ, ਵਿਆਕਰਣ, ਸ਼ਾਸਤ੍ਰ ਅਤੇ ਸਮ੍ਰਿਤੀਆਂ ਇਸ ਤਰ੍ਰਹਾ ਉਚਾਰਦੇ ਹੋ","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜਿਨਿ ਕਿਸਹੂ ਤੇ ਏਕ ਟਕਾ ਮੋ ਕੌ ਝਰੈ।","roman":"Jini kishoo te ek takaa mo kau jharai |","meaning_en":"'From whomever, a single taka should drop to me.'","page":2093,"meaning_status":"draft","note":"ਜਿਨਿ: read as 'whoever' (jin); could also be 'lest'; uncertain.","meaning_pa":"ਤਾ ਜੋ ਕਿਸੇ ਤੋਂ ਮੈਨੂੰ ਇਕ ਟਕਾ ਝੜ ਪਏ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜੇ ਤਿਨ ਕੋ ਕਛੁ ਦੇਤ ਉਸਤਤਿ ਤਾ ਕੀ ਕਰੈ।","roman":"Je tin ko kachhu det usatti taa kee karai |","meaning_en":"If they give him something, he praises them;","page":2093,"meaning_status":"draft","meaning_pa":"ਜੋ ਉਨ੍ਰਹਾ ਨੂੰ (ਭਾਵ ਤੁਹਾਨੂੰ) ਕੁਝ ਦਿੰਦਾ ਹੈ, ਉਸ ਦੀ ਉਸਤਤ ਕਰਦੇ ਹੋ","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਹੋ ਜੋ ਧਨ ਦੇਤ ਨ ਤਿਨੈ ਨਿੰਦ ਤਾ ਕੀ ਰਰੈ। ੪੨।","roman":"Ho jo dhan det na tinai nind taa kee rarai | 42 |","meaning_en":"those who give no wealth, he keeps railing at in blame.","page":2093,"meaning_status":"draft","meaning_pa":"ਅਤੇ ਜੋ ਉਨ੍ਰਹਾ ਨੂੰ ਧਨ ਨਹੀਂ ਦਿੰਦਾ, ਉਸ ਦੀ ਨਿੰਦਿਆ ਕਰਦੇ ਹੋ ॥੪੨॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2093,"meaning_status":"draft","meaning_pa":"ਦੋਹਰਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[43],"number_text":"੪੩।","page":2093,"lines":[{"gurmukhi":"ਨਿੰਦਿਆ ਅਰੁ ਉਸਤਤਿ ਦੋਊ ਜੀਵਤ ਹੀ ਜਗ ਮਾਹਿ।","roman":"Nindiaa aru usatti do'oo jeevat hee jag maahi |","meaning_en":"Slander and praise are both only in life, in this world;","page":2093,"meaning_status":"draft","meaning_pa":"ਨਿੰਦਿਆ ਅਤੇ ਉਸਤਤ ਦੋਵੇਾਂ ਜਗਤ ਵਿਚ ਜੀਉਾਂਦੇ ਤਕ ਹੀ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜਬ ਮਾਟੀ ਮਾਟੀ ਮਿਲੀ ਨਿੰਦੁਸਤਤਿ ਕਛੁ ਨਾਹਿ। ੪੩।","roman":"Jab maatee maatee milee nindusatti kachhu naahi | 43 |","meaning_en":"when clay is mingled with clay, there is no slander or praise at all.","page":2093,"meaning_status":"draft","meaning_pa":"ਜਦ ਮਿੱਟੀ ਨਾਲ ਮਿੱਟੀ ਮਿਲ ਗਈ, ਤਾ ਨਿੰਦਿਆ ਜਾ ਉਸਤਤ ਕੁਝ ਵੀ ਨਹੀਂ (ਰਹਿ ਜਾਦੀ) ॥੪੩॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":2095,"meaning_status":"draft","meaning_pa":"ਅੜਿਲ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[44],"number_text":"੪੪।","page":2095,"lines":[{"gurmukhi":"ਦੇਨਹਾਰ ਦਾਇਕਹਿ ਮੁਕਤਿ ਨਹਿ ਕਰਿ ਦਿਯੋ।","roman":"Denhaar daaikhi mukti nahi kari diyo |","meaning_en":"He did not set the giver, the donor, free;","page":2095,"meaning_status":"draft","note":"Lines .0 and .1 are obscure; translated as printed; uncertain.","meaning_pa":"ਮੁਕਤੀ ਪ੍ਰਦਾਨ ਕਰਨ ਵਾਲੇ ਪਰਮਾਤਮਾ ਨੇ (ਮੁਕਤੀ) ਕਿਸ ਹੋਰ ਦੇ ਹੱਥ ਨਹੀਂ ਦਿੱਤੀ ਹੋਈ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਅਨਦਾਇਕ ਤਿਹ ਪੁਤ੍ਰ ਨ ਪਿਤ ਕੋ ਬਧ ਕਿਯੋ।","roman":"Andaaik tih putr na pit ko badh kiyo |","meaning_en":"the one who gives nothing, his son did not kill the father.","page":2095,"meaning_status":"draft","meaning_pa":"ਨਾ ਦੇਣ ਵਾਲਾ ਪਿਤਾ ਪੁੱਤਰ ਦਾ ਬਧ ਨਾ ਕਰ ਦਿੰਦਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜਾ ਤੇ ਧਨ ਕਰ ਪਰੈ ਸੁ ਜਸ ਤਾ ਕੋ ਕਰੈ।","roman":"Jaa te dhan kar parai su jas taa ko karai |","meaning_en":"From the one from whom wealth falls into his hand, he sings his praise;","page":2095,"meaning_status":"draft","meaning_pa":"ਜਿਸ ਤੋਂ (ਤੁਹਾਡੇ) ਹੱਥ ਧਨ ਲਗਦਾ ਹੈ, (ਤੁਸੀਂ) ਉਸ ਦਾ ਜਸ ਕਰਦੇ ਹੋ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਹੋ ਜਾ ਤੇ ਕਛੁ ਨ ਲਹੈ ਨਿੰਦ ਤਿਹ ਉਚਰੈ। ੪੪।","roman":"Ho jaa te kachhu na lahai nind tih uchrai | 44 |","meaning_en":"from the one from whom he gets nothing, he utters slander.","page":2095,"meaning_status":"draft","meaning_pa":"ਜਿਸ ਤੋਂ ਕੁਝ ਨਹੀਂ ਲੈਂਦੇ, ਉਸ ਦੀ ਨਿੰਦਿਆ ਕਰਦੇ ਹੋ ॥੪੪॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2095,"meaning_status":"draft","meaning_pa":"ਚੌਪਈ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[45],"number_text":"੪੫।","page":2095,"lines":[{"gurmukhi":"ਦੁਹੂੰਅਨ ਸਮ ਜੋਊ ਕਰਿ ਜਾਨੈ। ਨਿੰਦ੍ਯਾ ਉਸਤਤਿ ਸਮ ਕਰਿ ਮਾਨੈ।","roman":"Duhoonan sam jo'oo kari jaanai | nindyaa usatti sam kari maanai |","meaning_en":"He who regards both alike, and takes blame and praise as equal,","page":2095,"meaning_status":"draft","meaning_pa":"ਉਸਤਤ ਅਤੇ ਨਿੰਦਿਆ ਦੋਹਾ ਨੂੰ ਜੋ ਇਕ ਸਮਾਨ ਸਮਝ ਕੇ ਮੰਨਦਾ ਹੈ,","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਹਮ ਤਾਹੀ ਕਹ ਬ੍ਰਹਮ ਪਛਾਨਹਿ। ਵਾਹੀ ਕਹਿ ਦਿਜ ਕੈ ਅਨੁਮਾਨਹਿ। ੪੫।","roman":"Ham taahee kah braham pachhaanhi | vaahee kahi dij kai anumaanhi | 45 |","meaning_en":"him alone we recognise as Brahman; him alone we take to be a true brahmin.","page":2095,"meaning_status":"draft","meaning_pa":"ਅਸੀਂ ਉਸੇ ਨੂੰ ਬ੍ਰਹਮ ਸਮਝਦੇ ਹਾ ਅਤੇ ਉਸੇ ਨੂੰ ਸੱਚੇ ਬ੍ਰਾਹਮਣ ਵਜੋਂ ਅਨੁਮਾਨ ਕਰਦੇ ਹਾ ॥੪੫॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":2095,"meaning_status":"draft","meaning_pa":"ਅੜਿਲ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[46],"number_text":"੪੬।","page":2095,"lines":[{"gurmukhi":"ਏ ਦਿਜ ਜਾ ਤੇ ਜਤਨ ਪਾਇ ਧਨ ਲੇਵਹੀ।","roman":"E dij jaa te jatan paai dhan levhee |","meaning_en":"These brahmins, from whomever they can get wealth by effort,","page":2095,"meaning_status":"draft","meaning_pa":"ਇਹ ਬ੍ਰਾਹਮਣ ਜਿਸ ਤੋਂ ਯਤਨ ਕਰ ਕੇ ਧਨ ਪ੍ਰਾਪਤ ਕਰ ਲੈਂਦੇ ਹਨ,","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਤਾ ਨਰ ਕਹ ਬਹੁਤ ਭਾਤਿ ਬਡਾਈ ਦੇਵਹੀ।","roman":"Taa nar kah bahut bhaati badaaee devhee |","meaning_en":"to that man they give great praise;","page":2095,"meaning_status":"draft"},{"gurmukhi":"ਮਿਥਯਾ ਉਪਮਾ ਬਕਿ ਕਰਿ ਤਹਿ ਪ੍ਰਸੰਨ ਕਰੈ।","roman":"Mithyaa upmaa baki kari tahi prasann karai |","meaning_en":"speaking false comparisons they please him;","page":2095,"meaning_status":"draft","meaning_pa":"ਉਸ ਵਿਅਕਤੀ ਨੂੰ ਬਹੁਤ ਢੰਗਾ ਨਾਲ ਵਡਿਆਈ ਦਿੰਦੇ ਹਨ। ਝੂਠੀ ਉਪਮਾ ਕਰ ਕੇ ਉਸ ਨੂੰ ਪ੍ਰਸੰਨ ਕਰਦੇ ਹਨ।","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"},{"gurmukhi":"ਹੋ ਘੋਰ ਨਰਕ ਕੇ ਬੀਚ ਅੰਤ ਦੋਊ ਪਰੈ। ੪੬।","roman":"Ho ghor narak ke beech ant do'oo parai | 46 |","meaning_en":"in the end both of them fall into dreadful hell.","page":2095,"meaning_status":"draft","meaning_pa":"ਪਰ ਅੰਤ ਵਿਚ ਦੋਵੇਾਂ ਘੋਰ ਨਰਕ ਵਿਚ ਪੈਂਦੇ ਹਨ ॥੪੬॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2095,"meaning_status":"draft","meaning_pa":"ਚੌਪਈ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[47],"number_text":"੪੭।","page":2095,"lines":[{"gurmukhi":"ਧਨ ਕੇ ਕਾਜ ਕਰਤ ਸਭ ਕਾਜਾ। ਊਚ ਨੀਚ ਰਾਨਾ ਅਰੁ ਰਾਜਾ।","roman":"Dhan ke kaaj karat sabh kaajaa | ooch neech raanaa aru raajaa |","meaning_en":"For the sake of wealth all do all their work, high and low, rana and king;","page":2095,"meaning_status":"draft","meaning_pa":"ਧਨ (ਦੀ ਪ੍ਰਾਪਤੀ) ਲਈ ਸਭ ਉੱਚੇ ਨੀਵੇਾਂ, ਰਾਣਾ ਅਤੇ ਰਾਜਾ ਕੰਮ ਕਰਦੇ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਖ੍ਯਾਲ ਕਾਲ ਕੋ ਕਿਨੂੰ ਨ ਪਾਯੋ। ਜਿਨ ਇਹ ਚੌਦਹ ਲੋਕ ਬਨਾਯੋ। ੪੭।","roman":"Khyaal kaal ko kinoon na paayo | jin ih chaudah lok banaayo | 47 |","meaning_en":"no one has taken thought of Death, who made these fourteen worlds.","page":2095,"meaning_status":"draft","note":"ਕਾਲ: 'Kal', Time/Death.","meaning_pa":"ਕਿਸੇ ਨੇ ਵੀ ਕਾਲ (ਪ੍ਰਭੂ) ਦਾ ਧਿਆਨ ਨਹੀਂ ਕੀਤਾ, ਜਿਸ ਨੇ ਇਨ੍ਰਹਾ ਚੌਦਾ ਲੋਕਾ ਦੀ ਸਿਰਜਨਾ ਕੀਤੀ ਹੈ ॥੪੭॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":2095,"meaning_status":"draft","meaning_pa":"ਅੜਿਲ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[48],"number_text":"੪੮।","page":2095,"lines":[{"gurmukhi":"ਇਹੀ ਦਰਬ ਕੇ ਲੋਭ ਬੇਦ ਬ੍ਯਾਕਰਨ ਪੜਤ ਨਰ।","roman":"Ihee darab ke lobh bed byaakran parat nar |","meaning_en":"For this greed of wealth, men study the Vedas and grammar;","page":2095,"meaning_status":"draft","meaning_pa":"ਇਸੇ ਧਨ ਦੇ ਲੋਭ ਕਰ ਕੇ ਲੋਕੀਂ ਵੇਦ ਅਤੇ ਵਿਆਕਰਨ ਪੜ੍ਰਹਦੇ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਇਹੀ ਦਰਬ ਕੇ ਲੋਭ ਮੰਤ੍ਰ ਜੰਤ੍ਰਨ ਉਪਦਿਸ ਕਰ।","roman":"Ihee darab ke lobh mantr jantran updis kar |","meaning_en":"for this greed of wealth, they give instruction in mantras and yantras;","page":2095,"meaning_status":"draft","meaning_pa":"ਇਸੇ ਧਨ ਦੇ ਲੋਭ ਕਰ ਕੇ ਮੰਤ੍ਰ ਅਤੇ ਜੰਤ੍ਰ ਉਪਦੇਸੇ ਜਾਦੇ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਇਹੀ ਦਰਬ ਕੇ ਲੋਭ ਦੇਸ ਪਰਦੇਸ ਸਿਧਾਏ।","roman":"Ihee darab ke lobh des pardes sidhaae |","meaning_en":"for this greed of wealth, they go to foreign lands;","page":2095,"meaning_status":"draft","meaning_pa":"ਇਸੇ ਧਨ ਦੇ ਲਾਲਚ ਕਰ ਕੇ ਦੇਸ ਪਰਦੇਸ ਵਿਚ ਜਾਦੇ ਹਨ","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਹੋ ਪਰੇ ਦੂਰਿ ਕਹ ਜਾਇ ਬਹੁਰਿ ਨਿਜੁ ਦੇਸਨ ਆਏ। ੪੮।","roman":"Ho pare doori kah jaai bahuri niju desan aae | 48 |","meaning_en":"they go far away, and then return to their own countries.","page":2095,"meaning_status":"draft","meaning_pa":"ਅਤੇ ਦੂਰ ਦੂਰ ਤਕ ਜਾ ਕੇ ਫਿਰ ਦੇਸ ਪਰਤ ਆਉਾਂਦੇ ਹਨ ॥੪੮॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"Kabitt.","page":2095,"meaning_status":"draft","meaning_pa":"ਕਬਿੱਤ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[49],"number_text":"੪੯।","page":2095,"lines":[{"gurmukhi":"ਏਹੀ ਧਨ ਲੋਭ ਤੇ ਪੜਤ ਬ੍ਯਾਕਰਨ ਸਭੈ","roman":"Ehee dhan lobh te parat byaakran sabhai","meaning_en":"For this greed of wealth, they study all of grammar;","page":2095,"meaning_status":"draft"},{"gurmukhi":"ਏਹੀ ਧਨ ਲੋਭ ਤੇ ਪੁਰਾਨ ਹਾਥ ਧਰੇ ਹੈਂ।","roman":"Ehee dhan lobh te puraan haath dhare hain |","meaning_en":"for this greed of wealth, they have taken the Puranas in hand;","page":2095,"meaning_status":"draft","meaning_pa":"ਇਸੇ ਧਨ ਦੇ ਲੋਭ ਕਰ ਕੇ ਸਾਰੇ ਵਿਆਕਰਣ ਪੜ੍ਰਹਦੇ ਹਨ ਅਤੇ ਇਸੇ ਧਨ ਦੇ ਲਾਲਚ ਕਰ ਕੇ ਪੁਰਾਣਾ ਨੂੰ ਹੱਥ ਵਿਚ ਲੈਂਦੇ ਹਨ।","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"},{"gurmukhi":"ਧਨ ਹੀ ਕੇ ਲੋਭ ਦੇਸ ਛਾਡਿ ਪਰਦੇਸ ਬਸੇ","roman":"Dhan hee ke lobh des chhaadi pardes base","meaning_en":"for greed of wealth, leaving their own land, they live abroad,","page":2095,"meaning_status":"draft"},{"gurmukhi":"ਤਾਤ ਅਰੁ ਮਾਤ ਕੇ ਦਰਸਹੂ ਨ ਕਰੇ ਹੈਂ।","roman":"Taat aru maat ke darashoo na kare hain |","meaning_en":"and do not even see their father and mother;","page":2095,"meaning_status":"draft","meaning_pa":"ਧਨ ਦੇ ਲਾਲਚ ਕਰ ਕੇ ਦੇਸ਼ ਛਡ ਕੇ ਪਰਦੇਸ ਵਸਦੇ ਹਨ ਅਤੇ ਮਾਤਾ ਪਿਤਾ ਦੇ ਦਰਸ਼ਨ ਤਕ ਨਹੀਂ ਕਰਦੇ।","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"},{"gurmukhi":"ਊਚੇ ਦ੍ਰੁਮ ਸਾਲ ਤਹਾ ਲਾਂਬੇ ਬਟ ਤਾਲ ਜਹਾ।","roman":"Ooche drum saal tahaa laanbe bat taal jahaa |","meaning_en":"where there are tall sal trees, and long banyans and palms,","page":2095,"meaning_status":"draft"},{"gurmukhi":"ਤਿਨ ਮੈ ਸਿਧਾਤ ਹੈ ਨ ਜੀ ਮੈ ਨੈਕੁ ਡਰੇ ਹੈਂ।","roman":"Tin mai sidhaat hai na jee mai naiku dare hain |","meaning_en":"among them they go, and are not at all afraid in their hearts;","page":2095,"meaning_status":"draft","meaning_pa":"ਜਿਥੇ ਉੱਚੇ ਉੱਚੇ ਸਾਲ ਅਤੇ ਲੰਬੇ ਲੰਬੇ ਬੋਹੜ ਅਤੇ ਤਾੜ ਦੇ ਬ੍ਰਿਛ ਹਨ, ਉਨ੍ਰਹਾ ਵਿਚ ਜਾਦੇ ਹਨ ਅਤੇ ਹਿਰਦੇ ਵਿਚ ਬਿਲਕੁਲ ਨਹੀਂ ਡਰਦੇ।","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"},{"gurmukhi":"ਧਨ ਕੈ ਨੁਰਾਗੀ ਹੈਂ ਕਹਾਵਤ ਤਿਆਗੀ ਆਪੁ","roman":"Dhan kai nuraagee hain kahaavat tiaagee aapu","meaning_en":"they are lovers of wealth, though they call themselves renouncers;","page":2095,"meaning_status":"draft"},{"gurmukhi":"ਕਾਸੀ ਬੀਚ ਜਏ ਤੇ ਕਮਾਊ ਜਾਇ ਮਰੇ ਹੈਂ। ੪੯।","roman":"Kaasee beech jae te kamaaoo jaai mare hain | 49 |","meaning_en":"those born in Kashi go off earning, and die.","page":2095,"meaning_status":"draft","note":"ਕਾਸੀ ਬੀਚ ਜਏ ਤੇ ਕਮਾਊ ਜਾਇ ਮਰੇ ਹੈਂ: read as 'those born in Kashi, earners, go and die'; uncertain.","meaning_pa":"(ਸਭ) ਧਨ ਨੂੰ ਪਿਆਰ ਕਰਦੇ ਹਨ, ਪਰ ਆਪਣੇ ਆਪ ਨੂੰ ਅਖਵਾਉਾਂਦੇ ਤਿਆਗੀ ਹਨ। (ਉਹ) ਕਾਸ਼ੀ ਵਿਚ ਜੰਮਦੇ ਹਨ ਅਤੇ ਕਮਾਊਾਂ ਵਿਚ ਜਾ ਮਰਦੇ ਹਨ ॥੪੯॥","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"}]},{"type":"heading","kind":"chhand","name":"ਬਿਜੈ ਛੰਦ","gurmukhi":"ਬਿਜੈ ਛੰਦ","roman":"Bijai chhand","meaning_en":"Bijay metre.","page":2097,"meaning_status":"draft","meaning_pa":"ਬਿਜੈ ਛੰਦ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[50],"number_text":"੫੦।","page":2097,"lines":[{"gurmukhi":"ਲਾਲਚ ਏਕ ਲਗੈ ਧਨ ਕੇ ਸਿਰ ਮਧਿ ਜਟਾਨ ਕੇ ਜੂਟ ਸਵਾਰੈ।","roman":"Laalach ek lagai dhan ke sir madhi jataan ke joot savaarai |","meaning_en":"Some, seized by greed for wealth alone, arrange knots of matted hair on their heads;","page":2097,"meaning_status":"draft","meaning_pa":"ਧਨ ਦੇ ਲਾਲਚ ਵਿਚ ਲਗੇ ਹੋਏ ਕਈ ਸਿਰ ਉਤੇ ਜਟਾਵਾ ਦੇ ਜੂੜੇ ਸੰਵਾਰਦੇ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਕਾਠ ਕੀ ਕੰਠਿਨ ਕੌ ਧਰਿ ਕੈ ਇਕ ਕਾਨਨ ਮੈ ਬਿਨੁ ਕਾਨਿ ਪਧਾਰੈ।","roman":"Kaath kee kanthin kau dhari kai ik kaanan mai binu kaani padhaarai |","meaning_en":"some put wooden necklaces on their necks and go into the forest without regard;","page":2097,"meaning_status":"draft","note":"ਬਿਨੁ ਕਾਨਿ: read as 'without regard/shame'; uncertain.","meaning_pa":"ਲਕੜੀ ਦੀ ਮਾਲਾ (ਕੰਠੀ) ਧਾਰਨ ਕਰ ਕੇ ਕਈ ਜੰਗਲਾ ਵਿਚ ਬਿਨਾ ਗ਼ੈਰਤ ਦੇ ਚਲੇ ਜਾਦੇ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਮੋਚਨ ਕੌ ਗਹਿ ਕੈ ਇਕ ਹਾਥਨ ਸੀਸ ਹੂ ਕੇ ਸਭ ਕੇਸ ਉਪਾਰੈ।","roman":"Mochan kau gahi kai ik haathan sees hoo ke sabh kes upaarai |","meaning_en":"some take tweezers in hand and pull out all the hair of their heads;","page":2097,"meaning_status":"draft","meaning_pa":"ਕਈ ਹੱਥ ਵਿਚ ਮੋਚਨਾ ਪਕੜ ਕੇ ਸਿਰ ਦੇ ਸਾਰੇ ਵਾਲ ਪੁਟ ਸੁਟਦੇ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਡਿੰਭੁ ਕਰੈ ਜਗ ਡੰਡਨ ਕੌ ਇਹ ਲੋਕ ਗਯੋ ਪਰਲੋਕ ਬਿਗਾਰੈ। ੫੦।","roman":"Dinbhu karai jag dandan kau ih lok gayo parlok bigaarai | 50 |","meaning_en":"they practise hypocrisy for the sake of staffs (alms); this world is lost and the next is spoilt.","page":2097,"meaning_status":"draft","note":"ਡੰਡਨ: read as 'staffs' (ascetic's staff), or 'fines'; uncertain.","meaning_pa":"ਜਗਤ ਨੂੰ ਦੰਡ ਦੇਣ ਲਈ ਪਾਖੰਡ ਕਰਦੇ ਹਨ। (ਉਨ੍ਰਹਾ ਦਾ) ਇਹ ਲੋਕ ਤਾ ਚਲਾ ਗਿਆ ਹੈ, ਪਰਲੋਕ ਵੀ ਨਸ਼ਟ ਕਰ ਲੈਂਦੇ ਹਨ ॥੫੦॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[51],"number_text":"੫੧।","page":2097,"lines":[{"gurmukhi":"ਮਾਟੀ ਕੇ ਲਿੰਗ ਬਨਾਇ ਕੈ ਪੂਜਤ ਤਾ ਮੈ ਕਹੋ ਇਨ ਕਾ ਸਿਧਿ ਪਾਈ।","roman":"Maatee ke ling banaai kai poojat taa mai kaho in kaa sidhi paaee |","meaning_en":"They make lingams of clay and worship them; say, what success have they gained in it?","page":2097,"meaning_status":"draft","meaning_pa":"ਮਿੱਟੀ ਦੇ ਲਿੰਗ ਬਣਾ ਕੇ ਪੂਜਦੇ ਹਨ। ਦਸੋ, ਉਨ੍ਰਹਾ ਵਿਚ ਇਨ੍ਰਹਾ ਨੇ ਕੀ ਸਿੱਧੀ ਪ੍ਰਾਪਤ ਕੀਤੀ ਹੈ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜੋ ਨਿਰਜੋਤਿ ਭਯੋ ਜਗ ਜਾਨਤ ਤਾਹਿ ਕੇ ਆਗੇ ਲੈ ਜੋਤਿ ਜਗਾਈ।","roman":"Jo nirjoti bhayo jag jaanat taahi ke aage lai joti jagaaee |","meaning_en":"Before the one whom the world knows has become lightless, they take a flame and light it.","page":2097,"meaning_status":"draft","meaning_pa":"ਜਗਤ ਜਾਣਦਾ ਹੈ ਕਿ ਜੋ (ਮੂਰਤੀਆਂ) ਨਿਰਜੋਤਿ ਹਨ, ਉਨ੍ਰਹਾ ਦੇ ਅਗੇ ਜੋਤਿ ਜਗਾਉਾਂਦੇ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਪਾਇ ਪਰੇ ਪਰਮੇਸ੍ਵਰ ਜਾਨਿ ਅਜਾਨ ਬਡੈ ਕਰਿ ਕੈ ਹਠਤਾਈ।","roman":"Paai pare parmesvar jaani ajaan badai kari kai hathtaaee |","meaning_en":"They fall at the feet of the ignorant one taking him for the Lord, with great obstinacy;","page":2097,"meaning_status":"draft","meaning_pa":"(ਉਹ ਪੱਥਰ ਨੂੰ) ਪਰਮੇਸਰ ਸਮਝ ਕੇ ਉਸ ਦੇ ਪੈਰੀਂ ਪੈਂਦੇ ਹਨ ਅਤੇ ਹਠ ਕਰ ਕੇ ਅਜਾਣ ਬਣਦੇ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਚੇਤ ਅਚੇਤ ਸੁਚੇਤਨ ਕੋ ਚਿਤ ਕੀ ਤਜਿ ਕੈ ਚਟ ਦੈ ਦੁਚਿਤਾਈ। ੫੧।","roman":"Chet achet suchetan ko chit kee taji kai chat dai duchitaaee | 51 |","meaning_en":"abandoning the mind's conscious, unconscious and truly conscious, they quickly give double-mindedness.","page":2097,"meaning_status":"draft","note":"Line is obscure; read as printed; uncertain.","meaning_pa":"ਹੇ ਮੂਰਖੋ! ਜ਼ਰਾ ਸਮਝੋ, ਸੁਚੇਤ ਹੋਵੋ ਅਤੇ ਤੁਰਤ ਚਿਤ ਦੀ ਦੁਬਿਧਾ ਨੂੰ ਛਡ ਦਿਓ ॥੫੧॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[52],"number_text":"੫੨।","page":2097,"lines":[{"gurmukhi":"ਕਾਸੀ ਕੇ ਬੀਚ ਪੜੈ ਬਹੁ ਕਾਲ ਬੁਟੰਤ ਮੈ ਅੰਤ ਮਰੈ ਪੁਨਿ ਜਾਈ।","roman":"Kaasee ke beech parai bahu kaal butant mai ant marai puni jaaee |","meaning_en":"They study a long time in Kashi; in [unclear] at the end they die and go.","page":2097,"meaning_status":"draft","note":"ਬੁਟੰਤ: cannot be read with confidence (perhaps a herb or place); left as [unclear]."},{"gurmukhi":"ਤਾਤ ਰਹਾ ਅਰੁ ਮਾਤ ਕਹੂੰ ਬਨਿਤਾ ਸੁਤ ਪੁਤ੍ਰ ਕਲਤ੍ਰਨ ਭਾਈ।","roman":"Taat rahaa aru maat kahoon banitaa sut putr kaltran bhaaee |","meaning_en":"Where was father, where mother, wife, son, sons, wives, brothers?","page":2097,"meaning_status":"draft","meaning_pa":"ਕਾਸ਼ੀ ਵਿਚ ਬਹੁਤ ਸਮੇਾਂ ਤਕ ਪੜ੍ਰਹਦੇ ਹਨ ਅਤੇ ਫਿਰ ਅੰਤ ਵਿਚ ਭੂਟਾਨ ('ਭੁਟੰਤ') ਵਿਚ ਜਾ ਮਰਦੇ ਹਨ। ਪਿਤਾ ਕਿਥੇ ਰਿਹਾ ਹੈ ਅਤੇ ਮਾਤ ਕਿਤੇ ਹੈ, ਇਸਤਰੀ, ਪੁੱਤਰ, ਪੁੱਤਰ ਦੀ ਇਸਤਰੀ ਅਤੇ ਭਰਾ (ਸਭ ਹੋਰਾ ਥਾਵਾ ਤੇ ਹਨ)।","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"},{"gurmukhi":"ਦੇਸ ਬਿਦੇਸ ਫਿਰੈ ਤਜਿ ਕੈ ਘਰ ਥੋਰੀ ਸੀ ਸੀਖਿ ਕੈ ਚਾਤੁਰਤਾਈ।","roman":"Des bides phirai taji kai ghar thoree see seekhi kai chaaturtaaee |","meaning_en":"They roam in country and foreign lands, leaving home, having learned a little cunning.","page":2097,"meaning_status":"draft","meaning_pa":"ਥੋੜੀ ਜਿਨੀ ਚਾਲਾਕੀ ਸਿਖ ਕੇ, ਘਰ ਨੂੰ ਛਡ ਕੇ ਦੇਸ਼ ਵਿਦੇਸ਼ ਫਿਰਦੇ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਲੋਭ ਕੀ ਲੀਕ ਨ ਲਾਂਘੀ ਕਿਸੂ ਨਰ ਲੋਭ ਰਹਾ ਸਭ ਲੋਗ ਲੁਭਾਈ। ੫੨।","roman":"Lobh kee leek na laanghee kisoo nar lobh rahaa sabh log lubhaaee | 52 |","meaning_en":"No man has crossed the line of greed; greed has remained, deluding all people.","page":2097,"meaning_status":"draft","meaning_pa":"ਕਿਸੇ ਵਿਅਕਤੀ ਨੇ ਵੀ ਲੋਭ ਦੀ ਲਕੀਰ ਨਹੀਂ ਲੰਘੀ, ਲੋਭ ਸਾਰਿਆਂ ਲੋਕਾ ਨੂੰ ਲੁਭਾ ਰਿਹਾ ਹੈ ॥੫੨॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"Kabitt.","page":2097,"meaning_status":"draft","meaning_pa":"ਕਬਿੱਤ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[53],"number_text":"੫੩।","page":2097,"lines":[{"gurmukhi":"ਏਕਨ ਕੋ ਮੂੰਡਿ ਮਾਂਡਿ ਏਕਨ ਸੌ ਲੇਹਿ ਡਾਂਡ","roman":"Ekan ko moondi maandi ekan sau lehi daand","meaning_en":"Having shaved the heads of some, they take fines from others;","page":2097,"meaning_status":"draft"},{"gurmukhi":"ਏਕਨ ਕੈ ਕੰਠੀ ਕਾਠ ਕੰਠ ਮੈ ਡਰਤ ਹੈਂ।","roman":"Ekan kai kanthee kaath kanth mai darat hain |","meaning_en":"some, fearful, wear wooden necklaces about their necks;","page":2097,"meaning_status":"draft","meaning_pa":"ਇਕਨਾ ਦੇ ਸਿਰ ਮੁੰਨ ਲੈਂਦੇ ਹਨ (ਭਾਵ ਲੁਟ ਪੁਟ ਲੈਂਦੇ ਹਨ) ਇਕਨਾ ਤੋਂ ਦੰਡ ਲੈਂਦੇ ਹਨ ਅਤੇ ਇਕਨਾ ਦੇ ਗਲੇ ਵਿਚ ਕਾਠ ਦੀ ਮਾਲਾ ਪਾ ਦਿੰਦੇ ਹਨ।","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"},{"gurmukhi":"ਏਕਨ ਦ੍ਰਿੜਾਵੈ ਮੰਤ੍ਰ ਏਕਨ ਲਿਖਾਵੈ ਜੰਤ੍ਰ","roman":"Ekan driraavai mantr ekan likhaavai jantr","meaning_en":"to some they make a mantra firm, for some they have a yantra written,","page":2097,"meaning_status":"draft"},{"gurmukhi":"ਏਕਨ ਕੌ ਤੰਤ੍ਰਨ ਪ੍ਰਬੋਧ੍ਯੋ ਈ ਕਰਤ ਹੈਂ।","roman":"Ekan kau tantran prabodhyo ee karat hain |","meaning_en":"and some they instruct in tantras.","page":2097,"meaning_status":"draft","meaning_pa":"ਇਕਨਾ ਨੂੰ ਮੰਤ੍ਰ ਦ੍ਰਿੜ੍ਰਹ ਕਰਦੇ ਹਨ, ਇਕਨਾ ਨੂੰ ਜੰਤ੍ਰ ਲਿਖਵਾਉਾਂਦੇ ਹਨ ਅਤੇ ਇਕਨਾ ਨੂੰ ਤੰਤ੍ਰ ਦੀ ਸਿਖਿਆ ਦਿੰਦੇ ਹਨ।","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"},{"gurmukhi":"ਏਕਨ ਕੇ ਬਿਦ੍ਯਾ ਕੋ ਬਿਵਾਦਨ ਬਤਾਵੈ ਡਿੰਭ","roman":"Ekan ke bidyaa ko bivaadan bataavai dinbh","meaning_en":"To some they present the disputes of learning with hypocrisy,","page":2097,"meaning_status":"draft"},{"gurmukhi":"ਜਗ ਕੋ ਦਿਖਾਇ ਜ੍ਯੋ ਕ੍ਯੋ ਮਾਤ੍ਰਾ ਕੌ ਹਰਤ ਹੈ।","roman":"Jag ko dikhaai jyo kyo maatraa kau harat hai |","meaning_en":"and showing it to the world, by whatever means they take away the wealth.","page":2097,"meaning_status":"draft","note":"ਮਾਤ੍ਰਾ: read as 'wealth/means'; uncertain.","meaning_pa":"ਇਕਨਾ ਨੂੰ ਵਿਦਿਆ ਦਾ ਵਿਵਾਦ ਦਸਦੇ ਹਨ ਅਤੇ ਜਗਤ ਨੂੰ ਪਾਖੰਡ ਵਿਖਾ ਕੇ ਜਿਵੇਾਂ ਕਿਵੇਾਂ ਧਨ ਨੂੰ ਹਰ ਲੈਂਦੇ ਹਨ।","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"},{"gurmukhi":"ਮੈਯਾ ਕੌ ਨ ਮਾਨੈ ਮਹਾ ਕਾਲੈ ਨ ਮਨਾਵੈ","roman":"Maiyaa kau na maanai mahaa kaalai na manaavai","meaning_en":"They do not honour the Mother, nor do they propitiate Great Death;","page":2097,"meaning_status":"draft","note":"ਕਾਲੈ: read as 'Kal' (Death/Time); could be Kali; uncertain."},{"gurmukhi":"ਮੂੜ ਮਾਟੀ ਕੌ ਮਾਨਤ ਤਾ ਤੇ ਮਾਂਗਤ ਮਰਤ ਹੈ। ੫੩।","roman":"Moor maatee kau maanat taa te maangat marat hai | 53 |","meaning_en":"the fool honours clay, and so dies begging.","page":2097,"meaning_status":"draft","meaning_pa":"ਮਾਤਾ (ਦੇਵੀ) ਨੂੰ ਨਹੀਂ ਮੰਨਦੇ ਅਤੇ ਨਾ ਮਹਾ ਕਾਲ ਨੂੰ ਮੰਨਦੇ ਹਨ (ਬਸ) ਮੂਰਖ ਮਿੱਟੀ ਦੀ ਪੂਜਾ ਕਰਦੇ ਹਨ ਅਤੇ ਉਸ ਤੋਂ ਮੰਗਦੇ ਮੰਗਦੇ ਮਰੀ ਜਾ ਰਹੇ ਹਨ ॥੫੩॥","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":2097,"meaning_status":"draft","meaning_pa":"ਸਵੈਯਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[54],"number_text":"੫੪।","page":2097,"lines":[{"gurmukhi":"ਚੇਤ ਅਚੇਤੁ ਕੀਏ ਜਿਨ ਚੇਤਨ ਤਾਹਿ ਅਚੇਤ ਨ ਕੋ ਠਹਰਾਵੈ।","roman":"Chet achetu kee'e jin chetan taahi achet na ko thahraavai |","meaning_en":"He who made the conscious unconscious, and the unconscious conscious, none should set Him down as unconscious;","page":2097,"meaning_status":"draft","note":"Line is obscure; read as printed; uncertain.","meaning_pa":"ਜਿਸ ਚੇਤਨ ਸੱਤਾ ਨੇ ਚੇਤ ਅਤੇ ਅਚੇਤ (ਜੜ-ਚੇਤਨ) ਨੂੰ ਸਿਰਜਿਆ ਹੈ, ਉਸ ਨੂੰ ਮੂਰਖ ਕੁਝ ਨਹੀਂ ਪਛਾਣਦਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਤਾਹਿ ਕਹੈ ਪਰਮੇਸ੍ਵਰ ਕੈ ਮਨ ਮਾਹਿ ਕਹੇ ਘਟਿ ਮੋਲ ਬਿਕਾਵੈ।","roman":"Taahi kahai parmesvar kai man maahi kahe ghati mol bikaavai |","meaning_en":"they call Him the Supreme Lord in the mind, but by saying so He is sold at a lessened price.","page":2097,"meaning_status":"draft","note":"ਘਟਿ ਮੋਲ ਬਿਕਾਵੈ: read as 'is sold at a reduced price'; uncertain.","meaning_pa":"ਉਸ ਨੂੰ ਮਨ ਵਿਚ ਪਰਮੇਸ਼੍ਵਰ ਕਹਿੰਦੇ ਹਨ ਜੋ ਬਹੁਤ ਘਟ ਮੁੱਲ ਤੇ ਵਿਕਦਾ ਹੈ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜਾਨਤ ਹੈ ਨ ਅਜਾਨ ਬਡੈ ਸੁ ਇਤੇ ਪਰ ਪੰਡਿਤ ਆਪੁ ਕਹਾਵੈ।","roman":"Jaanat hai na ajaan badai su ite par pandit aapu kahaavai |","meaning_en":"The great ignorant one does not know, and on top of that calls himself a pandit;","page":2097,"meaning_status":"draft","meaning_pa":"ਇਹ ਵੱਡੇ ਅਜਾਣ ਹਨ, ਕੁਝ ਵੀ ਨਹੀਂ ਜਾਣਦੇ, ਪਰ (ਤਾ ਵੀ) ਆਪਣੇ ਆਪ ਨੂੰ ਪੰਡਿਤ ਅਖਵਾਉਾਂਦੇ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਲਾਜ ਕੇ ਮਾਰੇ ਮਰੈ ਨ ਮਹਾ ਲਟ ਐਠਹਿ ਐਠ ਅਮੈਠਿ ਗਵਾਵੈ। ੫੪।","roman":"Laaj ke maare marai na mahaa lat aithhi aith amaithi gavaavai | 54 |","meaning_en":"he does not die of shame, the great rogue, who twists and twists his twists and loses them.","page":2097,"meaning_status":"draft","note":"ਲਟ ਐਠਹਿ ਐਠ ਅਮੈਠਿ: obscure; read as printed; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਬਿਜੈ ਛੰਦ","gurmukhi":"ਬਿਜੈ ਛੰਦ","roman":"Bijai chhand","meaning_en":"Bijay metre.","page":2097,"meaning_status":"draft"},{"type":"verse","number":[55],"number_text":"੫੫।","page":2097,"lines":[{"gurmukhi":"ਗਤਮਾਨ ਕਹਾਵਤ ਗਾਤ ਸਭੈ ਕਛੂ ਜਾਨੈ ਨ ਬਾਤ ਗਤਾਗਤ ਹੈ।","roman":"Gatmaan kahaavat gaat sabhai kachhoo jaanai na baat gataagat hai |","meaning_en":"All call themselves free of pride, yet they know nothing of the matter of coming and going.","page":2097,"meaning_status":"draft","note":"ਗਤਮਾਨ: read as 'free of pride'; uncertain.","meaning_pa":"ਸ਼ਰਮ ਦੇ ਮਾਰੇ ਇਹ ਢੀਠ ਮਰਦੇ ਨਹੀਂ ਹਨ ਅਤੇ ਅਭਿਮਾਨ ਵਿਚ ਹੀ ਆਕੜ ਕੇ (ਜੀਵਨ) ਨਸ਼ਟ ਕਰ ਲੈਂਦੇ ਹਨ ॥੫੪॥ ਬਿਜੈ ਛੰਦ: ਸਾਰੇ ਮਨੁੱਖ ਆਪਣੇ ਆਪ ਨੂੰ ਮੁਕਤ ਸਮਝਦੇ ਹਨ, ਪਰ ਉਹ ਆਵਾਗਵਣ ('ਗਤਾਗਤ') ਦੀ ਕੁਝ ਵੀ ਗੱਲ ਨਹੀਂ ਸਮਝਦੇ।","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 3 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"},{"gurmukhi":"ਦੁਤਿਮਾਨ ਘਨੇ ਬਲਵਾਨ ਬਡੇ ਹਮ ਜਾਨਤ ਜੋਗ ਮਧੇ ਜਤ ਹੈ।","roman":"Dutimaan ghane balvaan bade ham jaanat jog madhe jat hai |","meaning_en":"'Very radiant, very strong, great; we know them as celibates among the yogis.'","page":2097,"meaning_status":"draft","meaning_pa":"ਅਸੀਂ ਜਾਣਦੇ ਹਾ ਕਿ ਬਹੁਤ ਤੇਜਸਵੀ ਅਤੇ ਬਲਵਾਨ ਜੋਗ ਵਿਚ ਜਕੜੇ ਹੋਏ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਪਾਹਨ ਕੈ ਕਹੈ ਬੀਚ ਸਹੀ ਸਿਵ ਜਾਨੈ ਨ ਮੂੜ ਮਹਾ ਮਤ ਹੈ।","roman":"Paahan kai kahai beech sahee siv jaanai na moor mahaa mat hai |","meaning_en":"They say that Shiva is truly in a stone; the fool, greatly intoxicated, does not know.","page":2097,"meaning_status":"draft","meaning_pa":"ਉਹ ਪੱਥਰ ਵਿਚ ਹੀ ਸਹੀ ਸ਼ਿਵ ਨੂੰ ਮੰਨਦੇ ਹਨ ਪਰ (ਸਹੀ ਸ਼ਿਵ ਨੂੰ ਉਹ) ਮੂਰਖ ਸਮਝਦੇ ਨਹੀਂ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਤੁਮਹੂੰ ਨ ਬਿਚਾਰਿ ਸੁ ਜਾਨ ਕਹੋ ਇਨ ਮੈ ਕਹਾ ਪਾਰਬਤੀ ਪਤਿ ਹੈ। ੫੫।","roman":"Tumhoon na bichaari su jaan kaho in mai kahaa paarabtee pati hai | 55 |","meaning_en":"You too have not considered; say, knowing it, where in these is the husband of Parvati?","page":2097,"meaning_status":"draft","note":"Line is obscure; read as printed; uncertain.","meaning_pa":"ਤੁਸੀਂ ਹੀ ਵਿਚਾਰ ਕੇ ਕਿਉਾਂ ਨਹੀਂ ਕਹਿੰਦੇ ਕਿ ਇਨ੍ਰਹਾ ਪੱਥਰਾ ਵਿਚ ਕੀ ਪਾਰਬਤੀ ਦੇ ਪਤੀ ਸ਼ਿਵ ਮੌਜੂਦ ਹਨ? ॥੫੫॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[56],"number_text":"੫੬।","page":2099,"lines":[{"gurmukhi":"ਮਾਟੀ ਕੌ ਸੀਸ ਨਿਵਾਵਤ ਹੈ ਜੜ ਯਾ ਤੇ ਕਹੋ ਤੁਹਿ ਕਾ ਸਿਧਿ ਐਹੈ।","roman":"Maatee kau sees nivaavat hai jar yaa te kaho tuhi kaa sidhi aihai |","meaning_en":"The dull one bows his head to clay; say, what success will you gain from this?","page":2099,"meaning_status":"draft","meaning_pa":"ਮੂਰਖ (ਲੋਕ) ਮਿੱਟੀ ਅਗੇ ਸਿਰ ਨਿਵਾਉਾਂਦੇ ਹਨ। ਭਲਾ ਦਸੋ ਇਸ ਤੋਂ ਤੁਸੀਂ ਕੀ ਸਿੱਧੀ ਹਾਸਲ ਕਰੋਗੇ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜੌਨ ਰਿਝਾਇ ਲਯੋ ਜਗ ਕੌ ਤਵ ਚਾਵਰ ਡਾਰਤ ਰੀਝਿ ਨ ਜੈ ਹੈ।","roman":"Jaun rijhaai layo jag kau tav chaavar daarat reejhi na jai hai |","meaning_en":"The One who has charmed the world will not be pleased by your waving a fly-whisk over him;","page":2099,"meaning_status":"draft","meaning_pa":"ਜਿਸ (ਪਰਮ ਸੱਤਾ) ਨੇ ਸਾਰੇ ਸੰਸਾਰ ਨੂੰ ਪ੍ਰਸੰਨ ਕਰ ਰਖਿਆ ਹੈ (ਰਿਝਾਇਆ ਹੋਇਆ ਹੈ) (ਉਹ) ਤੁਹਾਡੇ ਚਾਵਲ ਭੇਾਂਟ ਕਰਨ ਨਾਲ ਪ੍ਰਸੰਨ ਨਹੀਂ ਹੋ ਜਾਵੇਗਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਧੂਪ ਜਗਾਇ ਕੈ ਸੰਖ ਬਜਾਇ ਸੁ ਫੂਲਨ ਕੀ ਬਰਖਾ ਬਰਖੈ ਹੈ।","roman":"Dhoop jagaai kai sankh bajaai su phoolan kee barkhaa barkhai hai |","meaning_en":"lighting incense, blowing a conch, and showering a rain of flowers,","page":2099,"meaning_status":"draft","meaning_pa":"ਧੂਪ ਜਗਾ ਕੇ ਅਤੇ ਸੰਖ ਵਜਾ ਕੇ ਫੁਲਾ ਦੀ ਬਰਖਾ ਕਰਦੇ ਹੋ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਅੰਤ ਉਪਾਇ ਕੈ ਹਾਰਿ ਹੈਂ ਰੇ ਪਸੁ ਪਾਹਨ ਮੈ ਪਰਮੇਸ੍ਰ ਨ ਪੈ ਹੈ। ੫੬।","roman":"Ant upaai kai haari hain re pasu paahan mai parmesr na pai hai | 56 |","meaning_en":"in the end you will be defeated, beast; you will not find the Lord in a stone.","page":2099,"meaning_status":"draft","note":"ਪਰਮੇਸ੍ਰ: printed so (Parmeshar).","meaning_pa":"ਹੇ ਮੂਰਖੋ! ਅੰਤ ਵਿਚ (ਹਰ ਪ੍ਰਕਾਰ ਦੇ) ਉਪਾ ਕਰ ਕੇ ਹਾਰ ਜਾਓਗੇ, ਪਰ ਪੱਥਰਾ (ਭਾਵ-ਮੂਰਤੀਆਂ) ਵਿਚ ਪਰਮਾਤਮਾ ਨੂੰ ਪ੍ਰਾਪਤ ਨਹੀਂ ਕਰ ਸਕੋਗੇ ॥੫੬॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[57],"number_text":"੫੭।","page":2099,"lines":[{"gurmukhi":"ਏਕਨ ਜੰਤ੍ਰ ਸਿਖਾਵਤ ਹੈ ਦਿਜ ਏਕਨ ਮੰਤ੍ਰ ਪ੍ਰਯੋਗ ਬਤਾਵੈ।","roman":"Ekan jantr sikhaavat hai dij ekan mantr prayog bataavai |","meaning_en":"Some brahmins teach yantras, some show the use of mantras;","page":2099,"meaning_status":"draft","meaning_pa":"ਇਹ ਬ੍ਰਾਹਮਣ ਇਕਨਾ ਨੂੰ ਜੰਤ੍ਰ ਸਿਖਾਉਾਂਦੇ ਹਨ ਅਤੇ ਇਕਨਾ ਨੂੰ ਮੰਤ੍ਰ ਦੀ ਵਰਤੋਂ ਕਰਨੀ ਦਸਦੇ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜੋ ਨ ਭਿਜੈ ਇਨ ਬਾਤਨ ਤੇ ਤਿਹ ਗੀਤਿ ਕਬਿਤ ਸਲੋਕ ਸੁਨਾਵੈ।","roman":"Jo na bhijai in baatan te tih geeti kabit salok sunaavai |","meaning_en":"whom these things do not melt, to him he sings songs, kabitts and slokas.","page":2099,"meaning_status":"draft","meaning_pa":"ਜੋ ਇਨ੍ਰਹਾ ਗੱਲਾ ਨਾਲ ਪ੍ਰਭਾਵਿਤ ਨਹੀਂ ਹੁੰਦਾ, ਉਨ੍ਰਹਾ ਨੂੰ ਗੀਤ, ਕਬਿੱਤ: ਅਤੇ ਸ਼ਲੋਕ ਸੁਣਾਉਾਂਦੇ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਦ੍ਯੋਸ ਹਿਰੈ ਧਨ ਲੋਗਨ ਕੇ ਗ੍ਰਿਹ ਚੋਰੁ ਚਕੈ ਠਗ ਦੇਖਿ ਲਜਾਵੈ।","roman":"Dyos hirai dhan logan ke grih choru chakai thag dekhi lajaavai |","meaning_en":"By day he steals wealth from people's houses; a thief is startled and a cheat is ashamed to see him;","page":2099,"meaning_status":"draft","note":"ਦ੍ਯੋਸ: read as 'by day'; uncertain.","meaning_pa":"(ਇਹ ਬ੍ਰਾਹਮਣ) ਦਿਨ ਦਿਹਾੜੇ ਲੋਕਾ ਦੇ ਘਰਾ ਤੋਂ ਧਨ ਚੁਰਾ ਲੈਂਦੇ ਹਨ। (ਉਨ੍ਰਹਾ ਪ੍ਰਬੀਨਤਾ ਨੂੰ) ਵੇਖ ਕੇ ਚੋਰ ਹੈਰਾਨ ਹੋ ਜਾਦੇ ਹਨ ਅਤੇ ਠੱਗ ਵੇਖ ਕੇ ਸ਼ਰਮਸਾਰ ਹੁੰਦੇ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਕਾਨਿ ਕਰੈ ਨਹਿ ਕਾਜੀ ਕੁਟਵਾਰ ਕੀ ਮੂੰਡਿ ਕੈ ਮੂੰਡਿ ਮੁਰੀਦਨ ਖਾਵੈ। ੫੭।","roman":"Kaani karai nahi kaajee kutvaar kee moondi kai moondi mureedan khaavai | 57 |","meaning_en":"he has no regard for the qazi or the kotwal, and shaving head after head he eats off his disciples.","page":2099,"meaning_status":"draft","meaning_pa":"ਇਹ ਕਾਜ਼ੀ ਅਤੇ ਕੋਤਵਾਲ ਤਕ ਦੀ ਪਰਵਾਹ ਨਹੀਂ ਕਰਦੇ ਅਤੇ ਮੁਰੀਦਾ ਨੂੰ ਲੁਟ ਲੁਟ ਕੇ ਖਾ ਜਾਦੇ ਹਨ ॥੫੭॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2099,"meaning_status":"draft","meaning_pa":"ਦੋਹਰਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[58],"number_text":"੫੮।","page":2099,"lines":[{"gurmukhi":"ਪਾਹਨ ਕੀ ਪੂਜਾ ਕਰੇ ਜੋ ਹੈ ਅਧਿਕ ਅਚੇਤ।","roman":"Paahan kee poojaa kare jo hai adhik achet |","meaning_en":"One who worships stone is very unwise;","page":2099,"meaning_status":"draft"},{"gurmukhi":"ਭਾਂਗ ਨ ਏਤੇ ਪਰ ਭਖੈ ਜਾਨਤ ਆਪ ਸੁਚੇਤ। ੫੮।","roman":"Bhaang na ete par bhakhai jaanat aap suchet | 58 |","meaning_en":"and yet he does not eat bhang, and thinks himself wise.","page":2099,"meaning_status":"draft","meaning_pa":"ਜੋ ਅਧਿਕ ਮੂਰਖ ਹਨ, ਉਹੀ ਪੱਥਰਾ ਦੀ ਪੂਜਾ ਕਰਦੇ ਹਨ। ਇਤਨਾ ਹੋਣ ਤੇ ਵੀ ਭੰਗ ਨਹੀਂ ਖਾਦੇ, ਪਰ ਆਪਣੇ ਆਪ ਨੂੰ ਸਚੇਤ (ਸਮਝਦਾਰ) ਸਮਝਦੇ ਹਨ ॥੫੮॥","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"}]},{"type":"heading","kind":"chhand","name":"ਤੋਟਕ ਛੰਦ","gurmukhi":"ਤੋਟਕ ਛੰਦ","roman":"Totak chhand","meaning_en":"Totak metre.","page":2099,"meaning_status":"draft","meaning_pa":"ਤੋਟਕ ਛੰਦ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[59],"number_text":"੫੯।","page":2099,"lines":[{"gurmukhi":"ਧਨ ਕੇ ਲਗਿ ਲੋਭ ਗਏ ਅਨਤੈ। ਤਜਿ ਮਾਤ ਪਿਤਾ ਸੁਤ ਬਾਲ ਕਿਤੈ।","roman":"Dhan ke lagi lobh gae antai | taji maat pitaa sut baal kitai |","meaning_en":"In greed for wealth they have gone elsewhere, leaving mother, father, son and child somewhere;","page":2099,"meaning_status":"draft","meaning_pa":"ਇਹ ਮਾਤਾ, ਪਿਤਾ, ਪੁੱਤਰ ਅਤੇ ਇਸਤਰੀ ਨੂੰ ਕਿਤੇ ਛਡ ਕੇ ਧਨ ਦੇ ਲੋਭ ਕਰ ਕੇ ਹੋਰ ਥਾ ਚਲੇ ਜਾਦੇ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਬਸਿ ਕੈ ਬਹੁ ਮਾਸ ਤਹਾ ਹੀ ਮਰੈ। ਫਿਰਿ ਕੈ ਗ੍ਰਿਹਿ ਕੇ ਨਹਿ ਪੰਥ ਪਰੈ। ੫੯।","roman":"Basi kai bahu maas tahaa hee marai | phiri kai grihi ke nahi panth parai | 59 |","meaning_en":"living many months there they die there, and do not again set foot on the road home.","page":2099,"meaning_status":"draft","meaning_pa":"(ਉਹ) ਉਥੇ ਬਹੁਤ ਮਹੀਨੇ (ਲੰਬੇ ਸਮੇਾਂ ਤਕ) ਰਹਿ ਕੇ ਉਥੇ ਹੀ ਮਰ ਜਾਦੇ ਹਨ ਅਤੇ ਫਿਰ ਘਰ ਦੇ ਮਾਰਗ ਉਤੇ ਨਹੀਂ ਪੈਂਦੇ ॥੫੯॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2099,"meaning_status":"draft","meaning_pa":"ਦੋਹਰਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[60],"number_text":"੬੦।","page":2099,"lines":[{"gurmukhi":"ਧਨੀ ਲੋਗ ਹੈ ਪੁਹਪ ਸਮ ਗੁਨਿ ਜਨ ਭੌਰ ਬਿਚਾਰ।","roman":"Dhanee log hai puhap sam guni jan bhaur bichaar |","meaning_en":"Rich people are like flowers; consider the learned folk as bees;","page":2099,"meaning_status":"draft","meaning_pa":"ਧਨਵਾਨ ਲੋਕ ਫੁਲਾ ਦੇ ਸਮਾਨ ਹਨ ਅਤੇ ਗੁਨੀ ਜਨ (ਭਾਵ ਬ੍ਰਾਹਮਣ) ਭੌਰਿਆਂ ਵਰਗੇ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਗੂੰਜ ਰਹਤ ਤਿਹ ਪਰ ਸਦਾ ਸਭ ਧਨ ਧਾਮ ਬਿਸਾਰ। ੬੦।","roman":"Goonj rahat tih par sadaa sabh dhan dhaam bisaar | 60 |","meaning_en":"they always hum over them, forgetting all wealth and home.","page":2099,"meaning_status":"draft","meaning_pa":"ਉਹ ਘਰ ਬਾਹਰ ਸਭ ਕੁਝ ਭੁਲਾ ਕੇ, ਸਦਾ ਉਨ੍ਰਹਾ (ਧਨਵਾਨਾ) ਉਤੇ ਗੂੰਜਦੇ ਰਹਿੰਦੇ ਹਨ ॥੬੦॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2099,"meaning_status":"draft","meaning_pa":"ਚੌਪਈ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[61],"number_text":"੬੧।","page":2099,"lines":[{"gurmukhi":"ਸਭ ਕੋਊ ਅੰਤ ਕਾਲ ਬਸਿ ਭਯਾ। ਧਨ ਕੀ ਆਸ ਨਿਕਰਿ ਤਜਿ ਗਯਾ।","roman":"Sabh ko'oo ant kaal basi bhayaa | dhan kee aas nikri taji gayaa |","meaning_en":"Everyone came under the power of Death at the end; leaving, he went out with hope of wealth.","page":2099,"meaning_status":"draft","meaning_pa":"ਸਭ ਕੋਈ ਅੰਤ ਵਿਚ ਕਾਲ ਦੇ ਵਸ ਵਿਚ ਹੁੰਦੇ ਹਨ ਅਤੇ ਧਨ ਦੀ ਆਸ ਵਿਚ ਹੀ (ਸਭ ਕੁਝ) ਛਡ ਕੇ ਨਿਕਲ ਜਾਦੇ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਆਸਾ ਕਰਤ ਗਯਾ ਸੰਸਾਰਾ। ਇਹ ਆਸਾ ਕੋ ਵਾਰ ਨ ਪਾਰਾ। ੬੧।","roman":"Aasaa karat gayaa sansaaraa | ih aasaa ko vaar na paaraa | 61 |","meaning_en":"Hoping, he left the world; this hope has no bank on this side or that.","page":2099,"meaning_status":"draft","meaning_pa":"(ਧਨ ਦੀ) ਇੱਛਾ ਕਰਦਾ ਹੋਇਆ ਸਾਰਾ ਸੰਸਾਰ ਚਲਾ ਗਿਆ ਹੈ, ਪਰ ਇਸ 'ਇੱਛਾ' ਦਾ ਕੋਈ ਉਰਾਰ ਪਾਰ ਨਹੀਂ ਹੈ ॥੬੧॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[62],"number_text":"੬੨।","page":2099,"lines":[{"gurmukhi":"ਏਕ ਨਿਰਾਸ ਵਹੈ ਕਰਤਾਰਾ। ਜਿਨ ਕੀਨਾ ਇਹ ਸਕਲ ਪਸਾਰਾ।","roman":"Ek niraas vahai kartaaraa | jin keenaa ih sakal pasaaraa |","meaning_en":"Only that One, the Creator, is without hope, who made all this expanse.","page":2099,"meaning_status":"draft","meaning_pa":"ਇੱਛਾ ਤੋਂ ਮੁਕਤ ਕੇਵਲ ਇਕ ਕਰਤਾਰ ਹੀ ਹੈ, ਜਿਸ ਨੇ ਇਸ ਸਾਰੀ ਸ੍ਰਿਸ਼ਟੀ ਦੀ ਸਿਰਜਨਾ ਕੀਤੀ ਹੋਈ ਹੈ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਆਸਾ ਰਹਿਤ ਔਰ ਕੋਊ ਨਾਹੀ। ਜਾਨੁ ਲੇਹੁ ਦਿਜਬਰ ਮਨ ਮਾਹੀ। ੬੨।","roman":"Aasaa rahit aur ko'oo naahee | jaanu lehu dijbar man maahee | 62 |","meaning_en":"There is no one else free of hope; know this in your mind, excellent brahmin.","page":2099,"meaning_status":"draft","meaning_pa":"ਇੱਛਾ ਤੋਂ ਬਿਨਾ ਹੋਰ ਕੋਈ ਵੀ ਨਹੀਂ ਹੈ। ਹੇ ਸ੍ਰੇਸ਼ਠ ਬ੍ਰਾਹਮਣ! (ਤੁਸੀਂ) ਮਨ ਵਿਚ ਸਮਝ ਲਵੋ ॥੬੨॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[63],"number_text":"੬੩।","page":2099,"lines":[{"gurmukhi":"ਲੋਭ ਲਗੇ ਧਨ ਕੇ ਏ ਦਿਜਬਰ। ਮਾਂਗਤ ਫਿਰਤ ਸਭਨ ਕੇ ਘਰ ਘਰ।","roman":"Lobh lage dhan ke e dijbar | maangat phirat sabhan ke ghar ghar |","meaning_en":"These excellent brahmins, attached to greed for wealth, go begging at everyone's house.","page":2099,"meaning_status":"draft","meaning_pa":"ਇਹ ਸ੍ਰੇਸ਼ਠ ਬ੍ਰਾਹਮਣ ਧਨ ਦੇ ਲੋਭ ਵਿਚ ਫਸੇ ਹੋਏ ਹਨ ਅਤੇ ਸਭ ਦੇ ਘਰ ਘਰ ਮੰਗਦੇ ਫਿਰਦੇ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਯਾ ਜਗ ਮਹਿ ਕਰ ਡਿੰਭ ਦਿਖਾਵਤ। ਤੇ ਠਗਿ ਠਗਿ ਸਭ ਕਹ ਧਨ ਖਾਵਤ। ੬੩।","roman":"Yaa jag mahi kar dinbh dikhaavat | te thagi thagi sabh kah dhan khaavat | 63 |","meaning_en":"Making a show of hypocrisy in this world, they cheat and cheat and eat everyone's wealth.","page":2099,"meaning_status":"draft","meaning_pa":"ਇਸ ਜਗਤ ਵਿਚ (ਇਹ) ਪਾਖੰਡ ਕਰਕੇ ਵਿਖਾਉਾਂਦੇ ਹਨ ਅਤੇ ਸਭ ਦਾ ਧਨ ਠਗ ਠਗ ਕੇ ਖਾਦੇ ਹਨ ॥੬੩॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2099,"meaning_status":"draft","meaning_pa":"ਦੋਹਰਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[64],"number_text":"੬੪।","page":2099,"lines":[{"gurmukhi":"ਆਸਾ ਕੀ ਆਸਾ ਲਗੇ ਸਭ ਹੀ ਗਯਾ ਜਹਾਨ।","roman":"Aasaa kee aasaa lage sabh hee gayaa jahaan |","meaning_en":"In hope upon hope, the whole world has gone;","page":2099,"meaning_status":"draft","meaning_pa":"ਇੱਛਾ ('ਆਸਾ') ਦੀ ਇੱਛਾ ਵਿਚ ਲਗਿਆ ਹੋਇਆ ਇਹ ਸਾਰਾ ਸੰਸਾਰ ਚਲਾ ਗਿਆ ਹੈ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਆਸਾ ਜਗ ਜੀਵਤ ਬਚੀ ਲੀਜੈ ਸਮਝਿ ਸੁਜਾਨ। ੬੪।","roman":"Aasaa jag jeevat bachee leejai samjhi sujaan | 64 |","meaning_en":"hope alone remains while the world lives; understand this, wise one.","page":2099,"meaning_status":"draft","meaning_pa":"ਸਾਰੇ ਸਮਝਦਾਰ ਇਹ ਸਮਝ ਲੈਣ ਕਿ ਕੇਵਲ 'ਆਸਾ' ਹੀ ਸੰਸਾਰ ਵਿਚ ਜੀਉਾਂਦੀ ਬਚੀ ਹੈ ॥੬੪॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2101,"meaning_status":"draft","meaning_pa":"ਚੌਪਈ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[65],"number_text":"੬੫।","page":2101,"lines":[{"gurmukhi":"ਆਸਾ ਕਰਤ ਸਗਲ ਜਗ ਜਯਾ। ਆਸਹਿ ਉਪਜ੍ਯਾ ਆਸਹਿ ਭਯਾ।","roman":"Aasaa karat sagal jag jayaa | aashi upjyaa aashi bhayaa |","meaning_en":"Hoping, the whole world is born; in hope it arose, in hope it came to be.","page":2101,"meaning_status":"draft","meaning_pa":"ਆਸਾ ਕਰਦਿਆਂ ਹੀ ਸਾਰਾ ਸੰਸਾਰ ਜਨਮਿਆ ਹੈ। ਆਸਾ ਵਿਚ ਉਪਜਦਾ ਹੋਇਆ ਆਸਾ ਰੂਪ ਹੀ ਹੋ ਜਾਦਾ ਹੈ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਆਸਾ ਕਰਤ ਤਰੁਨ ਬ੍ਰਿਧ ਹੂਆ। ਆਸਾ ਕਰਤ ਲੋਗ ਸਭ ਮੂਆ। ੬੫।","roman":"Aasaa karat tarun bridh hooaa | aasaa karat log sabh mooaa | 65 |","meaning_en":"Hoping, the young became old; hoping, all people died.","page":2101,"meaning_status":"draft","meaning_pa":"ਆਸਾ ਕਰਦਿਆਂ ਜਵਾਨ ਬੁੱਢਾ ਹੋ ਜਾਦਾ ਹੈ। ਆਸਾ ਕਰਦਿਆਂ ਸਾਰੇ ਲੋਕ ਮਰ ਗਏ ਹਨ ॥੬੫॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[66],"number_text":"੬੬।","page":2101,"lines":[{"gurmukhi":"ਆਸਾ ਕਰਤ ਲੋਗ ਸਭ ਭਏ। ਬਾਲਕ ਹੁਤੋ ਬ੍ਰਿਧ ਹ੍ਵੈ ਗਏ।","roman":"Aasaa karat log sabh bhae | baalak huto bridh hvai gae |","meaning_en":"Hoping, all people came into being; the child became old;","page":2101,"meaning_status":"draft","meaning_pa":"ਆਸਾ ਕਰਦਿਆਂ ਸਭ ਲੋਕ ਬਾਲਕ ਤੋਂ ਬਿਰਧ ਹੋ ਗਏ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜਿਤਿ ਕਿਤ ਧਨ ਆਸਾ ਕਰਿ ਡੋਲਹਿ। ਦੇਸ ਬਿਦੇਸ ਧਨਾਸ ਕਲੋਲਹਿ। ੬੬।","roman":"Jiti kit dhan aasaa kari dolhi | des bides dhanaas kalolhi | 66 |","meaning_en":"wherever, in hope of wealth, they wander, and frolic in country and foreign lands.","page":2101,"meaning_status":"draft","note":"ਧਨਾਸ: read as 'hope of wealth'; uncertain.","meaning_pa":"ਆਸ ਕਰ ਕੇ ਜਿਥੇ ਕਿਥੇ ਡੋਲਦੇ ਫਿਰ ਰਹੇ ਹਨ ਅਤੇ ਧਨ ਦੀ ਆਸਾ ਵਿਚ ਦੇਸਾ-ਵਿਦੇਸ਼ਾ ਵਿਚ ਘੁੰਮਦੇ ਫਿਰਦੇ ਹਨ ॥੬੬॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[67],"number_text":"੬੭।","page":2101,"lines":[{"gurmukhi":"ਪਾਹਨ ਕਹੁ ਧਨਾਸ ਸਿਰ ਨ੍ਯਾਵੈ। ਚੇਤ ਅਚੇਤਨ ਕੌ ਠਹਰਾਵੈ।","roman":"Paahan kahu dhanaas sir nyaavai | chet achetan kau thahraavai |","meaning_en":"In hope of wealth, he bows his head to a stone and sets the unconscious up as the conscious.","page":2101,"meaning_status":"draft","note":"ਚੇਤ ਅਚੇਤਨ ਕੌ ਠਹਰਾਵੈ: printed so; sense uncertain.","meaning_pa":"ਧਨ ਦੀ ਆਸਾ ਵਿਚ ਹੀ ਪੱਥਰ ਨੂੰ ਸਿਰ ਨਿਵਾਉਾਂਦੇ ਹਨ ਅਤੇ ਅਚੇਤ ਨੂੰ ਸਚੇਤ ਕਹਿੰਦੇ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਕਰਤ ਪ੍ਰਪੰਚ ਪੇਟ ਕੇ ਕਾਜਾ। ਊਚ ਨੀਚ ਰਾਨਾ ਅਰੁ ਰਾਜਾ। ੬੭।","roman":"Karat prapanch pet ke kaajaa | ooch neech raanaa aru raajaa | 67 |","meaning_en":"For the belly's sake they make deceit, high and low, rana and king.","page":2101,"meaning_status":"draft","meaning_pa":"ਉੱਚੇ ਨੀਵੇਾਂ, ਰਾਣਾ ਅਤੇ ਰਾਜਾ (ਸਭ) ਪੇਟ ਦੀ ਖਾਤਰ ਪ੍ਰਪੰਚ ਕਰਦੇ ਹਨ ॥੬੭॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[68],"number_text":"੬੮।","page":2101,"lines":[{"gurmukhi":"ਕਾਹੂ ਕੋ ਸਿਛਾ ਸੁ ਦ੍ਰਿੜਾਵੈ। ਕਾਹੂੰ ਕੌ ਲੈ ਮੂੰਡ ਮੁੰਡਾਵੈ।","roman":"Kaahoo ko sichhaa su driraavai | kaahoon kau lai moond mundaavai |","meaning_en":"Some he makes firm in teaching; some he takes and has their heads shaved;","page":2101,"meaning_status":"draft","meaning_pa":"ਕਿਸੇ ਨੂੰ ਸਿਖਿਆ ਦ੍ਰਿੜ੍ਰਹ ਕਰਾਉਾਂਦੇ ਹਨ ਅਤੇ ਕਿਸੇ ਦਾ ਸਿਰ ਮੁੰਨਵਾ ਦਿੰਦੇ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਕਾਹੂੰ ਪਠੈ ਤੀਰਥਨ ਦੇਹੀ। ਗ੍ਰਿਹ ਕੋ ਦਰਬੁ ਮਾਂਗ ਸਭ ਲੇਹੀ। ੬੮।","roman":"Kaahoon pathai teerthan dehee | grih ko darbu maang sabh lehee | 68 |","meaning_en":"some he sends to pilgrimages, and begging takes all the wealth of their house.","page":2101,"meaning_status":"draft","meaning_pa":"ਕਈਆਂ ਨੂੰ ਤੀਰਥਾ (ਦੀ ਯਾਤ੍ਰਾ) ਉਤੇ ਭੇਜ ਦਿੰਦੇ ਹਨ ਅਤੇ ਘਰ ਦਾ ਸਾਰਾ ਧਨ (ਆਪ) ਮੰਗ ਲੈਂਦੇ ਹਨ ॥੬੮॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[69],"number_text":"੬੯।","page":2101,"lines":[{"gurmukhi":"ਜਿਹ ਨਰ ਕੋ ਧਨਵਾਨ ਤਕਾਵੈ। ਜੋਨਿ ਸਿਲਾ ਮਹਿ ਤਾਹਿ ਫਸਾਵੈ।","roman":"Jih nar ko dhanvaan takaavai | joni silaa mahi taahi phasaavai |","meaning_en":"Whichever wealthy man he eyes, he entangles him in the birth of a stone;","page":2101,"meaning_status":"draft","note":"ਜੋਨਿ ਸਿਲਾ: read as 'the birth/womb of stone'; uncertain.","meaning_pa":"ਜਿਸ ਵਿਅਕਤੀ ਨੂੰ (ਇਹ) ਧਨਵਾਨ ਵੇਖ ਲੈਂਦੇ ਹਨ, ਉਸ ਨੂੰ ਜੂਨਾ ਦੇ ਚੱਕਰ (ਸਿਲਸਿਲੇ) ਵਿਚ ਫਸਾ ਦਿੰਦੇ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਬਹੁਰਿ ਡੰਡ ਤਿਹ ਮੂੰਡਿ ਚੁਕਾਹੀ। ਕਾਢਿ ਦੇਤ ਤਾ ਕੇ ਪੁਨਿ ਮਾਹੀ। ੬੯।","roman":"Bahuri dand tih moondi chukaahee | kaadhi det taa ke puni maahee | 69 |","meaning_en":"then the fine on his head is cleared, and taking him out, he again puts him in that same place.","page":2101,"meaning_status":"draft","note":"Lines .0 to .1 are obscure; translated as printed; uncertain.","meaning_pa":"ਫਿਰ ਉਸ ਦੇ ਸਿਰ ਉਤੇ ਬਹੁਤ ਦੰਡ ਕਢ ਦਿੰਦੇ ਹਨ ਅਤੇ ਫਿਰ ਉਸ ਨੂੰ ਚੁਕਤਾ ਕਰਾ ਲੈਂਦੇ ਹਨ (ਭਾਵ ਵਸੂਲ ਕਰਦੇ ਹਨ) ॥੬੯॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[70],"number_text":"੭੦।","page":2101,"lines":[{"gurmukhi":"ਇਨ ਲੋਗਨ ਧਨ ਹੀ ਕੀ ਆਸਾ। ਸ੍ਰੀ ਹਰਿ ਜੀ ਕੀ ਨਾਹਿ ਪ੍ਯਾਸਾ।","roman":"In logan dhan hee kee aasaa | sree hari jee kee naahi pyaasaa |","meaning_en":"These people have hope of wealth alone; they have no thirst for Sri Hari.","page":2101,"meaning_status":"draft","meaning_pa":"ਇਨ੍ਰਹਾ ਲੋਕਾ ਨੂੰ ਧਨ ਦੀ ਹੀ ਆਸ ਹੈ। ਸ੍ਰੀ ਭਗਵਾਨ ਲਈ ਕੋਈ ਪਿਆਸ ਨਹੀਂ ਹੈ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਡਿੰਭਿ ਜਗਤ ਕਹ ਕਰਿ ਪਰਚਾਵੈ। ਲਛਿਮੀ ਹਰ ਜ੍ਯੋ ਤ੍ਯੋ ਲੈ ਆਵੈ। ੭੦।","roman":"Dinbhi jagat kah kari parchaavai | lachhimee har jyo tyo lai aavai | 70 |","meaning_en":"With hypocrisy they beguile the world, and by whatever means they bring Lakshmi (wealth) away.","page":2101,"meaning_status":"draft","meaning_pa":"(ਉਹ) ਪਾਖੰਡ ਕਰ ਕੇ ਜਗਤ ਨੂੰ ਪਰਚਾਉਾਂਦੇ ਹਨ ਅਤੇ ਜਿਵੇਾਂ ਕਿਵੇਾਂ ਧਨ ਹਰ ਕੇ ਲੈ ਆਉਾਂਦੇ ਹਨ ॥੭੦॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"speaker","name":"ਦਿਜ ਬਾਚ","gurmukhi":"ਦਿਜ ਬਾਚ","roman":"Dij baach","meaning_en":"The brahmin said:","page":2101,"meaning_status":"draft","meaning_pa":"ਬ੍ਰਾਹਮਣ ਨੇ ਕਿਹਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[71],"number_text":"੭੧।","page":2101,"lines":[{"gurmukhi":"ਸੁਨੁ ਪੁਤ੍ਰੀ ਤੈ ਬਾਤ ਨ ਜਾਨੈ। ਸਿਵ ਕਹ ਕਰਿ ਪਾਹਨ ਪਹਿਚਾਨੈ।","roman":"Sunu putree tai baat na jaanai | siv kah kari paahan pahichaanai |","meaning_en":"'Listen, daughter, you do not know the matter; you take Shiva to be a stone.","page":2101,"meaning_status":"draft","meaning_pa":"ਹੇ ਪੁੱਤਰੀ! ਸੁਣ, ਤੂੰ (ਅਸਲ) ਗੱਲ ਨਹੀਂ ਜਾਣਦੀ ਹੈਂ ਅਤੇ ਸ਼ਿਵ ਨੂੰ ਪੱਥਰ ਸਮਝਦੀ ਹੈਂ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਬਿਪ੍ਰਨ ਕੌ ਸਭ ਹੀ ਸਿਰ ਨ੍ਯਾਵੈ। ਚਰਨੋਦਕ ਲੈ ਮਾਥ ਚੜਾਵੈ। ੭੧।","roman":"Bipran kau sabh hee sir nyaavai | charnodak lai maath charaavai | 71 |","meaning_en":"All bow their heads to brahmins, and take the water of their feet and put it on their foreheads.","page":2101,"meaning_status":"draft","meaning_pa":"ਬ੍ਰਾਹਮਣਾ ਨੂੰ ਤਾ ਸਾਰੇ ਸਿਰ ਨਿਵਾਉਾਂਦੇ ਹਨ ਅਤੇ ਉਨ੍ਰਹਾ ਤੋਂ ਚਰਨੋਦਕ (ਚਰਨਾਮ੍ਰਿਤ) ਲੈ ਕੇ ਮੱਥੇ ਉਤੇ ਚੜ੍ਰਹਾਉਾਂਦੇ ਹਨ ॥੭੧॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[72],"number_text":"੭੨।","page":2101,"lines":[{"gurmukhi":"ਪੂਜਾ ਕਰਤ ਸਗਲ ਜਗ ਇਨ ਕੀ। ਨਿੰਦ੍ਯਾ ਕਰਤ ਮੂੜ ਤੈ ਜਿਨ ਕੀ।","roman":"Poojaa karat sagal jag in kee | nindyaa karat moor tai jin kee |","meaning_en":"All the world worships them; you, fool, slander them.","page":2101,"meaning_status":"draft","meaning_pa":"ਇਨ੍ਰਹਾ ਦੀ ਸਾਰਾ ਜਗਤ ਪੂਜਾ ਕਰਦਾ ਹੈ ਜਿਨ੍ਰਹਾ ਦੀ ਹੇ ਮੂਰਖ! ਤੂੰ ਨਿੰਦਿਆ ਕਰਦੀ ਹੈਂ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਏ ਹੈ ਪਰਮ ਪੁਰਾਤਨ ਦਿਜਬਰ। ਸਦਾ ਸਰਾਹਤ ਜਿਨ ਕਹ ਨ੍ਰਿਪ ਬਰ। ੭੨।","roman":"E hai param puraatan dijbar | sadaa saraahat jin kah nrip bar | 72 |","meaning_en":"These are supremely ancient, excellent brahmins, whom the best kings always praise.'","page":2101,"meaning_status":"draft","meaning_pa":"ਇਹ ਬ੍ਰਾਹਮਣ ਪਰਮ ਪੁਰਾਤਨ ਹਨ ਜਿਨ੍ਰਹਾ ਨੂੰ ਸਦਾ ਮਹਾਨ ਰਾਜੇ ਸਲਾਹੁੰਦੇ ਰਹਿੰਦੇ ਹਨ ॥੭੨॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"speaker","name":"ਕੁਅਰਿ ਬਾਚ","gurmukhi":"ਕੁਅਰਿ ਬਾਚ","roman":"Kuari baach","meaning_en":"The princess said:","page":2101,"meaning_status":"draft","meaning_pa":"ਰਾਜ ਕੁਮਾਰੀ ਨੇ ਕਿਹਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[73],"number_text":"੭੩।","page":2101,"lines":[{"gurmukhi":"ਸੁਨ ਮੂਰਖ ਦਿਜ ਤੈ ਨਹਿ ਜਾਨੀ। ਪਰਮ ਜੋਤਿ ਪਾਹਨ ਪਹਿਚਾਨੀ।","roman":"Sun moorakh dij tai nahi jaanee | param joti paahan pahichaanee |","meaning_en":"'Listen, foolish brahmin, you have not understood; you recognise the supreme light in a stone.","page":2101,"meaning_status":"draft","meaning_pa":"ਹੇ ਮੂਰਖ ਬ੍ਰਾਹਮਣ! ਸੁਣ, ਤੂੰ ਨਹੀਂ ਜਾਣਦਾ ਅਤੇ ਪੱਥਰ ਨੂੰ ਪਰਮ ਜੋਤਿ ਮੰਨ ਰਿਹਾ ਹੈਂ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਇਨ ਮਹਿ ਪਰਮ ਪੁਰਖ ਤੈ ਜਾਨਾ। ਤਜਿ ਸ੍ਯਾਨਪ ਹ੍ਵੈ ਗਯੋ ਅਯਾਨਾ। ੭੩।","roman":"In mahi param purakh tai jaanaa | taji syaanap hvai gayo ayaanaa | 73 |","meaning_en":"You have known the supreme Person in these; leaving cleverness, you have become ignorant.","page":2101,"meaning_status":"draft","meaning_pa":"ਇਨ੍ਰਹਾ (ਪੱਥਰਾ) ਵਿਚ ਤੂੰ ਪਰਮ ਪੁਰਖ ਨੂੰ ਸਮਝ ਰਖਿਆ ਹੈ। ਸਿਆਣਪ ਛਡ ਕੇ ਇਆਣਾ ਹੋ ਗਿਆ ਹੈਂ ॥੭੩॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":2101,"meaning_status":"draft","meaning_pa":"ਅੜਿਲ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[74],"number_text":"੭੪।","page":2101,"lines":[{"gurmukhi":"ਲੈਨੌ ਹੋਇ ਸੁ ਲੈ ਦਿਜ ਮੁਹਿ ਨ ਝੁਠਾਇਯੈ।","roman":"Lainau hoi su lai dij muhi na jhuthaaiyai |","meaning_en":"Take whatever you want to take, brahmin; do not make me out a liar;","page":2101,"meaning_status":"draft","meaning_pa":"ਹੇ ਬ੍ਰਾਹਮਣ! ਜੋ (ਤੂੰ) ਲੈਣਾ ਹੈ, ਲੈ ਲੈ, ਪਰ ਮੈਨੂੰ ਝੂਠ ਮੂਠ ਨਾ ਦਸ","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਪਾਹਨ ਮੈ ਪਰਮੇਸ੍ਵਰ ਨ ਭਾਖਿ ਸੁਨਾਇਯੈ।","roman":"Paahan mai parmesvar na bhaakhi sunaaiyai |","meaning_en":"do not go about saying that the Lord is in a stone.","page":2101,"meaning_status":"draft","meaning_pa":"ਅਤੇ ਮੈਨੂੰ ਪੱਥਰ ਵਿਚ ਪਰਮਾਤਮਾ ਕਹਿ ਕੇ ਨਾ ਸੁਣਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਇਨ ਲੋਗਨ ਪਾਹਨ ਮਹਿ ਸਿਵ ਠਹਰਾਇ ਕੈ।","roman":"In logan paahan mahi siv thahraai kai |","meaning_en":"These people, setting Shiva in stones,","page":2101,"meaning_status":"draft","meaning_pa":"ਇਨ੍ਰਹਾ ਲੋਕਾ ਨੂੰ ਪੱਥਰਾ ਵਿਚ ਸ਼ਿਵ ਦਸ ਕੇ","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਹੋ ਮੂੜਨ ਲੀਜਹੁ ਲੂਟ ਹਰਖ ਉਪਜਾਇ ਕੈ। ੭੪।","roman":"Ho mooran leejhu loot harakh upjaai kai | 74 |","meaning_en":"loot the fools, producing delight in them.","page":2101,"meaning_status":"draft","meaning_pa":"ਮੂਰਖਾ ਨੂੰ ਪ੍ਰਸੰਨਤਾ ਪੂਰਵਕ ਲੁਟ ਲੈ ॥੭੪॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[75],"number_text":"੭੫।","page":2103,"lines":[{"gurmukhi":"ਕਾਹੂ ਕਹ ਪਾਹਨ ਮਹਿ ਬ੍ਰਹਮ ਬਤਾਤ ਹੈ।","roman":"Kaahoo kah paahan mahi braham bataat hai |","meaning_en":"To some he points out Brahman in a stone;","page":2103,"meaning_status":"draft","meaning_pa":"ਕਿਸੇ ਨੂੰ (ਤੂੰ) ਪੱਥਰ ਵਿਚ ਪਰਮਾਤਮਾ ਦਸਦਾ ਹੈਂ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜਲ ਡੂਬਨ ਹਿਤ ਕਿਸਹੂੰ ਤੀਰਥ ਪਠਾਤ ਹੈ।","roman":"Jal dooban hit kishoon teerath pathaat hai |","meaning_en":"to some he sends them to a place of pilgrimage to dive in the water;","page":2103,"meaning_status":"draft","meaning_pa":"ਕਿਸੇ ਨੂੰ ਜਲ ਵਿਚ ਡੁਬਕੀ ਮਾਰਨ ਲਈ ਤੀਰਥਾ ਉਤੇ ਭੇਜਦਾ ਹੈਂ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜ੍ਯੋ ਤ੍ਯੋ ਧਨ ਹਰ ਲੇਤ ਜਤਨ ਅਨਗਨਿਤ ਕਰ।","roman":"Jyo tyo dhan har let jatan anagnit kar |","meaning_en":"by whatever means he takes their wealth, with countless efforts;","page":2103,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਟਕਾ ਗਾਠਿ ਮਹਿ ਲਏ ਨ ਦੇਹੀ ਜਾਨ ਘਰ। ੭੫।","roman":"Ho takaa gaathi mahi lae na dehee jaan ghar | 75 |","meaning_en":"having taken the taka into his knot, he does not let him go home.","page":2103,"meaning_status":"draft","meaning_pa":"ਜਿਵੇਾਂ ਕਿਵੇਾਂ ਅਣਗਿਣਤ ਯਤਨ ਕਰ ਕੇ ਧਨ ਹਰ ਲੈਂਦਾ ਹੈ। (ਜਿਸ ਦੀ) ਗੰਢ ਵਿਚ ਪੈਸਾ (ਜਾਣ ਲੈਂਦਾ ਹੈ) ਉਸ ਤੋਂ ਲਏ ਬਿਨਾ ਘਰ ਜਾਣ ਨਹੀਂ ਦਿੰਦਾ ॥੭੫॥","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"}]},{"type":"verse","number":[76],"number_text":"੭੬।","page":2103,"lines":[{"gurmukhi":"ਧਨੀ ਪੁਰਖ ਕਹ ਲਖਿ ਦਿਜ ਦੋਖ ਲਗਾਵਹੀ।","roman":"Dhanee purakh kah lakhi dij dokh lagaavhee |","meaning_en":"Seeing a rich man, the brahmin lays a fault on him,","page":2103,"meaning_status":"draft","meaning_pa":"ਧਨਵਾਨ ਵਿਅਕਤੀ ਨੂੰ ਵੇਖ ਕੇ ਬ੍ਰਾਹਮਣ (ਕੋਈ ਨਾ ਕੋਈ) ਦੋਸ਼, (ਪਾਪ) ਲਗਾ ਦਿੰਦੇ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਹੋਮ ਜਗ੍ਯ ਤਾ ਤੇ ਬਹੁ ਭਾਤ ਕਰਾਵਹੀ।","roman":"Hom jagy taa te bahu bhaat karaavhee |","meaning_en":"and through him has homa and sacrifices performed in many ways;","page":2103,"meaning_status":"draft","meaning_pa":"ਉਸ ਤੋਂ ਬਹੁਤ ਤਰ੍ਰਹਾ ਦੇ ਹੋਮ ਅਤੇ ਯੱਗ ਕਰਵਾਉਾਂਦੇ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਧਨਿਯਹਿ ਕਰਿ ਨਿਰਧਨੀ ਜਾਤ ਧਨ ਖਾਇ ਕੈ।","roman":"Dhaniyhi kari niradhnee jaat dhan khaai kai |","meaning_en":"making the rich man poor, he eats his wealth and goes,","page":2103,"meaning_status":"draft","meaning_pa":"ਧਨਵਾਨ ਦਾ ਧਨ ਖਾ ਕੇ (ਉਸ ਨੂੰ) ਨਿਰਧਨ ਬਣਾ ਦਿੰਦੇ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਹੋ ਬਹੁਰਿ ਨ ਤਾ ਕੌ ਬਦਨ ਦਿਖਾਵਤ ਆਇ ਕੈ। ੭੬।","roman":"Ho bahuri na taa kau badan dikhaavat aai kai | 76 |","meaning_en":"and does not come again to show him his face.","page":2103,"meaning_status":"draft","meaning_pa":"ਫਿਰ ਉਸ ਨੂੰ ਆ ਕੇ ਮੂੰਹ ਤਕ ਨਹੀਂ ਵਿਖਾਉਾਂਦੇ ॥੭੬॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2103,"meaning_status":"draft","meaning_pa":"ਚੌਪਈ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[77],"number_text":"੭੭।","page":2103,"lines":[{"gurmukhi":"ਕਾਹੂ ਲੌ ਤੀਰਥਨ ਸਿਧਾਵੈ। ਕਾਹੂ ਅਫਲ ਪ੍ਰਯੋਗ ਬਤਾਵੈ।","roman":"Kaahoo lau teerthan sidhaavai | kaahoo aphal prayog bataavai |","meaning_en":"Some he sends to pilgrimages; to some he points out fruitless rites.","page":2103,"meaning_status":"draft","meaning_pa":"ਕਈਆਂ ਨੂੰ ਤੀਰਥਾ ਉਤੇ ਭੇਜ ਦਿੰਦੇ ਹਨ ਅਤੇ ਕਈਆਂ ਦੀ ਸਾਧਨਾ (ਉਪਾ, 'ਪ੍ਰਯੋਗ') ਨੂੰ ਅਫਲ ਦਸਦੇ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਕਾਕਨ ਜ੍ਯੋ ਮੰਡਰਾਤ ਧਨੂਪਰ। ਜ੍ਯੋ ਕਿਲਕਾ ਮਛਰੀਯੈ ਦੂਪਰ। ੭੭।","roman":"Kaakan jyo mandraat dhanoopar | jyo kilkaa machhreeyai doopar | 77 |","meaning_en":"Like crows they hover over wealth, like a swarm of flies and mosquitoes at noon.","page":2103,"meaning_status":"draft","note":"ਕਿਲਕਾ: uncertain; read as 'swarm'; ਦੂਪਰ read as 'noon'.","meaning_pa":"ਕਾਵਾ ਵਾਗ ਧਨ ਉਤੇ ਮੰਡਰਾਉਾਂਦੇ ਹਨ। (ਜਾ) ਜਿਵੇਾਂ ਦੁਧੀਰਾ ਮਛਲੀਆ ਉਤੇ (ਗੇੜੇ ਕਢਦਾ ਹੈ) ॥੭੭॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[78],"number_text":"੭੮।","page":2103,"lines":[{"gurmukhi":"ਜ੍ਯੋ ਦ੍ਵੈ ਸ੍ਵਾਨ ਏਕ ਹਡਿਯਾ ਪਰ। ਭੂਸਤ ਮਨੋ ਬਾਦਿ ਬਿਦ੍ਯਾਧਰ।","roman":"Jyo dvai svaan ek hadiyaa par | bhoosat mano baadi bidyaadhar |","meaning_en":"As two dogs growl over a single bone, so, as if disputing, the learned ones argue;","page":2103,"meaning_status":"draft","note":"ਬਿਦ੍ਯਾਧਰ: 'learned men'; ਬਾਦਿ: 'dispute'; uncertain.","meaning_pa":"ਜਿਵੇਾਂ ਦੋ ਕੁੱਤੇ ਇਕ ਹੱਡੀ ਉਤੇ (ਲੜ ਮਰਦੇ ਹਨ) ਉਸੇ ਤਰ੍ਰਹਾ ਮਾਨੋ ਦੋ ਵਿਦਵਾਨ ਕਿਸੇ ਵਾਦ-ਵਿਵਾਦ ਵੇਲੇ ਭੌਂਕਦੇ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਬਾਹਰ ਕਰਤ ਬੇਦ ਕੀ ਚਰਚਾ। ਤਨ ਅਰੁ ਮਨ ਧਨ ਹੀ ਕੀ ਅਰਚਾ। ੭੮।","roman":"Baahar karat bed kee charchaa | tan aru man dhan hee kee archaa | 78 |","meaning_en":"outside they carry on talk of the Veda, while body and mind are given to the worship of wealth alone.","page":2103,"meaning_status":"draft","meaning_pa":"ਬਾਹਰੋਂ ਤਾ ਵੇਦ ਦੀ ਗੱਲ ਕਰਦੇ ਹਨ, ਪਰ ਮਨ ਅਤੇ ਤਨ ਧਨ ਦੀ ਪੂਜਾ ਉਤੇ ਲਗਿਆ ਰਹਿੰਦਾ ਹੈ ॥੭੮॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2103,"meaning_status":"draft","meaning_pa":"ਦੋਹਰਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[79],"number_text":"੭੯।","page":2103,"lines":[{"gurmukhi":"ਧਨ ਕੀ ਆਸਾ ਮਨ ਰਹੇ ਬਾਹਰ ਪੂਜਤ ਦੇਵ।","roman":"Dhan kee aasaa man rahe baahar poojat dev |","meaning_en":"With hope of wealth in the mind, outside they worship gods;","page":2103,"meaning_status":"draft","meaning_pa":"ਮਨ ਵਿਚ ਧਨ ਦੀ ਆਸਾ ਰਹਿੰਦੀ ਹੈ ਅਤੇ ਬਾਹਰੋਂ ਦੇਵਤਾ ਦੀ ਪੂਜਾ ਕਰਦਾ ਹੈ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਨ ਹਰਿ ਮਿਲਾ ਨ ਧਨ ਭਯੋ ਬ੍ਰਿਥਾ ਭਈ ਸਭ ਸੇਵ। ੭੯।","roman":"Na hari milaa na dhan bhayo brithaa bhaee sabh sev | 79 |","meaning_en":"neither Hari was met nor wealth gained; all the service was in vain.","page":2103,"meaning_status":"draft","meaning_pa":"ਨਾ ਪਰਮਾਤਮਾ ਮਿਲਦਾ ਹੈ ਅਤੇ ਨਾ ਹੀ ਧਨਵਾਨ ਹੁੰਦਾ ਹੈ। ਸਾਰੀ ਸੇਵਾ ਵਿਅਰਥ ਹੋ ਜਾਦੀ ਹੈ ॥੭੯॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":2103,"meaning_status":"draft","meaning_pa":"ਅੜਿਲ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[80],"number_text":"੮੦।","page":2103,"lines":[{"gurmukhi":"ਏ ਬਿਦ੍ਯਾ ਬਲ ਕਰਿਹ ਜੋਗ ਕੀ ਬਾਤ ਨ ਜਾਨੈ।","roman":"E bidyaa bal karih jog kee baat na jaanai |","meaning_en":"These, by the power of their learning, do not know the matter of yoga;","page":2103,"meaning_status":"draft"},{"gurmukhi":"ਏ ਸੁਚੇਤ ਕਰਿ ਰਹਹਿ ਹਮਨਿ ਆਚੇਤ ਪ੍ਰਮਾਨੈ।","roman":"E suchet kari rahhi hamni aachet pramaanai |","meaning_en":"they keep themselves wise and take us to be unaware.","page":2103,"meaning_status":"draft","meaning_pa":"ਇਹ ਵਿਦਿਆ ਦੇ ਬਲ ਤੇ ਗੱਲ ਕਰਦੇ ਹਨ, ਪਰ ਯੋਗ ਦੀ ਗੱਲ ਨੂੰ ਨਹੀਂ ਜਾਣਦੇ। ਇਹ (ਆਪਣੇ ਆਪ ਨੂੰ) ਸੂਝਵਾਨ ਸਮਝਦੇ ਹਨ ਅਤੇ ਸਾਨੂੰ ਮੂਰਖ ਦਸਦੇ ਹਨ।","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"},{"gurmukhi":"ਕਹਾ ਭਯੌ ਜੌ ਭਾਂਗ ਭੂਲਿ ਭੌਦੂ ਨਹਿ ਖਾਈ।","roman":"Kahaa bhayau jau bhaang bhooli bhaudoo nahi khaaee |","meaning_en":"What if one has not eaten bhang or, forgetfully, [unclear];","page":2103,"meaning_status":"draft","note":"ਭੌਦੂ: cannot be read with confidence; left as [unclear]."},{"gurmukhi":"ਹੋ ਨਿਜੁ ਤਨ ਤੇ ਬਿਸੰਭਾਰ ਰਹਤ ਸਭ ਲਖਤ ਲੁਕਾਈ। ੮੦।","roman":"Ho niju tan te bisanbhaar rahat sabh lakhat lukaaee | 80 |","meaning_en":"from his own body he stays unmindful, while all the people look on.","page":2103,"meaning_status":"draft","note":"Line is obscure; read as printed; uncertain.","meaning_pa":"ਕੀ ਹੋਇਆ ਜੋ ਮੂਰਖ ਨੇ ਭੁਲ ਕੇ ਵੀ ਭੰਗ ਨਹੀਂ ਖਾਈ। ਪਰ ਸਾਰੇ ਜਾਣਦੇ ਹਨ ਕਿ ਉਹ ਆਪਣੇ ਸ਼ਰੀਰ ਤੋਂ ਵੀ ਬੇਸੁਰਤ ਰਹਿੰਦੇ ਹਨ ॥੮੦॥","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"}]},{"type":"verse","number":[81],"number_text":"੮੧।","page":2103,"lines":[{"gurmukhi":"ਭਾਂਗ ਖਾਇ ਭਟ ਭਿੜਹਿ ਗਜਨ ਕੇ ਦਾਂਤ ਉਪਾਰਹਿ।","roman":"Bhaang khaai bhat bhirhi gajan ke daant upaarhi |","meaning_en":"Eating bhang, warriors fight and pull out the tusks of elephants;","page":2103,"meaning_status":"draft"},{"gurmukhi":"ਸਿਮਟਿ ਸਾਂਗ ਸੰਗ੍ਰਹਹਿ ਸਾਰ ਸਨਮੁਖ ਹ੍ਵੈ ਝਾਰਹਿ।","roman":"Simti saang sangrahhi saar sanmukh hvai jhaarhi |","meaning_en":"gathering their spears and swords, they face the foe and strike.","page":2103,"meaning_status":"draft","note":"Second line read loosely; uncertain.","meaning_pa":"ਭੰਗ ਖਾ ਕੇ ਸੂਰਮੇ ਲੜਦੇ ਹਨ ਅਤੇ ਹਾਥੀਆਂ ਤਕ ਦੇ ਦੰਦ ਉਖਾੜ ਦਿੰਦੇ ਹਨ। ਉਹ ਬਰਛੇ ਨੂੰ ਘੁਟ ਕੇ ਫੜਦੇ ਹਨ ਅਤੇ (ਵੈਰੀ ਦੇ) ਸਾਹਮਣੇ ਹਥਿਆਰ ('ਸਾਰ' ਲੋਹਾ) ਚਲਾਉਾਂਦੇ ਹਨ।","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"},{"gurmukhi":"ਤੈ ਮੂਜੀ ਪੀ ਭਾਂਗ ਕਹੋ ਕਾ ਕਾਜ ਸਵਰਿ ਹੈ।","roman":"Tai moojee pee bhaang kaho kaa kaaj savri hai |","meaning_en":"You, wretch, having drunk bhang, say what work will be accomplished?","page":2103,"meaning_status":"draft","note":"ਮੂਜੀ: read as 'wretch, base one'; uncertain."},{"gurmukhi":"ਹੋ ਹ੍ਵੈ ਕੈ ਮ੍ਰਿਤਕ ਸਮਾਨ ਜਾਇ ਔਧੇ ਮੁਖ ਪਰਿ ਹੈ। ੮੧।","roman":"Ho hvai kai mritak samaan jaai audhe mukh pari hai | 81 |","meaning_en":"Becoming like a corpse, you will go and fall on your face.","page":2103,"meaning_status":"draft","meaning_pa":"ਹੇ ਮੂਰਖ! ਤੂੰ ਭੰਗ ਪੀ ਕੇ ਦਸ ਕੀ ਕੰਮ ਸੰਵਾਰੇਾਂਗਾ। ਮ੍ਰਿਤਕ ਵਾਗ ਹੋ ਕੇ ਮੂਧੇ ਮੂੰਹ ਡਿਗੇਾਂਗਾ ॥੮੧॥","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"}]},{"type":"heading","kind":"chhand","name":"ਭੁਜੰਗ ਛੰਦ","gurmukhi":"ਭੁਜੰਗ ਛੰਦ","roman":"Bhujang chhand","meaning_en":"Bhujang metre.","page":2103,"meaning_status":"draft","note":"ਭੁਜੰਗ ਛੰਦ: Bhujang Prayat metre.","meaning_pa":"ਭੁਜੰਗ ਛੰਦ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[82],"number_text":"੮੨।","page":2103,"lines":[{"gurmukhi":"ਸੁਨੋ ਮਿਸ੍ਰ ਸਿਛਾ ਇਨੀ ਕੋ ਸੁ ਦੀਜੈ। ਮਹਾ ਝੂਠ ਤੇ ਰਾਖਿ ਕੈ ਮੋਹਿ ਲੀਜੈ।","roman":"Suno misr sichhaa inee ko su deejai | mahaa jhooth te raakhi kai mohi leejai |","meaning_en":"Listen, Mishra: give this teaching to these; protect me from great falsehood and take me in.","page":2103,"meaning_status":"draft","note":"Read loosely; uncertain.","meaning_pa":"ਹੇ ਬ੍ਰਾਹਮਣ! ਸੁਣੋ, (ਤੁਸੀਂ) ਸਿਖਿਆ ਇਨ੍ਰਹਾ (ਮੂਰਖਾ) ਨੂੰ ਹੀ ਦਿਓ। ਮੈਨੂੰ ਇਸ ਮਹਾ ਝੂਠ ਤੋਂ ਬਚਾ ਲਵੋ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਇਤੋ ਝੂਠ ਕੈ ਔਰ ਨੀਕੋ ਦ੍ਰਿੜਾਵੌ। ਕਹਾ ਚਾਮ ਕੇ ਦਾਮ ਕੈ ਕੈ ਚਲਾਵੌ। ੮੨।","roman":"Ito jhooth kai aur neeko driraavau | kahaa chaam ke daam kai kai chalaavau | 82 |","meaning_en":"Having told so much falsehood, you firmly instil it in others; why do you make coins of leather and circulate them?","page":2103,"meaning_status":"draft","meaning_pa":"ਇਸ ਝੂਠ ਨੂੰ ਕਿਸੇ ਹੋਰ ਢੰਗ ਨਾਲ ਦ੍ਰਿੜ੍ਰਹ ਕਰਾਓ ਅਤੇ ਚੰਮ ਦੇ ਦੰਮ ਕਹਿ ਕੇ ਚਲਾਓ ॥੮੨॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[83],"number_text":"੮੩।","page":2103,"lines":[{"gurmukhi":"ਮਹਾ ਘੋਰ ਈ ਨਰਕ ਕੇ ਬੀਚ ਜੈ ਹੌ। ਕਿ ਚੰਡਾਲ ਕੀ ਜੋਨਿ ਮੈ ਔਤਰੈ ਹੌ।","roman":"Mahaa ghor ee narak ke beech jai hau | ki chandaal kee joni mai autrai hau |","meaning_en":"You will go into the midst of dreadful hell, or you will be born in the womb of an outcaste;","page":2103,"meaning_status":"draft","note":"ਚੰਡਾਲ: 'chandal', outcaste.","meaning_pa":"(ਤੁਸੀਂ) ਮਹਾ ਘੋਰ ਨਰਕ ਵਿਚ ਜਾਓਗੇ। ਜਾ ਚੰਡਾਲ ਦੀ ਜੂਨ ਵਿਚ ਜਨਮ ਧਾਰਨ ਕਰੋਗੇ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਕਿ ਟਾਂਗੇ ਮਰੋਗੇ ਬਧੇ ਮ੍ਰਿਤਸ਼ਾਲਾ। ਸਨੈ ਬੰਧੁ ਪੁਤ੍ਰਾ ਕਲਤ੍ਰਾਨ ਬਾਲਾ। ੮੩।","roman":"Ki taange maroge badhe mritshaalaa | sanai bandhu putraa kaltraan baalaa | 83 |","meaning_en":"or you will die hung up and bound in the house of death, together with your kin, sons, wives and children.","page":2103,"meaning_status":"draft","note":"ਟਾਂਗੇ ਮਰੋਗੇ ਬਧੇ ਮ੍ਰਿਤਸ਼ਾਲਾ: obscure; read as printed; uncertain.","meaning_pa":"ਜਾ (ਤੁਸੀਂ) ਪੁਠੇ ਟੰਗੇ ਹੋਏ ਮੁਰਦਾ ਘਰ ਵਿਚ ਮਾਰੇ ਜਾਓਗੇ ਭਰਾ, ਪੁੱਤਰ, ਪਤਨੀ, ਪੁੱਤਰੀ ਸਮੇਤ  ॥੮੩॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[84],"number_text":"੮੪।","page":2105,"lines":[{"gurmukhi":"ਕਹੋ ਮਿਸ੍ਰ ਆਗੇ ਕਹਾ ਜ੍ਵਾਬ ਦੈਹੋ। ਜਬੈ ਕਾਲ ਕੇ ਜਾਲ ਮੈ ਫਾਸਿ ਜੈ ਹੋ।","roman":"Kaho misr aage kahaa jvaab daiho | jabai kaal ke jaal mai phaasi jai ho |","meaning_en":"Say, Mishra, what answer will you give hereafter, when you are caught in the net of Death?","page":2105,"meaning_status":"draft","meaning_pa":"ਹੇ ਬ੍ਰਾਹਮਣ! ਦਸੋ, ਅਗੇ ਕੀ ਜਵਾਬ ਦਿਓਗੇ, ਜਦੋਂ ਕਾਲ ਦੇ ਜਾਲ ਵਿਚ ਫਸ ਜਾਓਗੇ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਕਹੋ ਕੌਨ ਸੋ ਪਾਠ ਕੈਹੋ ਤਹਾ ਹੀ। ਤਊ ਲਿੰਗ ਪੂਜਾ ਕਰੌਗੇ ਉਹਾ ਹੀ। ੮੪।","roman":"Kaho kaun so paath kaiho tahaa hee | taoo ling poojaa karauge uhaa hee | 84 |","meaning_en":"Say, what recitation will you recite there? Will you even then do worship of the lingam there?","page":2105,"meaning_status":"draft","meaning_pa":"ਦਸੋ, ਉਥੇ ਕਿਹੜਾ ਪਾਠ ਕਰੋਗੇ। ਕੀ ਉਥੇ ਵੀ ਤੁਸੀਂ ਲਿੰਗ ਦੀ ਪੂਜਾ ਕਰੋਗੇ ॥੮੪॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[85],"number_text":"੮੫।","page":2105,"lines":[{"gurmukhi":"ਤਹਾ ਰੁਦ੍ਰ ਐ ਹੈ ਕਿ ਸ੍ਰੀ ਕ੍ਰਿਸਨ ਐ ਹੈ। ਜਹਾ ਬਾਧਿ ਸ੍ਰੀ ਕਾਲ ਤੋ ਕੌ ਚਲੇ ਹੈ।","roman":"Tahaa rudr ai hai ki sree krisan ai hai | jahaa baadhi sree kaal to kau chale hai |","meaning_en":"Will Rudra come there, or Sri Krishna, where Sri Kal takes you away bound?","page":2105,"meaning_status":"draft","meaning_pa":"ਉਥੇ ਰੁਦ੍ਰ ਆਵੇਗਾ ਜਾ ਸ੍ਰੀ ਕ੍ਰਿਸ਼ਨ ਆਵੇਗਾ, ਜਿਥੇ ਕਾਲ ਬੰਨ੍ਰਹ ਕੇ ਤੁਹਾਨੂੰ ਲੈ ਕੇ ਜਾਵੇਗਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਕਿਧੌ ਆਨਿ ਕੈ ਰਾਮ ਹ੍ਵੈ ਹੈ ਸਹਾਈ। ਜਹਾ ਪੁਤ੍ਰ ਮਾਤਾ ਨ ਤਾਤਾ ਨ ਭਾਈ। ੮੫।","roman":"Kidhau aani kai raam hvai hai sahaaee | jahaa putr maataa na taataa na bhaaee | 85 |","meaning_en":"Or will Ram come and be your helper, where there is no son, mother, father or brother?","page":2105,"meaning_status":"draft","meaning_pa":"ਕੀ ਉਥੇ ਤੁਹਾਡੀ ਰਾਮ ਆ ਕੇ ਮੱਦਦ ਕਰੇਗਾ? ਜਿਥੇ ਪੁੱਤਰ, ਮਾਤਾ, ਪਿਤਾ ਅਤੇ ਭਰਾ (ਤੁਹਾਡੇ ਨਾਲ) ਨਹੀਂ ਹੋਣਗੇ ॥੮੫॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[86],"number_text":"੮੬।","page":2105,"lines":[{"gurmukhi":"ਮਹਾ ਕਾਲ ਜੂ ਕੋ ਸਦਾ ਸੀਸ ਨ੍ਯੈਯੈ। ਪੁਰੀ ਚੌਦਹੂੰ ਤ੍ਰਾਸ ਜਾ ਕੋ ਤ੍ਰਸੈਯੈ।","roman":"Mahaa kaal joo ko sadaa sees nyaiyai | puree chaudhoon traas jaa ko trasaiyai |","meaning_en":"Always bow your head to Mahakal, whose terror makes the fourteen worlds tremble,","page":2105,"meaning_status":"draft","meaning_pa":"(ਇਸ ਲਈ) ਸਦਾ ਮਹਾ ਕਾਲ ਨੂੰ ਸੀਸ ਨਿਵਾਉਾਂਣਾ ਚਾਹੀਦਾ ਹੈ ਜਿਸ ਦੇ ਡਰ ਤੋਂ ਚੌਦਾ ਪੁਰੀਆਂ ਡਰਦੀਆਂ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਸਦਾ ਆਨਿ ਜਾ ਕੀ ਸਭੈ ਜੀਵ ਮਾਨੈ। ਸਭੈ ਲੋਕ ਖ੍ਯਾਤਾ ਬਿਧਾਤਾ ਪਛਾਨੈ। ੮੬।","roman":"Sadaa aani jaa kee sabhai jeev maanai | sabhai lok khyaataa bidhaataa pachhaanai | 86 |","meaning_en":"whose command all beings always obey, and whom all worlds know as the renowned Creator.","page":2105,"meaning_status":"draft","meaning_pa":"ਜਿਸ ਦੀ ਪ੍ਰਭੁਤਾ ਸਾਰੇ ਜੀਵ ਮੰਨਦੇ ਹਨ ਅਤੇ ਜਿਸ ਨੂੰ ਸਾਰੇ ਲੋਕ ਵਿਧਾਤਾ ਵਜੋਂ ਪਛਾਣਦੇ ਹਨ ॥੮੬॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[87],"number_text":"੮੭।","page":2105,"lines":[{"gurmukhi":"ਨਹੀ ਜਾਨਿ ਜਾਈ ਕਛੂ ਰੂਪ ਰੇਖਾ। ਕਹਾ ਬਾਸ ਤਾ ਕੋ ਫਿਰੈ ਕੌਨ ਭੇਖਾ।","roman":"Nahee jaani jaaee kachhoo roop rekhaa | kahaa baas taa ko phirai kaun bhekhaa |","meaning_en":"His form and mark cannot be known at all; where is His dwelling, what garb does He wander in?","page":2105,"meaning_status":"draft","meaning_pa":"ਜਿਸ ਦੀ ਕੁਝ ਵੀ ਰੂਪ-ਰੇਖਾ ਜਾਣੀ ਨਹੀਂ ਜਾ ਸਕਦੀ। ਉਸ ਦਾ ਵਾਸ ਕਿਥੇ ਹੈ ਅਤੇ ਕਿਸ ਭੇਸ ਵਿਚ ਫਿਰਦਾ ਹੈ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਕਹਾ ਨਾਮ ਤਾ ਕੋ ਕਹਾ ਕੈ ਕਹਾਵੈ। ਕਹਾ ਕੈ ਬਖਾਨੋ ਕਹੇ ਮੋ ਨ ਆਵੈ। ੮੭।","roman":"Kahaa naam taa ko kahaa kai kahaavai | kahaa kai bakhaano kahe mo na aavai | 87 |","meaning_en":"What is His name, by what is He called? Where shall I describe Him? Spoken of, it does not come to me.","page":2105,"meaning_status":"draft","meaning_pa":"ਉਸ ਦਾ ਕੀ ਨਾ ਹੈ ਅਤੇ ਕਿਥੋਂ ਦਾ ਅਖਵਾਉਾਂਦਾ ਹੈ। ਕਿਥੋਂ ਤਕ ਉਸ ਦਾ ਬਖਾਨ ਕਰਾ, ਕਥਨ ਵਿਚ ਨਹੀਂ ਆਉਾਂਦਾ ॥੮੭॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[88],"number_text":"੮੮।","page":2105,"lines":[{"gurmukhi":"ਨ ਤਾ ਕੋ ਕੋਊ ਤਾਤ ਮਾਤਾ ਨ ਭਾਈ। ਨ ਪੁਤ੍ਰਾ ਨ ਪੋਤ੍ਰਾ ਨ ਦਾਯਾ ਨ ਦਾਈ।","roman":"Na taa ko ko'oo taat maataa na bhaaee | na putraa na potraa na daayaa na daaee |","meaning_en":"He has no father, mother or brother, no son, grandson, nurse or midwife;","page":2105,"meaning_status":"draft","meaning_pa":"ਉਸ ਦਾ ਨਾ ਕੋਈ ਪਿਤਾ ਹੈ, ਨਾ ਮਾਤਾ, ਨਾ ਭਰਾ, ਨਾ ਪੁੱਤਰ, ਨਾ ਪੋਤਰਾ ਅਤੇ ਨਾ ਹੀ ਕੋਈ ਦਾਇਆ ਅਤੇ ਨਾ ਦਾਈ ਹੈ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਕਛੂ ਸੰਗ ਸੈਨਾ ਨ ਤਾ ਕੋ ਸੁਹਾਵੈ। ਕਹੈ ਸਤਿ ਸੋਈ ਕਰੈ ਸੋ ਬਨ੍ਯਾਵੈ। ੮੮।","roman":"Kachhoo sang sainaa na taa ko suhaavai | kahai sati soee karai so banyaavai | 88 |","meaning_en":"no army or company suits Him; what He says is true, and what He does, He brings about.","page":2105,"meaning_status":"draft","meaning_pa":"ਉਸ ਦੇ ਨਾਲ ਕੋਈ ਵੀ ਸੈਨਾ ਨਹੀਂ ਸ਼ੋਭਦੀ। ਉਹ ਸਤਿ ਕਹਿੰਦਾ ਹੈ ਅਤੇ ਉਹੀ ਕਰਦਾ ਹੈ ਜੋ ਬਣਦਾ ਸਰਦਾ ਹੈ ॥੮੮॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[89],"number_text":"੮੯।","page":2105,"lines":[{"gurmukhi":"ਕਈਊ ਸਵਾਰੈ ਕਈਊ ਖਪਾਵੈ। ਉਸਾਰੇ ਗੜੇ ਫੇਰਿ ਮੇਟੈ ਬਨਾਵੈ।","roman":"Kaeeoo savaarai kaeeoo khapaavai | usaare gare pheri metai banaavai |","meaning_en":"Many He adorns, many He destroys; He raises fortresses, then erases and makes them again.","page":2105,"meaning_status":"draft","meaning_pa":"(ਉਸ ਨੇ) ਕਈਆਂ ਨੂੰ ਸੰਵਾਰਿਆ ਹੈ ਅਤੇ ਕਈਆ ਨੂੰ ਖਪਾ ਦਿੱਤਾ ਹੈ। (ਕਈਆਂ ਨੂੰ) ਉਸਾਰਿਆ ਹੈ, ਘੜਿਆ ਹੈ, ਫਿਰ ਮਿਟਾਇਆ ਹੈ ਅਤੇ ਬਣਾਇਆ ਹੈ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਘਨੀ ਬਾਰ ਲੌ ਪੰਥ ਚਾਰੋ ਭ੍ਰਮਾਨਾ। ਮਹਾ ਕਾਲ ਹੀ ਕੋ ਗੁਰੂ ਕੈ ਪਛਾਨਾ। ੮੯।","roman":"Ghanee baar lau panth chaaro bhramaanaa | mahaa kaal hee ko guroo kai pachhaanaa | 89 |","meaning_en":"After wandering a long time over the four paths, I recognised Mahakal alone as Guru.","page":2105,"meaning_status":"draft","meaning_pa":"(ਉਹ) ਅਨੇਕ ਵਾਰ ਚੌਹਾ ਪਾਸੇ ਘੁੰਮਦਾ ਹੈ। ਮਹਾ ਕਾਲ ਨੂੰ ਗੁਰੂ ਰੂਪ ਵਿਚ ਪਛਾਣਿਆ ਜਾਦਾ ਹੈ ॥੮੯॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[90],"number_text":"੯੦।","page":2105,"lines":[{"gurmukhi":"ਮੁਰੀਦ ਹੈ ਉਸੀ ਕਾ ਵਹੈ ਪੀਰ ਮੇਰੋ। ਉਸੀ ਕਾ ਕਿਯਾ ਆਪਨਾ ਜੀਵ ਚੇਰੋ।","roman":"Mureed hai usee kaa vahai peer mero | usee kaa kiyaa aapnaa jeev chero |","meaning_en":"I am His disciple and He is my master; I have made my own soul His servant.","page":2105,"meaning_status":"draft","meaning_pa":"(ਮੈਂ) ਉਸੇ ਦੀ ਮੁਰੀਦ ਹਾ ਅਤੇ ਉਹੀ ਮੇਰਾ ਪੀਰ ਹੈ। ਉਸੇ ਦਾ ਹੀ (ਮੈਂ) ਆਪਣੇ ਜੀ ਨੂੰ ਚੇਲਾ ਬਣਾਇਆ ਹੋਇਆ ਹੈ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਤਿਸੀ ਕਾ ਕੀਆ ਬਾਲਕਾ ਮੈ ਕਹਾਵੌ। ਉਹੀ ਮੋਹਿ ਰਾਖਾ ਉਸੀ ਕੋ ਧਿਆਵੌ। ੯੦।","roman":"Tisee kaa keeaa baalkaa mai kahaavau | uhee mohi raakhaa usee ko dhiaavau | 90 |","meaning_en":"I am called a child made by Him; He has protected me, and on Him alone I meditate.","page":2105,"meaning_status":"draft","meaning_pa":"ਉਸੇ ਦੀ ਕੀਤੀ ਹੋਈ ਮੈਂ ਬਾਲਕਾ ਅਖਵਾਉਾਂਦੀ ਹਾ। ਉਹੀ ਮੇਰਾ ਰਾਖਾ ਹੈ ਅਤੇ ਉਸੇ ਦੀ ਮੈਂ ਆਰਾਧਨਾ ਕਰਦੀ ਹਾ ॥੯੦॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2105,"meaning_status":"draft","meaning_pa":"ਚੌਪਈ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[91],"number_text":"੯੧।","page":2105,"lines":[{"gurmukhi":"ਦਿਜ ਹਮ ਮਹਾ ਕਾਲ ਕੋ ਮਾਨੈ। ਪਾਹਨ ਮੈ ਮਨ ਕੋ ਨਹਿ ਆਨੈ।","roman":"Dij ham mahaa kaal ko maanai | paahan mai man ko nahi aanai |","meaning_en":"Brahmin, we honour Mahakal; we do not bring a stone into our mind.","page":2105,"meaning_status":"draft","meaning_pa":"ਹੇ ਬ੍ਰਾਹਮਣ! ਮੈਂ (ਕੇਵਲ) ਮਹਾ ਕਾਲ ਨੂੰ ਮੰਨਦੀ ਹਾ ਅਤੇ ਪੱਥਰਾ (ਦੀ ਪੂਜਾ ਵਿਚ ਆਪਣਾ) ਮਨ ਨਹੀਂ ਲਗਾਉਾਂਦੀ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਪਾਹਨ ਕੋ ਪਾਹਨ ਕਰਿ ਜਾਨਤ। ਤਾ ਤੇ ਬੁਰੋ ਲੋਗ ਏ ਮਾਨਤ। ੯੧।","roman":"Paahan ko paahan kari jaanat | taa te buro log e maanat | 91 |","meaning_en":"We know a stone as a stone, and for that these people consider us bad.","page":2105,"meaning_status":"draft","meaning_pa":"(ਮੈਂ) ਪੱਥਰ ਨੂੰ ਪੱਥਰ ਕਰ ਕੇ ਹੀ ਮੰਨਦੀ ਹਾ। ਇਸੇ ਲਈ (ਇਹ) ਲੋਕ ਬੁਰਾ ਮੰਨਦੇ ਹਨ ॥੯੧॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[92],"number_text":"੯੨।","page":2105,"lines":[{"gurmukhi":"ਝੂਠਾ ਕਹ ਝੂਠਾ ਹਮ ਕੈ ਹੈ। ਜੋ ਸਭ ਲੋਗ ਮਨੈ ਕੁਰਰੈ ਹੈ।","roman":"Jhoothaa kah jhoothaa ham kai hai | jo sabh log manai kurrai hai |","meaning_en":"We shall call the false false, though all people hold it to be true.","page":2105,"meaning_status":"draft","note":"ਕੁਰਰੈ: obscure; read as printed; uncertain.","meaning_pa":"ਝੂਠੇ ਨੂੰ ਤਾ ਮੈਂ ਝੂਠਾ ਕਹਾਗੀ ਭਾਵੇਾਂ ਸਾਰੇ ਲੋਕ ਮਨ ਵਿਚ (ਕਿਉਾਂ ਨ) ਖਿਝਣ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਹਮ ਕਾਹੂ ਕੀ ਕਾਨਿ ਨ ਰਾਖੈ। ਸਤਿ ਬਚਨ ਮੁਖ ਊਪਰ ਭਾਖੈ। ੯੨।","roman":"Ham kaahoo kee kaani na raakhai | sati bachan mukh oopar bhaakhai | 92 |","meaning_en":"We keep awe of no one; we speak true words to the face.","page":2105,"meaning_status":"draft","meaning_pa":"ਮੈਂ ਕਿਸੇ ਦੀ ਪਰਵਾਹ ਨਹੀਂ ਰਖਦੀ ਹਾ ਅਤੇ ਮੂੰਹ ਉਤੇ ਸੱਚੀ ਗੱਲ ਕਹਿੰਦੀ ਹਾ ॥੯੨॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[93],"number_text":"੯੩।","page":2105,"lines":[{"gurmukhi":"ਸੁਨੁ ਦਿਜ ਤੁਮ ਧਨ ਕੇ ਲਬ ਲਾਗੇ। ਮਾਂਗਤ ਫਿਰਤ ਸਭਨ ਕੇ ਆਗੇ।","roman":"Sunu dij tum dhan ke lab laage | maangat phirat sabhan ke aage |","meaning_en":"Listen, brahmin, you are attached to greed for wealth and go begging before everyone.","page":2105,"meaning_status":"draft","meaning_pa":"ਹੇ ਬ੍ਰਾਹਮਣ! ਸੁਣੋ, ਤੁਸੀਂ ਧਨ ਦੇ ਲੋਭ ਵਿਚ ਲਗੇ ਹੋਏ ਸਭ ਦੇ ਅਗੇ ਮੰਗਦੇ ਫਿਰਦੇ ਹੋ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਆਪਨੇ ਮਨ ਭੀਤਰਿ ਨ ਲਜਾਵਹੁ। ਇਕ ਟਕ ਹ੍ਵੈ ਹਰਿ ਧ੍ਯਾਨ ਨ ਲਾਵਹੁ। ੯੩।","roman":"Aapne man bheetri na lajaavhu | ik tak hvai hari dhyaan na laavhu | 93 |","meaning_en":"You are not ashamed in your own mind, and do not fix your meditation steadily on Hari.","page":2105,"meaning_status":"draft","meaning_pa":"ਆਪਣੇ ਮਨ ਵਿਚ ਲਜਿਤ ਨਹੀਂ ਹੁੰਦੇ ਅਤੇ ਇਕ ਟਕ ਹੋ ਕੇ ਹਰਿ ਵਲ ਧਿਆਨ ਨਹੀਂ ਲਗਾਉਾਂਦੇ ॥੯੩॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"speaker","name":"ਦਿਜ ਬਾਚ","gurmukhi":"ਦਿਜ ਬਾਚ","roman":"Dij baach","meaning_en":"The brahmin said:","page":2105,"meaning_status":"draft","meaning_pa":"ਬ੍ਰਾਹਮਣ ਨੇ ਕਿਹਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[94],"number_text":"੯੪।","page":2105,"lines":[{"gurmukhi":"ਤਬ ਦਿਜ ਬੋਲਾ ਤੈ ਕ੍ਯਾ ਮਾਨੈ। ਸੰਭੂ ਕੋ ਪਾਹਨ ਕਰਿ ਮਾਨੈ।","roman":"Tab dij bolaa tai kyaa maanai | sanbhoo ko paahan kari maanai |","meaning_en":"Then the brahmin said: 'What do you believe? Do you take Shambhu to be a stone?","page":2105,"meaning_status":"draft","meaning_pa":"ਤਦ ਬ੍ਰਾਹਮਣ ਬੋਲਿਆ ਕਿ ਤੂੰ ਕੀ ਮੰਨ ਸਕਦੀ ਹੈਂ, ਜੋ ਸ਼ਿਵ ਨੂੰ ਪੱਥਰ ਸਮਝ ਰਹੀ ਹੈਂ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜੋ ਇਨ ਕੋ ਕਰਿ ਆਨ ਬਖਾਨੈ। ਤਾ ਕੋ ਬ੍ਰਹਮ ਪਾਤਕੀ ਜਾਨੈ। ੯੪।","roman":"Jo in ko kari aan bakhaanai | taa ko braham paatkee jaanai | 94 |","meaning_en":"Whoever speaks of these otherwise, know him a slayer of a brahmin.","page":2105,"meaning_status":"draft","note":"ਬ੍ਰਹਮ ਪਾਤਕੀ: read as 'one who commits the sin of killing a brahmin'; uncertain.","meaning_pa":"ਜੋ ਇਨ੍ਰਹਾ ਨੂੰ ਕੁਝ ਹੋਰ ਹੀ (ਭਾਵ ਉਲਟ) ਸਮਝਦਾ ਹੈ, ਉਸ ਨੂੰ ਪਰਮਾਤਮਾ ਪਾਪੀ ਸਮਝਦਾ ਹੈ ॥੯੪॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[95],"number_text":"੯੫।","page":2105,"lines":[{"gurmukhi":"ਜੋ ਇਨ ਕਹ ਕਟੁ ਬਚਨ ਉਚਾਰੈ। ਤਾ ਕੌ ਮਹਾ ਨਰਕ ਬਿਧਿ ਡਾਰੈ।","roman":"Jo in kah katu bachan uchaarai | taa kau mahaa narak bidhi daarai |","meaning_en":"Whoever utters harsh words to these, the Creator casts him into great hell.","page":2105,"meaning_status":"draft","meaning_pa":"ਜੋ ਇਨ੍ਰਹਾ ਪ੍ਰਤਿ ਕੌੜੇ ਬੋਲ ਬੋਲਦਾ ਹੈ, ਉਨ੍ਰਹਾ ਨੂੰ ਵਿਧਾਤਾ ਭਿਆਨਕ ਨਰਕ ਵਿਚ ਸੁਟਦਾ ਹੈ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਇਨ ਕੀ ਸਦਾ ਕੀਜਿਯੈ ਸੇਵਾ। ਏ ਹੈ ਪਰਮ ਪੁਰਾਤਨ ਦੇਵਾ। ੯੫।","roman":"In kee sadaa keejiyai sevaa | e hai param puraatan devaa | 95 |","meaning_en":"These should always be served; these are supremely ancient gods.'","page":2105,"meaning_status":"draft","meaning_pa":"ਇਨ੍ਰਹਾ ਦੀ ਸਦਾ ਸੇਵਾ ਕਰਨੀ ਚਾਹੀਦੀ ਹੈ ਕਿਉਾਂਕਿ ਇਹ ਪਰਮ ਪੁਰਾਤਨ ਦੇਵਤੇ ਹਨ ॥੯੫॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"speaker","name":"ਕੁਅਰਿ ਬਾਚ","gurmukhi":"ਕੁਅਰਿ ਬਾਚ","roman":"Kuari baach","meaning_en":"The princess said:","page":2107,"meaning_status":"draft","meaning_pa":"ਰਾਜ ਕੁਮਾਰੀ ਨੇ ਕਿਹਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[96],"number_text":"੯੬।","page":2107,"lines":[{"gurmukhi":"ਏਕੈ ਮਹਾ ਕਾਲ ਹਮ ਮਾਨੈ। ਮਹਾ ਰੁਦ੍ਰ ਕਹ ਕਛੂ ਨ ਜਾਨੈ।","roman":"Ekai mahaa kaal ham maanai | mahaa rudr kah kachhoo na jaanai |","meaning_en":"'We honour Mahakal alone; we know nothing of Maha Rudra.","page":2107,"meaning_status":"draft","meaning_pa":"ਮੈਂ ਇਕੋ ਮਹਾ ਕਾਲ ਨੂੰ ਮੰਨਦੀ ਹਾ। ਮੈਂ ਮਹਾ ਰੁਦ੍ਰ ਨੂੰ ਕੁਝ ਨਹੀਂ ਸਮਝਦੀ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਬ੍ਰਹਮ ਬਿਸਨ ਕੀ ਸੇਵ ਨ ਕਰਹੀ। ਤਿਨ ਤੇ ਹਮ ਕਬਹੂੰ ਨਹੀ ਡਰਹੀ। ੯੬।","roman":"Braham bisan kee sev na karhee | tin te ham kabhoon nahee darhee | 96 |","meaning_en":"We do not serve Brahma and Vishnu; we never fear them.","page":2107,"meaning_status":"draft","meaning_pa":"(ਮੈਂ) ਬ੍ਰਹਮਾ ਅਤੇ ਵਿਸ਼ਣੂ ਦੀ ਸੇਵਾ ਵੀ ਨਹੀਂ ਕਰਦੀ ਅਤੇ ਇਨ੍ਰਹਾ ਤੋਂ ਮੈਂ ਕਦੇ ਵੀ ਨਹੀਂ ਡਰਦੀ ॥੯੬॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[97],"number_text":"੯੭।","page":2107,"lines":[{"gurmukhi":"ਬ੍ਰਹਮ ਬਿਸਨ ਜਿਨ ਪੁਰਖ ਉਚਾਰਿਯੋ। ਤਾ ਕੌ ਮ੍ਰਿਤੁ ਜਾਨਿਯੈ ਮਾਰਿਯੋ।","roman":"Braham bisan jin purakh uchaariyo | taa kau mritu jaaniyai maariyo |","meaning_en":"Those whom they call Brahma and Vishnu, the Supreme Person, know them as struck down by death.","page":2107,"meaning_status":"draft","meaning_pa":"ਜਿਸ ਵਿਅਕਤੀ ਨੇ ਬ੍ਰਹਮਾ ਅਤੇ ਵਿਸ਼ਣੂ (ਦੇ ਨਾਮ ਦਾ) ਉਚਾਰਨ ਕੀਤਾ ਹੈ, ਸਮਝੋ ਉਸ ਨੂੰ ਮ੍ਰਿਤੂ ਨੇ ਮਾਰ ਸੁਟਿਆ ਹੈ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜਿਨ ਨਰ ਕਾਲ ਪੁਰਖ ਕੋ ਧ੍ਯਾਯੋ। ਤਾ ਕੇ ਨਿਕਟ ਕਾਲ ਨਹਿ ਆਯੋ। ੯੭।","roman":"Jin nar kaal purakh ko dhyaayo | taa ke nikat kaal nahi aayo | 97 |","meaning_en":"The man who meditated on Kal Purakh, Death did not come near him.","page":2107,"meaning_status":"draft","note":"ਕਾਲ ਪੁਰਖ: 'Kal Purakh', the Person of Time/Death.","meaning_pa":"ਜਿਸ ਬੰਦੇ ਨੇ ਕਾਲ ਪੁਰਖ ਦੀ ਆਰਾਧਨਾ ਕੀਤੀ ਹੈ, ਉਸ ਦੇ ਨੇੜੇ 'ਕਾਲ' (ਮ੍ਰਿਤੂ) ਨਹੀਂ ਆਉਾਂਦਾ ॥੯੭॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[98],"number_text":"੯੮।","page":2107,"lines":[{"gurmukhi":"ਜੇ ਨਰ ਕਾਲ ਪੁਰਖ ਕੋ ਧ੍ਯਾਵੈ। ਤੇ ਨਰ ਕਾਲ ਫਾਸ ਨਹਿ ਜਾਵੈ।","roman":"Je nar kaal purakh ko dhyaavai | te nar kaal phaas nahi jaavai |","meaning_en":"The men who meditate on Kal Purakh do not go into the noose of Death;","page":2107,"meaning_status":"draft","meaning_pa":"ਜੋ ਪੁਰਸ਼ ਕਾਲ ਪੁਰਖ ਨੂੰ ਧਿਆਉਾਂਦਾ ਹੈ, ਉਹ ਪੁਰਸ਼ ਕਾਲ ਦੀ ਫਾਹੀ ਵਿਚ ਨਹੀਂ ਫਸਦਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਤਿਨ ਕੇ ਰਿਧ ਸਿਧ ਸਭ ਘਰ ਮੌ। ਕੋਬਿਦ ਸਭ ਹੀ ਰਹਤ ਹੁਨਰ ਮੌ। ੯੮।","roman":"Tin ke ridh sidh sabh ghar mau | kobid sabh hee rahat hunar mau | 98 |","meaning_en":"in their houses are all riddhis and siddhis; the skilled remain in their craft.","page":2107,"meaning_status":"draft","note":"ਕੋਬਿਦ: read as 'the skilled/learned'; uncertain.","meaning_pa":"ਉਸ ਦੇ ਘਰ ਵਿਚ ਸਭ ਰਿੱਧੀਆਂ ਸਿੱਧੀਆਂ (ਰਹਿੰਦੀਆਂ ਹਨ) ਅਤੇ (ਉਹ) ਸਾਰਿਆਂ ਹੁਨਰਾ ਵਿਚ ਪ੍ਰਬੀਨ ਰਹਿੰਦਾ ਹੈ ॥੯੮॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[99],"number_text":"੯੯।","page":2107,"lines":[{"gurmukhi":"ਕਾਲ ਪੁਰਖ ਇਕਦਾ ਜਿਨ ਕਹਾ। ਤਾ ਕੇ ਰਿਧਿ ਸਿਧਿ ਹ੍ਵੈ ਰਹਾ।","roman":"Kaal purakh ikdaa jin kahaa | taa ke ridhi sidhi hvai rahaa |","meaning_en":"Whoever once has said 'Kal Purakh', riddhis and siddhis come to him;","page":2107,"meaning_status":"draft","meaning_pa":"ਜੋ ਇਕ ਵਾਰ ਵੀ ਕਾਲ ਪੁਰਖ ਦਾ (ਨਾਮ) ਲੈਂਦਾ ਹੈ, (ਸਭ) ਰਿੱਧੀਆਂ ਸਿੱਧੀਆਂ ਉਸ ਦੀਆਂ ਹੋ ਜਾਦੀਆਂ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਧਨ ਭਰੇ ਭੰਡਾਰੂ। ਜਿਨ ਕਾ ਆਵਤ ਵਾਰ ਨ ਪਾਰੂ। ੯੯।","roman":"Bhaati bhaati dhan bhare bhandaaroo | jin kaa aavat vaar na paaroo | 99 |","meaning_en":"his storehouses fill with every kind of wealth, of which no end or bank comes.","page":2107,"meaning_status":"draft","meaning_pa":"(ਉਸ ਦੇ) ਭਾਤ ਭਾਤ ਦੇ ਧਨ ਦੇ ਭੰਡਾਰ ਭਰ ਜਾਦੇ ਹਨ, ਜਿਨ੍ਰਹਾ ਦਾ ਕੋਈ ਅੰਤ ਨਹੀਂ ਪਾਇਆ ਜਾ ਸਕਦਾ ॥੯੯॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[100],"number_text":"੧੦੦।","page":2107,"lines":[{"gurmukhi":"ਜਿਨ ਨਰ ਕਾਲ ਪੁਰਖ ਕਹ ਧ੍ਯਾਯੋ। ਸੋ ਨਰ ਕਲਿ ਮੋ ਕਬਹੂ ਨ ਆਯੋ।","roman":"Jin nar kaal purakh kah dhyaayo | so nar kali mo kabhoo na aayo |","meaning_en":"The man who meditated on Kal Purakh never came into the Kali age;","page":2107,"meaning_status":"draft","meaning_pa":"ਜਿਸ ਪੁਰਸ਼ ਨੇ ਕਾਲ ਪੁਰਖ ਨੂੰ ਧਿਆਇਆ ਹੈ, ਉਹ ਪੁਰਸ਼ ਫਿਰ ਕਲਿਯੁਗ ਨੂੰ ਕਦੇ ਵੀ ਨਹੀਂ ਆਉਾਂਦਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਯਾ ਜਗ ਮੈ ਤੇ ਅਤਿ ਸੁਖ ਪਾਵੈ। ਭੋਗ ਕਰੈ ਬੈਰਨਿ ਕਹ ਘਾਵੈ। ੧੦੦।","roman":"Yaa jag mai te ati sukh paavai | bhog karai bairni kah ghaavai | 100 |","meaning_en":"in this world he gets great comfort, enjoys himself and kills his enemies.","page":2107,"meaning_status":"draft","meaning_pa":"(ਉਹ) ਇਸ ਜਗਤ ਵਿਚ ਬਹੁਤ ਸੁਖ ਪ੍ਰਾਪਤ ਕਰਦਾ ਹੈ ਅਤੇ ਵੈਰੀਆਂ ਨੂੰ ਮਾਰਦਾ ਹੋਇਆ ਸੰਸਾਰਿਕਤਾ ਨੂੰ ਮਾਣਦਾ ਹੈ ॥੧੦੦॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[101],"number_text":"੧੦੧।","page":2107,"lines":[{"gurmukhi":"ਜਬ ਤੋ ਕੋ ਦਿਜ ਕਾਲ ਸਤੈ ਹੈ। ਤਬ ਤੂ ਕੋ ਪੁਸਤਕ ਕਰ ਲੈ ਹੈ।","roman":"Jab to ko dij kaal satai hai | tab too ko pustak kar lai hai |","meaning_en":"When Death assails you, brahmin, will you then take up a book in your hand?","page":2107,"meaning_status":"draft","meaning_pa":"ਹੇ ਬ੍ਰਾਹਮਣ! ਜਦੋਂ ਤੈਨੂੰ ਕਾਲ ਦੁਖੀ ਕਰੇਗਾ, ਤਦ ਤੂੰ ਕਿਹੜੀ ਪੁਸਤਕ ਹੱਥ ਵਿਚ ਲਵੇਾਂਗਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਭਾਗਵਤ ਪੜੋ ਕਿ ਗੀਤਾ ਕਹਿ ਹੋ। ਰਾਮਹਿ ਪਕਰਿ ਕਿ ਸਿਵ ਕਹ ਗਹਿ ਹੋ। ੧੦੧।","roman":"Bhaagvat paro ki geetaa kahi ho | raamhi pakri ki siv kah gahi ho | 101 |","meaning_en":"Will you read the Bhagavat, or speak the Gita? Will you seize Ram, or hold Shiva?","page":2107,"meaning_status":"draft","meaning_pa":"ਕੀ ਭਾਗਵਤ ਪੁਰਾਣ ਪੜ੍ਰਹੋਗੇ ਜਾ ਭਗਵਦ ਗੀਤਾ ਨੂੰ ਉਚਾਰੋਗੇ। ਰਾਮ ਨੂੰ ਪਕੜੋਗੇ ਕਿ ਸ਼ਿਵ ਨੂੰ ਫੜੋਗੇ ॥੧੦੧॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[102],"number_text":"੧੦੨।","page":2107,"lines":[{"gurmukhi":"ਜੇ ਤੁਮ ਪਰਮ ਪੁਰਖ ਠਹਰਾਏ। ਤੇ ਸਭ ਡੰਡ ਕਾਲ ਕੇ ਘਾਏ।","roman":"Je tum param purakh thahraae | te sabh dand kaal ke ghaae |","meaning_en":"Those whom you have set up as the supreme Person, all were struck by the rod of Death.","page":2107,"meaning_status":"draft","meaning_pa":"ਜਿਨ੍ਰਹਾ ਨੂੰ ਤੂੰ ਪਰਮ ਪੁਰਖ ਵਜੋਂ ਸਥਾਪਿਤ ਕੀਤਾ ਹੈ ਉਹ ਸਭ ਕਾਲ ਦੇ ਡੰਡੇ ਦੇ ਮਾਰੇ ਹੋਏ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਕਾਲ ਡੰਡ ਬਿਨ ਬਚਾ ਨ ਕੋਈ। ਸਿਵ ਬਿਰੰਚ ਬਿਸਨਿੰਦ੍ਰ ਨ ਸੋਈ। ੧੦੨।","roman":"Kaal dand bin bachaa na koee | siv biranch bisnindr na soee | 102 |","meaning_en":"Without the rod of Death none has escaped, neither Shiva, Brahma, Vishnu nor Indra.","page":2107,"meaning_status":"draft","meaning_pa":"ਕਾਲ ਦੇ ਡੰਡੇ ਤੋਂ ਸ਼ਿਵ, ਬ੍ਰਹਮਾ, ਵਿਸ਼ਣੂ, ਇੰਦਰ ਆਦਿ ਕੋਈ ਵੀ ਬਚ ਨਹੀਂ ਸਕਿਆ ॥੧੦੨॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[103],"number_text":"੧੦੩।","page":2107,"lines":[{"gurmukhi":"ਜੈਸਿ ਜੂਨਿ ਇਕ ਦੈਤ ਬਖਨਿਯਤ। ਤ੍ਯੋ ਇਕ ਜੂਨਿ ਦੇਵਤਾ ਜਨਿਯਤ।","roman":"Jaisi jooni ik dait bakhniyat | tyo ik jooni devtaa janiyat |","meaning_en":"As one species is spoken of as demons, so one species is known as gods;","page":2107,"meaning_status":"draft","meaning_pa":"ਜਿਵੇਾਂ ਇਕ ਦੈਂਤ ਜੂਨ ਕਹੀ ਜਾਦੀ ਹੈ, ਉਸੇ ਤਰ੍ਰਹਾ ਇਕ ਦੇਵਤਾ ਜੂਨ ਵੀ ਜਾਣੀ ਜਾਦੀ ਹੈ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜੈਸੇ ਹਿੰਦੂਆਨੋ ਤੁਰਕਾਨਾ। ਸਭਹਿੰਨ ਸੀਸ ਕਾਲ ਜਰਵਾਨਾ। ੧੦੩।","roman":"Jaise hindooaano turkaanaa | sabhhinn sees kaal jarvaanaa | 103 |","meaning_en":"as the Hindus and the Turks, over the heads of all is the mighty Death.","page":2107,"meaning_status":"draft","meaning_pa":"ਜਿਵੇਾਂ ਕੋਈ ਹਿੰਦੂ ਜਾ ਮੁਸਲਮਾਨ ਹੈ, ਪਰ ਉਨ੍ਰਹਾ ਸਾਰਿਆਂ ਦੇ ਸਿਰ ਉਤੇ ਕਾਲ ਮਹਾਬਲੀ ਹੈ ॥੧੦੩॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[104],"number_text":"੧੦੪।","page":2107,"lines":[{"gurmukhi":"ਕਬਹੂੰ ਦੈਤ ਦੇਵਤਨ ਮਾਰੈ। ਕਬਹੂੰ ਦੈਤਨ ਦੇਵ ਸੰਘਾਰੈ।","roman":"Kabhoon dait devtan maarai | kabhoon daitan dev sanghaarai |","meaning_en":"Sometimes the demons kill the gods, sometimes the gods destroy the demons;","page":2107,"meaning_status":"draft","meaning_pa":"ਕਦੀ ਦੇਵਤਿਆਂ ਨੇ ਦੈਂਤਾ ਨੂੰ ਮਾਰਿਆ ਹੈ ਅਤੇ ਕਦੇ ਦੈਂਤਾ ਨੇ ਦੇਵਤਿਆਂ ਨੂੰ ਸੰਘਾਰਿਆ ਹੈ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਦੇਵ ਦੈਤ ਜਿਨ ਦੋਊ ਸੰਘਾਰਾ। ਵਹੈ ਪੁਰਖ ਪ੍ਰਤਿਪਾਲ ਹਮਾਰਾ। ੧੦੪।","roman":"Dev dait jin do'oo sanghaaraa | vahai purakh pratipaal hamaaraa | 104 |","meaning_en":"He who destroyed both gods and demons, that same Person is our cherisher.","page":2107,"meaning_status":"draft","meaning_pa":"ਜਿਸ ਨੇ ਦੇਵਤਿਆਂ ਅਤੇ ਦੈਂਤਾ ਦੋਹਾ ਨੂੰ ਮਾਰਿਆ ਹੈ, ਉਹ (ਕਾਲ) ਪੁਰਖ ਮੇਰਾ ਪ੍ਰਤਿਪਾਲਕ ਹੈ ॥੧੦੪॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":2107,"meaning_status":"draft","meaning_pa":"ਅੜਿਲ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[105],"number_text":"੧੦੫।","page":2107,"lines":[{"gurmukhi":"ਇੰਦ੍ਰ ਉਪਿੰਦ੍ਰ ਦਿਨਿੰਦ੍ਰਹਿ ਜੌਨ ਸੰਘਾਰਿਯੋ।","roman":"Indr upindr dinindrahi jaun sanghaariyo |","meaning_en":"He who destroyed Indra, Upendra and Dinendra (the sun),","page":2107,"meaning_status":"draft","meaning_pa":"ਜਿਸ ਨੇ ਇੰਦਰ, ਉਪਿੰਦਰ (ਵਾਮਨ) ਸੂਰਜ,","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਚੰਦ੍ਰ ਕੁਬੇਰ ਜਲਿੰਦ੍ਰ ਅਹਿੰਦ੍ਰਹਿ ਮਾਰਿਯੋ।","roman":"Chandr kuber jalindr ahindrahi maariyo |","meaning_en":"who killed Chandra, Kuber, Jalindra and Ahindra,","page":2107,"meaning_status":"draft","note":"Names kept as printed: Jalindra (lord of waters), Ahindra (lord of serpents); uncertain.","meaning_pa":"ਚੰਦ੍ਰਮਾ, ਕੁਬੇਰ, ਵਰੁਣ ਅਤੇ ਸ਼ੇਸ਼ਨਾਗ ਨੂੰ ਮਾਰ ਦਿੱਤਾ ਹੈ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਪੁਰੀ ਚੌਦਹੂੰ ਚਕ੍ਰ ਜਵਨ ਸੁਨਿ ਲੀਜਿਯੈ।","roman":"Puree chaudhoon chakr javan suni leejiyai |","meaning_en":"listen, and take Him whose is the circle of the fourteen worlds;","page":2107,"meaning_status":"draft","meaning_pa":"ਜਿਸ ਦਾ ਚੌਦਾ ਲੋਕਾ ਵਿਚ ਚੱਕਰ ਚਲਦਾ ਸੁਣੀਂਦਾ ਹੈ,","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਹੋ ਨਮਸਕਾਰ ਤਾਹੀ ਕੋ ਗੁਰ ਕਰਿ ਕੀਜਿਯੈ। ੧੦੫।","roman":"Ho namaskaar taahee ko gur kari keejiyai | 105 |","meaning_en":"make salutation to Him alone, taking Him as Guru.","page":2107,"meaning_status":"draft","meaning_pa":"ਉਸੇ ਨੂੰ ਪ੍ਰਨਾਮ ਕਰ ਕੇ ਗੁਰੂ ਧਾਰਨ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ ॥੧੦੫॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"speaker","name":"ਦਿਜ ਬਾਚ","gurmukhi":"ਦਿਜ ਬਾਚ","roman":"Dij baach","meaning_en":"The brahmin said:","page":2109,"meaning_status":"draft","note":"Printed so; the following verse reads like narration.","meaning_pa":"ਬ੍ਰਾਹਮਣ ਨੇ ਕਿਹਾ:","meaning_pa_source":"BaniDB"},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2109,"meaning_status":"draft","meaning_pa":"ਚੌਪਈ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[106],"number_text":"੧੦੬।","page":2109,"lines":[{"gurmukhi":"ਬਹੁ ਬਿਧਿ ਬਿਪ੍ਰਹਿ ਕੋ ਸਮਝਾਯੋ। ਪੁਨਿ ਮਿਸ੍ਰਹਿ ਅਸ ਭਾਖਿ ਸੁਨਾਯੋ।","roman":"Bahu bidhi biprahi ko samjhaayo | puni misrahi as bhaakhi sunaayo |","meaning_en":"He explained to the brahmin in many ways; then Mishra spoke thus:","page":2109,"meaning_status":"draft","note":"Who is speaking is unclear in the text; translated as printed.","meaning_pa":"(ਰਾਜ ਕੁਮਾਰੀ ਨੇ) ਕਈ ਤਰ੍ਰਹਾ ਨਾਲ ਬ੍ਰਾਹਮਣ ਨੂੰ ਸਮਝਾਇਆ। ਫਿਰ ਬ੍ਰਾਹਮਣ ਨੇ ਇਸ ਤਰ੍ਰਹਾ ਕਿਹਾ,","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜੇ ਪਾਹਨ ਕੀ ਪੂਜਾ ਕਰਿ ਹੈ। ਤਾ ਕੇ ਪਾਪ ਸਕਲ ਸਿਵ ਹਰਿ ਹੈ। ੧੦੬।","roman":"Je paahan kee poojaa kari hai | taa ke paap sakal siv hari hai | 106 |","meaning_en":"'Those who worship stone, Shiva will remove all their sins.","page":2109,"meaning_status":"draft","meaning_pa":"ਜੋ ਪੱਥਰ ਦੀ ਪੂਜਾ ਕਰਦਾ ਹੈ, ਉਨ੍ਰਹਾ ਦੇ ਸਾਰੇ ਪਾਪ ਸ਼ਿਵ ਖ਼ੁਦ ਦੂਰ ਕਰ ਦਿੰਦਾ ਹੈ ॥੧੦੬॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[107],"number_text":"੧੦੭।","page":2109,"lines":[{"gurmukhi":"ਜੇ ਨਰ ਸਾਲਿਗ੍ਰਾਮ ਕਹ ਧਯੈ ਹੈ। ਤਾ ਕੇ ਸਕਲ ਪਾਪ ਕੋ ਛੈ ਹੈ।","roman":"Je nar saaligraam kah dhayai hai | taa ke sakal paap ko chhai hai |","meaning_en":"Those men who meditate on the Shaligram, all their sins will be destroyed;","page":2109,"meaning_status":"draft","meaning_pa":"ਜੋ ਵਿਅਕਤੀ ਸਾਲਿਗ੍ਰਾਮ ਨੂੰ ਧਿਆਏਗਾ, ਉਸ ਦੇ ਸਾਰੇ ਪਾਪ ਖ਼ਤਮ ਹੈ ਜਾਣਗੇ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜੋ ਇਹ ਛਾਡਿ ਅਵਰ ਕਹ ਧਯੈ ਹੈ। ਤੇ ਨਰ ਮਹਾ ਨਰਕ ਮਹਿ ਜੈ ਹੈ। ੧੦੭।","roman":"Jo ih chhaadi avar kah dhayai hai | te nar mahaa narak mahi jai hai | 107 |","meaning_en":"those who leave this and meditate on another, those men will go into great hell.","page":2109,"meaning_status":"draft","meaning_pa":"ਜੋ ਇਸ ਨੂੰ ਛਡ ਕੇ ਹੋਰ ਕਿਸੇ ਦਾ ਧਿਆਨ ਕਰੇਗਾ ਉਹ ਪੁਰਸ਼ ਮਹਾ ਨਰਕ ਵਿਚ ਪਵੇਗਾ ॥੧੦੭॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[108],"number_text":"੧੦੮।","page":2109,"lines":[{"gurmukhi":"ਜੇ ਨਰ ਕਛੁ ਧਨ ਬਿਪ੍ਰਹਿ ਦੈ ਹੈ। ਆਗੇ ਮਾਗ ਦਸ ਗੁਨੋ ਲੈਹੈ।","roman":"Je nar kachhu dhan biprahi dai hai | aage maag das guno laihai |","meaning_en":"Those men who give some wealth to a brahmin will take it back ten-fold in the future on demand;","page":2109,"meaning_status":"draft","meaning_pa":"ਜੋ ਵਿਅਕਤੀ ਬ੍ਰਾਹਮਣ ਨੂੰ ਕੁਝ ਧਨ ਦੇਵੇਗਾ, ਉਹ ਅਗਲੇ ਜਨਮ ਵਿਚ ਦਸ ਗੁਣਾ ਮੰਗ ਲਵੇਗਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜੋ ਬਿਪ੍ਰਨ ਬਿਨੁ ਅਨਤੈ ਦੇਹੀ। ਤਾ ਕੌ ਕਛੁ ਸੁ ਫਲੈ ਨਹਿ ਸੇਈ। ੧੦੮।","roman":"Jo bipran binu antai dehee | taa kau kachhu su phalai nahi se'ee | 108 |","meaning_en":"whoever gives elsewhere, without brahmins, nothing bears fruit for him.'","page":2109,"meaning_status":"draft","meaning_pa":"ਜੋ ਬ੍ਰਾਹਮਣ ਤੋਂ ਬਿਨਾ ਕਿਸੇ ਹੋਰ ਨੂੰ ਦੇਵੇਗਾ, ਉਸ ਨੂੰ ਉਸ ਦਾ ਕੋਈ ਫਲ ਪ੍ਰਾਪਤ ਨਹੀਂ ਹੋਵੇਗਾ ॥੧੦੮॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":2109,"meaning_status":"draft","meaning_pa":"ਅੜਿਲ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[109],"number_text":"੧੦੯।","page":2109,"lines":[{"gurmukhi":"ਤਬੈ ਕੁਅਰਿ ਪ੍ਰਤਿਮਾ ਸਿਵ ਕੀ ਕਰ ਮੈ ਲਈ।","roman":"Tabai kuari pratimaa siv kee kar mai laee |","meaning_en":"Then the princess took the image of Shiva in her hand;","page":2109,"meaning_status":"draft","meaning_pa":"ਤਦ ਰਾਜ ਕੁਮਾਰੀ ਨੇ ਸ਼ਿਵ ਦੀ ਮੂਰਤੀ ਹੱਥ ਵਿਚ ਲੈ ਲਈ","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਹਸਿ ਹਸਿ ਕਰਿ ਦਿਜ ਕੇ ਮੁਖ ਕਸਿ ਕਸਿ ਕੈ ਦਈ।","roman":"Hasi hasi kari dij ke mukh kasi kasi kai daee |","meaning_en":"laughing and laughing, she thrust it again and again into the brahmin's mouth;","page":2109,"meaning_status":"draft","meaning_pa":"ਅਤੇ ਹਸ ਹਸ ਕੇ ਬ੍ਰਾਹਮਣ ਦੇ ਮੂੰਹ ਉਤੇ ਕਸ ਕਸ ਕੇ ਮਾਰੀ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਸਾਲਿਗ੍ਰਾਮ ਭੇ ਦਾਂਤਿ ਫੋਰਿ ਸਭ ਹੀ ਦੀਏ।","roman":"Saaligraam bhe daanti phori sabh hee dee'e |","meaning_en":"with the Shaligrams she broke all his teeth,","page":2109,"meaning_status":"draft","note":"ਸਾਲਿਗ੍ਰਾਮ ਭੇ: 'ਭੇ' read as 'with'; uncertain."},{"gurmukhi":"ਹੋ ਛੀਨਿ ਛਾਨਿ ਕਰਿ ਬਸਤ੍ਰ ਮਿਸ੍ਰ ਕੇ ਸਭ ਲੀਏ। ੧੦੯।","roman":"Ho chheeni chhaani kari basatr misr ke sabh lee'e | 109 |","meaning_en":"and snatching, she took away all the Mishra's clothes.","page":2109,"meaning_status":"draft","meaning_pa":"ਸਾਲਿਗ੍ਰਾਮ ਨਾਲ (ਬ੍ਰਾਹਮਣ ਦੇ) ਸਾਰੇ ਦੰਦ ਭੰਨ ਦਿੱਤੇ ਅਤੇ ਬ੍ਰਾਹਮਣ ਦੇ ਸਾਰੇ ਬਸਤ੍ਰ (ਅਤੇ ਦਰਬ) ਖੋਹ ਖਾਹ ਲਏ ॥੧੦੯॥","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"}]},{"type":"verse","number":[110],"number_text":"੧੧੦।","page":2109,"lines":[{"gurmukhi":"ਕਹੋ ਮਿਸ੍ਰ ਅਬ ਰੁਦ੍ਰ ਤਿਹਾਰੋ ਕਹ ਗਯੋ।","roman":"Kaho misr ab rudr tihaaro kah gayo |","meaning_en":"'Say, Mishra, where has your Rudra gone now,","page":2109,"meaning_status":"draft","meaning_pa":"(ਅਤੇ ਕਹਿਣ ਲਗੀ) ਹੇ ਬ੍ਰਾਹਮਣ! ਦਸ, ਹੁਣ ਤੇਰਾ ਸ਼ਿਵ ਕਿਥੇ ਗਿਆ ਹੈ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜਿਹ ਸੇਵਤ ਥੋ ਸਦਾ ਦਾਂਤਿ ਛੈ ਤਿਨ ਕਿਯੋ।","roman":"Jih sevat tho sadaa daanti chhai tin kiyo |","meaning_en":"whom you always served? He has made your teeth fall out.","page":2109,"meaning_status":"draft"},{"gurmukhi":"ਜਿਹ ਲਿੰਗਹਿ ਕੌ ਜਪਤੇ ਕਾਲ ਬਤਾਇਯੋ।","roman":"Jih linghi kau japte kaal bataaiyo |","meaning_en":"The lingam you used to mutter over told of Death;","page":2109,"meaning_status":"draft","meaning_pa":"ਜਿਸ ਨੂੰ (ਤੂੰ) ਸਦਾ ਪੂਜਦਾ ਸੈਂ, ਉਸ ਨੇ (ਤੇਰੇ) ਦੰਦ ਭੰਨ ਦਿੱਤੇ ਹਨ। ਜਿਸ ਲਿੰਗ ਦੀ ਪੂਜਾ ਕਰਦਿਆਂ (ਤੂੰ ਇਤਨਾ) ਸਮਾ ਬਿਤਾਇਆ ਹੈ,","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"},{"gurmukhi":"ਹੋ ਅੰਤ ਕਾਲ ਸੋ ਤੁਮਰੇ ਮੁਖ ਮਹਿ ਆਇਯੋ। ੧੧੦।","roman":"Ho ant kaal so tumre mukh mahi aaiyo | 110 |","meaning_en":"at the end that same Death has come into your mouth.'","page":2109,"meaning_status":"draft","note":"Lines .2 to .3 are obscure; read as printed; uncertain.","meaning_pa":"ਉਹੀ ਅੰਤ ਨੂੰ ਤੇਰੇ ਮੂੰਹ ਵਿਚ ਆਇਆ ਹੈ (ਅਰਥਾਤ ਤੇਰੇ ਮੂੰਹ ਉਤੇ ਆ ਕੇ ਵਜਿਆ ਹੈ) ॥੧੧੦॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2109,"meaning_status":"draft","meaning_pa":"ਚੌਪਈ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[111],"number_text":"੧੧੧।","page":2109,"lines":[{"gurmukhi":"ਤਾ ਕੋ ਦਰਬੁ ਛੀਨਿ ਜੋ ਲਿਯੋ। ਜੋ ਸਭ ਦਾਨ ਦਿਜਨ ਕਰਿ ਦਿਯੋ।","roman":"Taa ko darbu chheeni jo liyo | jo sabh daan dijan kari diyo |","meaning_en":"Whatever wealth of his she had snatched, all of which he had given in gifts to brahmins,","page":2109,"meaning_status":"draft","note":"Who gave and who snatched is unclear in the text; translated as printed.","meaning_pa":"ਉਸ (ਬ੍ਰਾਹਮਣ) ਦਾ ਜੋ ਦਰਬ (ਦੌਲਤ) ਧਨ ਖੋਹਿਆ ਸੀ, ਉਹ ਸਭ ਬ੍ਰਾਹਮਣਾ ਨੂੰ ਦਾਨ ਕਰ ਦਿੱਤਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਕਹਿਯੋ ਮਿਸ੍ਰ ਕਛੁ ਚਿੰਤ ਨ ਕਰਹੂੰ। ਦਾਨ ਦਸ ਗੁਨੋ ਅਗੈ ਫਰਹੂੰ। ੧੧੧।","roman":"Kahiyo misr kachhu chint na karhoon | daan das guno agai pharhoon | 111 |","meaning_en":"Mishra said: 'Do not worry at all; the gift will bear fruit ten-fold ahead.'","page":2109,"meaning_status":"draft","meaning_pa":"ਅਤੇ ਕਿਹਾ ਹੇ ਬ੍ਰਾਹਮਣ! (ਧਨ ਦੀ) ਕੁਝ ਵੀ ਚਿੰਤਾ ਨਾ ਕਰੋ (ਕਿਉਾਂਕਿ) ਅਗਲੇ ਜਨਮ ਵਿਚ ਇਹ ਦਸ ਗੁਣਾ ਹੋ ਕੇ ਫਲੇਗਾ ॥੧੧੧॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"Kabitt.","page":2109,"meaning_status":"draft","meaning_pa":"ਕਬਿੱਤ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[112],"number_text":"੧੧੨।","page":2109,"lines":[{"gurmukhi":"ਔਰਨ ਕੋ ਕਹਤ ਲੁਟਾਵੋ ਤੁਮ ਖਾਹੁ ਧਨ ਆਪੁ","roman":"Auran ko kahat lutaavo tum khaahu dhan aapu","meaning_en":"To others you say 'squander it', while you yourself eat the wealth;","page":2109,"meaning_status":"draft"},{"gurmukhi":"ਪਹਿਤੀ ਮੈ ਡਾਰਿ ਖਾਤ ਨ ਬਿਸਾਰ ਹੈਂ।","roman":"Pahitee mai daari khaat na bisaar hain |","meaning_en":"putting it into their pouch they eat, and do not forget.","page":2109,"meaning_status":"draft","note":"ਪਹਿਤੀ: read as 'pouch/bundle'; uncertain.","meaning_pa":"ਹੋਰਨਾ ਨੂੰ ਕਹਿੰਦੇ ਹਨ ਕਿ ਤੁਸੀਂ ਖੂਬ ਧਨ ਲੁਟਾਓ, ਪਰ ਆਪ ਧਨ ਨੂੰ ਖਾਉਾਂਦੇ ਹਨ (ਅਰਥਾਤ-ਮੌਜ ਨਾਲ ਵਰਤਦੇ ਹਨ) (ਅਤੇ ਕੰਜੂਸ ਇਤਨੇ ਹਨ ਕਿ) ਦਾਲ ('ਪਹਿਤੀ') ਵਿਚ ਹਲਦੀ ('ਬਿਸਾਰ') ਪਾ ਕੇ ਨਹੀਂ ਖਾਉਾਂਦੇ।","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"},{"gurmukhi":"ਬਡੇ ਹੀ ਪ੍ਰਪੰਚੀ ਪਰਪਚੰਨ ਕੋ ਲੀਏ ਫਿਰੈ","roman":"Bade hee prapanchee parapchann ko lee'e phirai","meaning_en":"They go about carrying great schemes and deceits,","page":2109,"meaning_status":"draft"},{"gurmukhi":"ਦਿਨ ਹੀ ਮੈ ਲੋਗਨ ਕੋ ਲੂਟਤ ਬਜਾਰ ਹੈਂ।","roman":"Din hee mai logan ko lootat bajaar hain |","meaning_en":"and in broad day they loot people in the bazaar.","page":2109,"meaning_status":"draft","meaning_pa":"ਬਹੁਤ ਵੱਡੇ ਪ੍ਰਪੰਚੀ ਹਨ ਅਤੇ ਪ੍ਰਪੰਚਾ (ਪਾਖੰਡਾ) ਦਾ ਹੀ ਪ੍ਰਦਰਸ਼ਨ ਕਰਦੇ ਫਿਰਦੇ ਹਨ ਅਤੇ ਦਿਨ ਵਿਚ ਹੀ ਲੋਕਾ ਨੂੰ ਬਾਜ਼ਾਰ ਵਿਚ ਲੁਟ ਲੈਂਦੇ ਹਨ।","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"},{"gurmukhi":"ਹਾਥ ਤੇ ਨ ਕੌਡੀ ਦੇਤ ਕੌਡੀ ਕੌਡੀ ਮਾਂਗ ਲੇਤ","roman":"Haath te na kaudee det kaudee kaudee maang let","meaning_en":"They give not a cowrie from their hand, and beg cowrie by cowrie;","page":2109,"meaning_status":"draft"},{"gurmukhi":"ਪੁਤ੍ਰੀ ਕਹਤ ਤਾ ਸੋ ਕਰੈ ਬਿਭਚਾਰ ਹੈਂ।","roman":"Putree kahat taa so karai bibhchaar hain |","meaning_en":"calling her daughter, they commit adultery with her.","page":2109,"meaning_status":"draft","meaning_pa":"ਹੱਥੋਂ ਕੌਡੀ ਨਹੀਂ ਦਿੰਦੇ, (ਪਰ ਸਭ ਤੋਂ) ਕੌਡੀ ਕੌਡੀ ਮੰਗ ਲੈਂਦੇ ਹਨ। (ਜਿਸ ਨੂੰ) ਪੁੱਤਰੀ ਕਹਿੰਦੇ ਹਨ, ਉਸ ਨਾਲ ਵਿਭਚਾਰ ਕਰਦੇ ਹਨ।","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"},{"gurmukhi":"ਲੋਭਤਾ ਕੇ ਜਏ ਹੈਂ ਕਿ ਮਮਤਾ ਕੇ ਭਏ ਹੈਂ","roman":"Lobhtaa ke jae hain ki mamtaa ke bhae hain","meaning_en":"Are they born of greed, or of attachment?","page":2109,"meaning_status":"draft"},{"gurmukhi":"ਏ ਸੂਮਤਾ ਕੇ ਪੁਤ੍ਰ ਕੈਧੌ ਦਰਿਦ੍ਰਾਵਤਾਰ ਹੈਂ। ੧੧੨।","roman":"E soomtaa ke putr kaidhau daridraavtaar hain | 112 |","meaning_en":"They are sons of miserliness, or else incarnations of poverty.","page":2109,"meaning_status":"draft","meaning_pa":"(ਇਸ ਤਰ੍ਰਹਾ ਇਹ) ਲੋਭ ਦੇ ਪੈਦਾ ਕੀਤੇ ਹੋਏ ਸੁਆਰਥੀ ਬਣੇ ਫਿਰਦੇ ਹਨ। (ਇਹ) ਕੰਜੂਸੀ ਦੇ ਪੁੱਤਰ ਜਾ ਦਰਿਦ੍ਰਤਾ ਦੇ ਅਵਤਾਰ ਹਨ ॥੧੧੨॥","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2111,"meaning_status":"draft","meaning_pa":"ਚੌਪਈ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[113],"number_text":"੧੧੩।","page":2111,"lines":[{"gurmukhi":"ਪਹਤੀ ਬਿਖੈ ਬਿਸਾਰ ਨ ਡਾਰਹਿ। ਔਰਨ ਪਾਸ ਗਾਲ ਕੋ ਮਾਰਹਿ।","roman":"Pahtee bikhai bisaar na daarhi | auran paas gaal ko maarhi |","meaning_en":"They do not neglect to put it into the pouch, and before others they boast;","page":2111,"meaning_status":"draft","note":"ਪਹਤੀ: as 'ਪਹਿਤੀ' above, read as 'pouch'; uncertain.","meaning_pa":"(ਆਪ ਤਾ) ਦਾਲ ਵਿਚ ਹਲਦੀ ਨਹੀਂ ਪਾਉਾਂਦੇ, ਪਰ ਹੋਰਨਾ ਪਾਸ ਸ਼ੇਖੀ ਮਾਰਦੇ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜਨਿਯਤ ਕਿਸੀ ਦੇਸ ਕੇ ਰਾਜਾ। ਕੌਡੀ ਕੇ ਆਵਤ ਨਹਿ ਕਾਜਾ। ੧੧੩।","roman":"Janiyat kisee des ke raajaa | kaudee ke aavat nahi kaajaa | 113 |","meaning_en":"they are known as kings of some country, yet are of no use even for a cowrie.","page":2111,"meaning_status":"draft","meaning_pa":"ਲਗਦੇ ਤਾ ਕਿਸੇ ਦੇਸ਼ ਦੇ ਰਾਜੇ ਹਨ, ਪਰ ਕੌਡੀ ਦੇ ਕੰਮ ਵੀ ਨਹੀਂ ਆਉਾਂਦੇ ॥੧੧੩॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[114],"number_text":"੧੧੪।","page":2111,"lines":[{"gurmukhi":"ਜੌ ਇਨ ਮੰਤ੍ਰ ਜੰਤ੍ਰ ਸਿਧਿ ਹੋਈ। ਦਰ ਦਰ ਭੀਖਿ ਨ ਮਾਂਗੈ ਕੋਈ।","roman":"Jau in mantr jantr sidhi hoee | dar dar bheekhi na maangai koee |","meaning_en":"If these had success in mantra and yantra, no one would beg for alms from door to door;","page":2111,"meaning_status":"draft","meaning_pa":"ਜੇ ਇਨ੍ਰਹਾ ਮੰਤ੍ਰਾ ਜੰਤ੍ਰਾ ਤੋਂ ਸਿੱਧੀ ਪ੍ਰਾਪਤ ਹੁੰਦੀ, ਤਾ ਕੋਈ ਦਰ ਦਰ ਭਿਖ ਨਾ ਮੰਗਦਾ ਫਿਰਦਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਏਕੈ ਮੁਖ ਤੇ ਮੰਤ੍ਰ ਉਚਾਰੈ। ਧਨ ਸੌ ਸਕਲ ਧਾਮ ਭਰਿ ਡਾਰੈ। ੧੧੪।","roman":"Ekai mukh te mantr uchaarai | dhan sau sakal dhaam bhari daarai | 114 |","meaning_en":"from the mouth alone they would utter a mantra and fill all houses with wealth.","page":2111,"meaning_status":"draft","meaning_pa":"ਮੁਖ ਤੋਂ ਇਕੋ ਮੰਤ੍ਰ ਉਚਾਰਨ ਕਰ ਕੇ ਸਾਰੇ ਘਰ ਨੂੰ ਧਨ ਨਾਲ ਭਰ ਲੈਂਦੇ ਹਨ ॥੧੧੪॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[115],"number_text":"੧੧੫।","page":2111,"lines":[{"gurmukhi":"ਰਾਮ ਕ੍ਰਿਸਨ ਏ ਜਿਨੈ ਬਖਾਨੈ। ਸਿਵ ਬ੍ਰਹਮਾ ਏ ਜਾਹਿ ਪ੍ਰਮਾਨੈ।","roman":"Raam krisan e jinai bakhaanai | siv brahmaa e jaahi pramaanai |","meaning_en":"Those whom they call Ram and Krishna, whom they take to be Shiva and Brahma,","page":2111,"meaning_status":"draft","meaning_pa":"ਰਾਮ, ਕ੍ਰਿਸ਼ਨ, ਇਹ ਜਿਤਨੇ ਹੀ ਦਸੇ ਜਾਦੇ ਹਨ ਸ਼ਿਵ, ਬ੍ਰਹਮਾ ਆਦਿ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਤੇ ਸਭ ਹੀ ਸ੍ਰੀ ਕਾਲ ਸੰਘਾਰੇ। ਕਾਲ ਪਾਇ ਕੈ ਬਹੁਰਿ ਸਵਾਰੇ। ੧੧੫।","roman":"Te sabh hee sree kaal sanghaare | kaal paai kai bahuri savaare | 115 |","meaning_en":"all of them Sri Kal destroyed, and when the time came, adorned them again.","page":2111,"meaning_status":"draft","meaning_pa":"ਉਨ੍ਰਹਾ ਸਭ ਨੂੰ ਕਾਲ ਨੇ ਮਾਰ ਦਿੱਤਾ ਹੈ ਅਤੇ ਕਾਲ ਨੇ ਹੀ ਉਨ੍ਰਹਾ ਨੂੰ ਫਿਰ ਸਾਜਿਆ ਹੈ ॥੧੧੫॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[116],"number_text":"੧੧੬।","page":2111,"lines":[{"gurmukhi":"ਕੇਤੇ ਰਾਮਚੰਦ ਅਰੁ ਕ੍ਰਿਸਨਾ। ਕੇਤੇ ਚਤੁਰਾਨਨ ਸਿਵ ਬਿਸਨਾ।","roman":"Kete raamchand aru krisnaa | kete chaturaanan siv bisnaa |","meaning_en":"Many Ramchandras and Krishnas, many four-faced Brahmas, Shivas and Vishnus;","page":2111,"meaning_status":"draft","meaning_pa":"ਕਿਤਨੇ ਹੀ ਰਾਮ ਚੰਦ੍ਰ, ਕ੍ਰਿਸ਼ਨ, ਬ੍ਰਹਮਾ, ਸ਼ਿਵ ਅਤੇ ਵਿਸ਼ਣੂ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਚੰਦ ਸੂਰਜ ਏ ਕਵਨ ਬਿਚਾਰੇ। ਪਾਨੀ ਭਰਤ ਕਾਲ ਕੇ ਦ੍ਵਾਰੇ। ੧੧੬।","roman":"Chand sooraj e kavan bichaare | paanee bharat kaal ke dvaare | 116 |","meaning_en":"who are these poor moon and sun? They draw water at the door of Death.","page":2111,"meaning_status":"draft","meaning_pa":"ਚੰਦ੍ਰਮਾ ਅਤੇ ਸੂਰਜ ਵਿਚਾਰੇ ਕੀ ਹਨ। ਇਹ ਸਾਰੇ ਕਾਲ ਦੇ ਦੁਆਰ ਉਤੇ ਪਾਣੀ ਭਰਦੇ ਹਨ ॥੧੧੬॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[117],"number_text":"੧੧੭।","page":2111,"lines":[{"gurmukhi":"ਕਾਲ ਪਾਇ ਸਭ ਹੀ ਏ ਭਏ। ਕਾਲੋ ਪਾਇ ਕਾਲ ਹ੍ਵੈ ਗਏ।","roman":"Kaal paai sabh hee e bhae | kaalo paai kaal hvai gae |","meaning_en":"By Time all these came to be; and by Time they became dead.","page":2111,"meaning_status":"draft","meaning_pa":"ਕਾਲ ਦੇ ਪ੍ਰਾਪਤ ਹੋਣ ਤੇ ਹੀ ਇਹ ਸਭ ਹੋਂਦ ਵਿਚ ਆਏ ਅਤੇ ਕਾਲ ਦੇ ਪ੍ਰਾਪਤ ਹੋਣ ਤੇ ਇਹ ਕਾਲ-ਵਸ ਹੋ ਗਏ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਕਾਲਹਿ ਪਾਇ ਬਹੁਰਿ ਅਵਤਰਿ ਹੈ। ਕਾਲਹਿ ਕਾਲ ਪਾਇ ਸੰਘਰਿ ਹੈ। ੧੧੭।","roman":"Kaalhi paai bahuri avatri hai | kaalhi kaal paai sanghri hai | 117 |","meaning_en":"By Time they will incarnate again, and by Time they will be destroyed.","page":2111,"meaning_status":"draft","meaning_pa":"ਕਾਲ ਦੇ ਪ੍ਰਾਪਤ ਹੋਣ ਤੇ ਫਿਰ ਪ੍ਰਗਟ ਹੁੰਦੇ ਹਨ। ਕਾਲ ਦੇ ਪ੍ਰਾਪਤ ਹੋਣ ਤੇ ਫਿਰ ਕਾਲ ਦੁਆਰਾ ਮਾਰੇ ਜਾਦੇ ਹਨ ॥੧੧੭॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2111,"meaning_status":"draft","meaning_pa":"ਦੋਹਰਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[118],"number_text":"੧੧੮।","page":2111,"lines":[{"gurmukhi":"ਸ੍ਰਾਪ ਰਾਛਸੀ ਕੇ ਦਏ ਜੋ ਭਯੋ ਪਾਹਨ ਜਾਇ।","roman":"Sraap raachhsee ke dae jo bhayo paahan jaai |","meaning_en":"One who by the curse of a she-demon went and became a stone,","page":2111,"meaning_status":"draft","meaning_pa":"(ਇਕ) ਰਾਖਸ਼ੀ ਦੇ ਸ੍ਰਾਪ ਦੇਣ ਤੇ ਜੋ ਪੱਥਰ ਬਣ ਜਾਦਾ ਹੈ,","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਤਾਹਿ ਕਹਤ ਪਰਮੇਸ੍ਰ ਤੈ ਮਨ ਮਹਿ ਨਹੀ ਲਜਾਇ। ੧੧੮।","roman":"Taahi kahat parmesr tai man mahi nahee lajaai | 118 |","meaning_en":"you call him the Supreme Lord; you have no shame in your mind.","page":2111,"meaning_status":"draft","meaning_pa":"ਉਸ ਨੂੰ ਪਰਮੇਸ਼੍ਵਰ ਕਹਿੰਦਿਆਂ (ਇਹ) ਮਨ ਵਿਚ ਨਹੀਂ ਲਜਾਉਾਂਦੇ ॥੧੧੮॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"speaker","name":"ਦਿਜ ਬਾਚ","gurmukhi":"ਦਿਜ ਬਾਚ","roman":"Dij baach","meaning_en":"The brahmin said:","page":2111,"meaning_status":"draft","note":"Printed so; the following verse is narration.","meaning_pa":"ਬ੍ਰਾਹਮਣ ਨੇ ਕਿਹਾ:","meaning_pa_source":"BaniDB"},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2111,"meaning_status":"draft","meaning_pa":"ਚੌਪਈ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[119],"number_text":"੧੧੯।","page":2111,"lines":[{"gurmukhi":"ਤਬ ਦਿਜ ਅਧਿਕ ਕੋਪ ਹ੍ਵੈ ਗਯੋ। ਭਰਭਰਾਇ ਠਾਢਾ ਉਠਿ ਭਯੋ।","roman":"Tab dij adhik kop hvai gayo | bharabhraai thaadhaa uthi bhayo |","meaning_en":"Then the brahmin became very angry, and trembling stood up.","page":2111,"meaning_status":"draft","meaning_pa":"ਤਦ ਬ੍ਰਾਹਮਣ ਬਹੁਤ ਕ੍ਰੋਧਵਾਨ ਹੋ ਗਿਆ ਅਤੇ ਘਬਰਾ ('ਭਰਭਰਾਇ') ਕੇ ਉਠ ਖੜੋਤਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਅਬ ਮੈ ਇਹ ਰਾਜਾ ਪੈ ਜੈਹੌ। ਤਹੀ ਬਾਂਧਿ ਕਰਿ ਤੋਹਿ ਮੰਗੈ ਹੌ। ੧੧੯।","roman":"Ab mai ih raajaa pai jaihau | tahee baandhi kari tohi mangai hau | 119 |","meaning_en":"'Now I will go to this king, and there I will have you summoned bound.'","page":2111,"meaning_status":"draft","meaning_pa":"(ਅਤੇ ਕਹਿਣ ਲਗਿਆ) ਹੁਣ ਮੈਂ ਇਸ ਰਾਜੇ ਕੋਲ ਜਾਦਾ ਹਾ ਅਤੇ ਤੈਨੂੰ ਬੰਨ੍ਰਹਵਾ ਕੇ ਉਥੇ ਹੀ ਮੰਗਵਾਉਾਂਦਾ ਹਾ ॥੧੧੯॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"speaker","name":"ਕੁਅਰਿ ਬਾਚ","gurmukhi":"ਕੁਅਰਿ ਬਾਚ","roman":"Kuari baach","meaning_en":"The princess said:","page":2111,"meaning_status":"draft","meaning_pa":"ਰਾਜ ਕੁਮਾਰੀ ਨੇ ਕਿਹਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[120],"number_text":"੧੨੦।","page":2111,"lines":[{"gurmukhi":"ਤਬ ਤਿਨ ਕੁਅਰਿ ਦਿਜਹਿ ਗਹਿ ਲਿਆ। ਡਾਰ ਨਦੀ ਕੇ ਭੀਤਰ ਦਿਯਾ।","roman":"Tab tin kuari dijhi gahi liaa | daar nadee ke bheetar diyaa |","meaning_en":"Then the princess seized the brahmin and threw him into the river;","page":2111,"meaning_status":"draft","meaning_pa":"ਤਦ ਉਸ ਰਾਜ ਕੁਮਾਰੀ ਨੇ ਬ੍ਰਾਹਮਣ ਨੂੰ ਪਕੜ ਲਿਆ ਅਤੇ ਨਦੀ ਵਿਚ ਸੁਟ ਦਿੱਤਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਗੋਤਾ ਪਕਰਿ ਆਠ ਸੈ ਦੀਨਾ। ਤਾਹਿ ਪਵਿਤ੍ਰ ਭਲੀ ਬਿਧਿ ਕੀਨਾ। ੧੨੦।","roman":"Gotaa pakri aath sai deenaa | taahi pavitr bhalee bidhi keenaa | 120 |","meaning_en":"holding him, she gave him eight hundred dips, and made him pure in a fine way.","page":2111,"meaning_status":"draft","meaning_pa":"(ਉਸ ਨੂੰ) ਪਕੜ ਕੇ ਅੱਠ ਸੌ ਗ਼ੋਤੇ ਦਿੱਤੇ ਅਤੇ ਉਸ ਨੂੰ ਚੰਗੀ ਤਰ੍ਰਹਾ ਨਾਲ ਪਵਿਤ੍ਰ ਕੀਤਾ ॥੧੨੦॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[121],"number_text":"੧੨੧।","page":2111,"lines":[{"gurmukhi":"ਕਹੀ ਕੁਅਰਿ ਪਿਤੁ ਪਹਿ ਮੈ ਜੈ ਹੌ। ਤੈ ਮੁਹਿ ਡਾਰਾ ਹਾਥ ਬਤੈ ਹੌ।","roman":"Kahee kuari pitu pahi mai jai hau | tai muhi daaraa haath batai hau |","meaning_en":"The princess said: 'I will go to my father and say that you laid your hand on me;","page":2111,"meaning_status":"draft","meaning_pa":"ਰਾਜ ਕੁਮਾਰੀ ਕਹਿਣ ਲਗੀ ਕਿ ਮੈਂ ਪਿਤਾ ਕੋਲ ਜਾਵਾਗੀ ਅਤੇ ਦਸਾਗੀ ਕਿ ਤੂੰ ਮੈਨੂੰ ਹੱਥ ਪਾਇਆ ਹੈ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਤੇਰੇ ਦੋਨੋ ਹਾਥ ਕਟਾਊ। ਤੌ ਰਾਜਾ ਕੀ ਸੁਤਾ ਕਹਾਊ। ੧੨੧।","roman":"Tere dono haath kataaoo | tau raajaa kee sutaa kahaaoo | 121 |","meaning_en":"I will have both your hands cut off, and only then will I be called the king's daughter.'","page":2111,"meaning_status":"draft","meaning_pa":"ਤੇਰੇ ਦੋਵੇਾਂ ਹੱਥ ਕਟਵਾਵਾਗੀ। ਤਦ ਹੀ ਰਾਜੇ ਦੀ ਪੁੱਤਰੀ ਅਖਵਾਵਾਗੀ ॥੧੨੧॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"speaker","name":"ਦਿਜ ਬਾਚ","gurmukhi":"ਦਿਜ ਬਾਚ","roman":"Dij baach","meaning_en":"The brahmin said:","page":2111,"meaning_status":"draft"},{"type":"verse","number":[122],"number_text":"੧੨੨।","page":2111,"lines":[{"gurmukhi":"ਇਹ ਸੁਨਿ ਬਾਤ ਮਿਸ੍ਰ ਡਰ ਪਯੋ। ਲਾਗਤ ਪਾਇ ਕੁਅਰਿ ਕੇ ਭਯੋ।","roman":"Ih suni baat misr dar payo | laagat paai kuari ke bhayo |","meaning_en":"Hearing this, the Mishra was afraid and fell at the princess's feet.","page":2111,"meaning_status":"draft","meaning_pa":"ਬ੍ਰਾਹਮਣ ਨੇ ਕਿਹਾ: ਇਹ ਗੱਲ ਸੁਣ ਕੇ ਬ੍ਰਾਹਮਣ ਡਰ ਗਿਆ ਅਤੇ ਰਾਜ ਕੁਮਾਰੀ ਦੇ ਪੈਰੀਂ ਪੈ ਗਿਆ।","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"},{"gurmukhi":"ਸੋਊ ਕਰੋ ਜੁ ਮੋਹਿ ਉਚਾਰੋ। ਤੁਮ ਨਿਜੁ ਜਿਯ ਤੇ ਕੋਪ ਨਿਵਾਰੋ। ੧੨੨।","roman":"So'oo karo ju mohi uchaaro | tum niju jiy te kop nivaaro | 122 |","meaning_en":"'Do whatever you tell me; put away the anger from your heart.'","page":2111,"meaning_status":"draft","meaning_pa":"(ਕਹਿਣ ਲਗਿਆ ਕਿ ਮੈਂ) ਉਹੀ ਕਰਾਗਾ ਜੋ (ਤੂੰ) ਮੈਨੂੰ ਕਹੇਾਂਗੀ। ਤੂੰ ਆਪਣੇ ਮਨ ਤੋਂ ਕ੍ਰੋਧ ਦੂਰ ਕਰ ਦੇ ॥੧੨੨॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"speaker","name":"ਕੁਅਰਿ ਬਾਚ","gurmukhi":"ਕੁਅਰਿ ਬਾਚ","roman":"Kuari baach","meaning_en":"The princess said:","page":2113,"meaning_status":"draft","meaning_pa":"ਰਾਜ ਕੁਮਾਰੀ ਨੇ ਕਿਹਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[123],"number_text":"੧੨੩।","page":2113,"lines":[{"gurmukhi":"ਤੁਮ ਕਹਿਯਹੁ ਮੈ ਪ੍ਰਥਮ ਅਨਾਯੋ। ਧਨ ਨਿਮਿਤਿ ਮੈ ਦਰਬੁ ਲੁਟਾਯੋ।","roman":"Tum kahiyhu mai pratham anaayo | dhan nimiti mai darbu lutaayo |","meaning_en":"'You must say: 'I first brought it wrongly; for the sake of wealth I plundered wealth.'","page":2113,"meaning_status":"draft","note":"ਅਨਾਯੋ: read as 'brought'; uncertain.","meaning_pa":"ਤੂੰ ਕਹੀਂ ਕਿ (ਮੈਂ) ਪਹਿਲਾ ਇਸ਼ਨਾਨ ਕੀਤਾ ਹੈ ਅਤੇ (ਅਗਲੇ ਜਨਮ ਵਿਚ ਅਧਿਕ) ਧਨ ਪ੍ਰਾਪਤ ਕਰਨ ਲਈ ਦਰਬ ਲੁਟਾਇਆ ਹੈ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਪਾਹਨ ਕੀ ਪੂਜਾ ਨਹਿ ਕਰਿਯੈ। ਮਹਾ ਕਾਲ ਕੇ ਪਾਇਨ ਪਰਿਯੈ। ੧੨੩।","roman":"Paahan kee poojaa nahi kariyai | mahaa kaal ke paain pariyai | 123 |","meaning_en":"Stone should not be worshipped; fall at the feet of Mahakal.'","page":2113,"meaning_status":"draft","meaning_pa":"(ਤੂੰ ਹੁਣ) ਪੱਥਰ ਦੀ ਪੂਜਾ ਨਹੀਂ ਕਰੇਾਂਗਾ ਅਤੇ ਮਹਾ ਕਾਲ ਦੇ ਚਰਨੀਂ ਲਗੇਾਂਗਾ ॥੧੨੩॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"speaker","name":"ਕਬਿਯੋ ਬਾਚ","gurmukhi":"ਕਬਿਯੋ ਬਾਚ","roman":"Kabiyo baach","meaning_en":"The poet said:","page":2113,"meaning_status":"draft","note":"Printed ਕਬਿਯੋ ਬਾਚ (kabiyo bach).","meaning_pa":"ਕਵੀ ਦਾ ਕਥਨ ਹੈ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[124],"number_text":"੧੨੪।","page":2113,"lines":[{"gurmukhi":"ਤਬ ਦਿਜ ਮਹਾ ਕਾਲ ਕੋ ਧ੍ਯਾਯੋ। ਸਰਿਤਾ ਮਹਿ ਪਾਹਨਨ ਬਹਾਯੋ।","roman":"Tab dij mahaa kaal ko dhyaayo | saritaa mahi paahnan bahaayo |","meaning_en":"Then the brahmin meditated on Mahakal, and floated the stones away in the river;","page":2113,"meaning_status":"draft","meaning_pa":"ਤਦ ਬ੍ਰਾਹਮਣ ਨੇ ਮਹਾ ਕਾਲ ਦੀ ਪੂਜਾ ਕੀਤੀ ਅਤੇ ਪੱਥਰ (ਸਾਲਿਗ੍ਰਾਮ) ਨੂੰ ਨਦੀ ਵਿਚ ਵਹਾ ਦਿੱਤਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਦੂਜੇ ਕਾਨ ਨ ਕਿਨਹੂੰ ਜਾਨਾ। ਕਹਾ ਮਿਸ੍ਰ ਪਰ ਹਾਲ ਬਿਹਾਨਾ। ੧੨੪।","roman":"Dooje kaan na kinhoon jaanaa | kahaa misr par haal bihaanaa | 124 |","meaning_en":"no other ear learned it, nor what condition had befallen the Mishra.","page":2113,"meaning_status":"draft","meaning_pa":"ਦੂਜੇ ਕੰਨ ਤਕ ਕਿਸੇ ਨੇ ਨਾ ਜਾਣਿਆ ਕਿ ਬ੍ਰਾਹਮਣ ਉਤੇ ਕੀ ਬੀਤੀ ਹੈ ॥੧੨੪॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2113,"meaning_status":"draft","meaning_pa":"ਦੋਹਰਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[125,1],"number_text":"੧੨੫। ੧।","page":2113,"lines":[{"gurmukhi":"ਇਹ ਛਲ ਸੌ ਮਿਸਰਹਿ ਛਲਾ ਪਾਹਨ ਦਏ ਬਹਾਇ।","roman":"Ih chhal sau misarhi chhalaa paahan dae bahaai |","meaning_en":"By this trick she tricked the Mishra, and had the stones floated away;","page":2113,"meaning_status":"draft","meaning_pa":"ਇਸ ਛਲ ਨਾਲ (ਰਾਜ ਕੁਮਾਰੀ ਨੇ) ਬ੍ਰਾਹਮਣ ਨੂੰ ਛਲ ਲਿਆ ਅਤੇ ਪੱਥਰ ਨੂੰ ਰੋੜ ਦਿੱਤਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਮਹਾ ਕਾਲ ਕੋ ਸਿਖ੍ਯ ਕਰਿ ਮਦਰਾ ਭਾਂਗ ਪਿਵਾਇ। ੧੨੫। ੧।","roman":"Mahaa kaal ko sikhy kari madraa bhaang pivaai | 125 | 1 |","meaning_en":"she made him a disciple of Mahakal, and made him drink wine and bhang.","page":2113,"meaning_status":"draft"}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ਸ੍ਰੀ ਚਰਿਤ੍ਰ ਪਖ੍ਯਾਨੇ ਤ੍ਰਿਯਾ ਚਰਿਤ੍ਰੇ ਮੰਤ੍ਰੀ ਭੂਪ ਸੰਬਾਦੇ ਦੋਇ ਸੌ ਛਿਆਸਠਿ ਚਰਿਤ੍ਰ ਸਮਾਪਤਮ","roman":"Iti sree charitr pakhyaane triyaa charitre mantree bhoop sanbaade doi sau chhiaasthi charitr samaaptam","meaning_en":"Thus ends the two hundred and sixty-sixth charitra of the Charitropakhyan, of the wiles of women, in the dialogue of the minister and the king; complete.","page":2113,"meaning_status":"draft","note":"Printed ਤ੍ਰਿਯਾ ਚਰਿਤ੍ਰੇ (wiles of women)."},{"gurmukhi":"ਸਤੁ ਸੁਭਮ ਸਤੁ। ੨੬੬। ੫੧੯੫। ਅਫਜੂੰ।","roman":"Satu subham satu | 266 | 5195 | aphjoon |","meaning_en":"True, auspicious, true. 266. 5195. It continues.","page":2113,"meaning_status":"draft","note":"Printed ਸਤੁ ਸੁਭਮ ਸਤੁ ('sat subham sat'); ਅਫਜੂੰ read as 'it continues'.","meaning_pa":"(ਉਸ ਨੂੰ) ਸ਼ਰਾਬ ਅਤੇ ਭੰਗ ਪਿਆ ਕੇ ਮਹਾ ਕਾਲ ਦਾ ਸੇਵਕ ਬਣਾ ਦਿੱਤਾ ॥੧੨੫॥ ਇਥੇ ਸ੍ਰੀ ਚਰਿਤ੍ਰੋਪਾਖਿਆਨ ਦੇ ਤ੍ਰੀਆ ਚਰਿਤ੍ਰ ਦੇ ਮੰਤ੍ਰੀ ਭੂਪ ਸੰਬਾਦ ਦੇ ੨੬੬ਵੇਾਂ ਚਰਿਤ੍ਰ ਦੀ ਸਮਾਪਤੀ, ਸਭ ਸ਼ੁਭ ਹੈ ॥੨੬੬॥੫੧੯੫॥ ਚਲਦਾ॥","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 3 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"}],"page":2113,"number":[266,5195]}});
